program native_compiler

use vm.core.convert
use std.compiler.nox.job
use std.compiler.nox.syntax
use std.compiler.nox.package_compile
use std.compiler.nox.emit

#[pure]
fn main(input: Noun) -> Noun {
    let request = job.read(input)
    if (request.error.code == as_u32(0)) == false { return emit.failure(input, request.index, request.error) }
    let compiled = package_compile.compile(request)
    if (compiled.error.code == as_u32(0)) == false { return emit.failure(input, compiled.index, compiled.error) }
    emit.success_profile(input, compiled.formula, request.profile)
}

sources.std.compiler.nox.aggregate_gen:
module std.compiler.nox.aggregate_gen

use vm.nox.noun
use vm.core.convert
use std.nox.seq
use std.compiler.nox.formula
use std.compiler.nox.flow

// Links run backward. Wrapping each component before the accumulated suffix
// produces a cons-list preserving whole values in the caller's chosen order.
// Tuples admit16 components; records admit0..32 fields in declaration order.
#[pure]
#[requires(count < as_u32(33))]
pub fn generate(values: seq.Seq, arguments: seq.Seq, head: U32, count: U32) -> formula.Value {
    let mut result = flow.literal(0)
    let mut cursor = head
    for i in 0..32 {
        if i == count { return result }
        let link = seq.get(arguments, cursor)
        let value = formula.value(values, as_u32(noun.as_field(noun.head(link))))
        result = flow.cons(value, result)
        cursor = as_u32(noun.as_field(noun.tail(link)))
    }
    result
}

sources.std.compiler.nox.array_gen:
module std.compiler.nox.array_gen

use vm.nox.noun
use vm.core.convert
use std.nox.seq
use std.nox.tree
use std.compiler.nox.syntax
use std.compiler.nox.formula
use std.compiler.nox.flow

struct Values { output: formula.Value, head: U32, remaining: U32 }

#[pure]
fn chunk(values: seq.Seq, arguments: seq.Seq, input: Values) -> Values {
    let mut s = input
    for turn in 0..8 {
        if s.remaining == syntax.ZERO { return s }
        let link = seq.get(arguments, s.head)
        s.output = flow.cons(formula.value(values, as_u32(noun.as_field(noun.head(link)))), s.output)
        s.head = as_u32(noun.as_field(noun.tail(link)))
        s.remaining = syntax.dec(s.remaining)
    }
    s
}

// Reversed owned links become a zero-ended list, evaluated in source order.
#[pure]
#[requires((syntax.TABLE_CAP < count) == false)]
pub fn values(values: seq.Seq, arguments: seq.Seq, head: U32, count: U32) -> formula.Value {
    let mut s = Values { output: flow.literal(0), head, remaining: count }
    for block in 0..512 {
        s = chunk(values, arguments, s)
        if s.remaining == syntax.ZERO { return s.output }
    }
    s.output
}

#[pure]
fn binary(opcode: Field, a: formula.Value, b: formula.Value) -> formula.Value {
    formula.Value { formula: noun.pair(noun.atom(opcode), noun.pair(a.formula, b.formula)),
        depth: as_u32(as_field(formula.maximum(a.depth, b.depth)) + 2) }
}

#[pure]
fn subject(base: formula.Value, index: formula.Value) -> formula.Value {
    flow.cons(flow.axis(2), flow.cons(flow.literal(0), flow.cons(base, index)))
}

// Shared private Get subject: [table [0 [list index]]]. Caller checks length;
// each recursive dispatch consumes one list cell and decrements a positive index.
#[pure]
pub fn helper(table: tree.Shape, slot: U32) -> formula.Value {
    let next = subject(flow.axis(29), binary(6, flow.axis(15), flow.literal(1)))
    let recur = formula.apply(next, flow.axis(2 * table.capacity + as_field(slot)))
    flow.branch(binary(9, flow.axis(15), flow.literal(0)), flow.axis(28), recur)
}

// Source base and index execute exactly once, base first, before the bound.
#[pure]
pub fn read(base: formula.Value, index: formula.Value, length: U32, table: tree.Shape, slot: U32) -> formula.Value {
    let dispatch = formula.apply(flow.axis(1), flow.axis(2 * table.capacity + as_field(slot)))
    let crash = formula.Value { formula: noun.pair(noun.atom(8), flow.literal(0).formula), depth: as_u32(2) }
    let checked = flow.branch(binary(10, flow.axis(15), flow.literal(as_field(length))), dispatch, crash)
    flow.compose(subject(base, index), checked)
}

sources.std.compiler.nox.array_parse:
module std.compiler.nox.array_parse

use vm.nox.noun
use vm.core.convert
use std.nox.bytes
use std.nox.seq
use std.compiler.nox.syntax
use std.compiler.nox.ast
use std.compiler.nox.types
use std.compiler.nox.lexer
use std.compiler.nox.signatures
use std.compiler.nox.expression_state

struct Frame { start: U32, base: U32, count: U32, head: U32 }

#[pure]
fn pack(f: Frame) -> Noun {
    let position = noun.pair(noun.atom(as_field(f.start)), noun.atom(as_field(f.base)))
    let values = noun.pair(noun.atom(as_field(f.count)), noun.atom(as_field(f.head)))
    noun.pair(position, values)
}

#[pure]
fn read(value: Noun) -> Frame {
    let position = noun.head(value)
    let values = noun.tail(value)
    Frame { start: as_u32(noun.as_field(noun.head(position))), base: as_u32(noun.as_field(noun.tail(position))),
        count: as_u32(noun.as_field(noun.head(values))), head: as_u32(noun.as_field(noun.tail(values))) }
}

#[pure]
pub fn enter(source: bytes.Bytes, input: expression_state.State) -> expression_state.State {
    let mut s = input
    if s.ops == s.capacity { s.error = ast.failed(s.token, 7) return s }
    let frame = Frame { start: s.token.start, base: s.vals, count: syntax.ZERO, head: signatures.NONE }
    s.frames = noun.pair(pack(frame), s.frames)
    s.operators = ast.store(s.operators, s.ops, noun.atom(as_field(expression_state.ARRAY_MARKER)), s.capacity)
    s.ops = syntax.inc(s.ops)
    s.token = lexer.next(source, s.token.end)
    s.operand = true
    s
}

#[pure]
pub fn finish(source: bytes.Bytes, input: expression_state.State, closing: Bool) -> expression_state.State {
    let mut s = input
    let mut f = read(noun.head(s.frames))
    if s.operand {
        // Both [] and a trailing comma after an element are valid.
        if closing == false { s.error = ast.failed(s.token, 2) return s }
    } else {
        if (s.vals == syntax.inc(f.base)) == false { s.error = ast.failed(s.token, 2) return s }
        let value = noun.as_field(seq.get(s.values, f.base))
        let node = seq.get(s.nodes, as_u32(value))
        if noun.eq(ast.ty(node), noun.atom(types.FIELD)) == false { s.error = ast.issue(6, node) return s }
        if syntax.either(syntax.inc(f.count) == s.node_cap, seq.len(s.arguments) == s.node_cap) {
            s.error = ast.failed(s.token, 7) return s
        }
        let link = seq.len(s.arguments)
        s.arguments = seq.push(s.arguments, noun.pair(noun.atom(value), noun.atom(as_field(f.head))), s.node_cap)
        f.head = link
        f.count = syntax.inc(f.count)
        s.vals = f.base
    }
    if closing {
        let built = types.array(f.count, s.node_cap, s.capacity)
        if built.failed { s.error = ast.failed(s.token, 7) return s }
        if syntax.either(seq.len(s.nodes) == s.node_cap, s.vals == s.capacity) { s.error = ast.failed(s.token, 7) return s }
        let id = seq.len(s.nodes)
        s.nodes = seq.push(s.nodes, ast.typed(ast.ARRAY_VALUE, as_field(f.count), as_field(f.head), built.ty, f.start, s.token.end), s.node_cap)
        s.values = ast.store(s.values, s.vals, noun.atom(as_field(id)), s.capacity)
        s.vals = syntax.inc(s.vals)
        s.ops = syntax.dec(s.ops)
        s.frames = noun.tail(s.frames)
        s.operand = false
    } else {
        s.frames = noun.pair(pack(f), noun.tail(s.frames))
        s.operand = true
    }
    s.token = lexer.next(source, s.token.end)
    s
}

sources.std.compiler.nox.array_size:
module std.compiler.nox.array_size

use vm.nox.noun
use vm.core.convert
use vm.core.field
use std.nox.bytes
use std.compiler.nox.syntax
use std.compiler.nox.lexer
use std.compiler.nox.ast
use std.compiler.nox.types

pub struct Size { pub value: U32, pub exceeded: Bool }
pub struct Parsed { pub ty: Noun, pub token: syntax.Token, pub error: syntax.Error }

// Read known decimal source digits before Field normalization. Values never
// grow beyond ten times the internal table allowance, so even raw u64 limits are safe.
#[pure]
#[requires((end < start) == false)]
#[requires((bytes.len(source) < end) == false)]
#[requires((syntax.TABLE_CAP < limit) == false)]
pub fn decimal(source: bytes.Bytes, start: U32, end: U32, limit: U32) -> Size {
    let mut pos = start
    let mut value = syntax.ZERO
    for step in 0..65536 {
        if pos == end { return Size { value, exceeded: false } }
        let digit = field.sub(as_field(bytes.get(source, pos)), 48)
        value = as_u32(as_field(value) * 10 + digit)
        if limit < value { return Size { value: limit, exceeded: true } }
        pos = syntax.inc(pos)
    }
    Size { value, exceeded: (pos == end) == false }
}

#[pure]
fn fail(token: syntax.Token, code: Field) -> Parsed {
    Parsed { ty: noun.atom(types.INVALID), token, error: ast.failed(token, code) }
}

#[pure]
#[requires((syntax.TABLE_CAP < cap) == false)]
#[requires((syntax.STACK_CAP < stack) == false)]
pub fn parse(source: bytes.Bytes, opening: syntax.Token, cap: U32, stack: U32) -> Parsed {
    let element = lexer.next(source, opening.end)
    if (element.kind == as_u32(12)) == false { return fail(element, 6) }
    let separator = lexer.next(source, element.end)
    if (separator.kind == as_u32(43)) == false { return fail(separator, 2) }
    let size = lexer.next(source, separator.end)
    if (size.kind == as_u32(2)) == false {
        if size.kind == as_u32(14) { return fail(size, 1) }
        if syntax.either(size.kind == as_u32(1), size.kind == as_u32(5)) { return fail(size, 6) }
        return fail(size, 2)
    }
    let closing = lexer.next(source, size.end)
    if (closing.kind == as_u32(37)) == false {
        if syntax.either(closing.kind == as_u32(3), closing.kind == as_u32(4)) { return fail(closing, 6) }
        return fail(closing, 2)
    }
    let length = decimal(source, size.start, size.end, cap)
    if length.exceeded { return fail(size, 7) }
    let built = types.array(length.value, cap, stack)
    if built.failed { return fail(size, 7) }
    Parsed { ty: built.ty, token: lexer.next(source, closing.end), error: syntax.error(0, syntax.ZERO, syntax.ZERO) }
}

sources.std.compiler.nox.ascii:
module std.compiler.nox.ascii

use std.nox.bytes
use std.compiler.nox.syntax
use vm.core.convert
use vm.core.field

#[pure]
pub fn digit(value: U32) -> Bool { syntax.both((value < as_u32(48)) == false, value < as_u32(58)) }

#[pure]
pub fn initial(value: U32) -> Bool {
    if value == as_u32(95) { return true }
    if value < as_u32(65) { return false }
    if value < as_u32(91) { return true }
    if value < as_u32(97) { return false }
    value < as_u32(123)
}

#[pure]
pub fn space(value: U32) -> Bool {
    if value < as_u32(14) {
        if value < as_u32(9) { return false }
        return (value == as_u32(11)) == false
    }
    value == as_u32(32)
}

#[pure]
#[requires((bytes.len(source) < end) == false)]
#[requires((end < start) == false)]
pub fn same(source: bytes.Bytes, start: U32, end: U32, name: bytes.Bytes) -> Bool {
    let length = as_u32(field.sub(as_field(end), as_field(start)))
    if (length == bytes.len(name)) == false { return false }
    let mut pos = start
    for i in 0..255 {
        if pos == end { return true }
        if (bytes.get(source, pos) == bytes.get(name, i)) == false { return false }
        pos = syntax.inc(pos)
    }
    pos == end
}

// 1 identifier; 10 program; 11 fn; 12 Field; 13 reserved/unsupported.
#[pure]
pub fn keyword(value: Field) -> Field {
    if value == 31651020194079085 { return 10 } // program
    if value == 120325194214501 { return 13 } // module
    if value == 7697253 { return 13 } // use
    if value == 26222 { return 11 } // fn
    if value == 7370082 { return 40 } // pub
    if value == 7562595 { return 13 } // sec
    if value == 7103860 { return 15 } // let
    if value == 7173492 { return 16 } // mut
    if value == 427071271796 { return 45 } // const
    if value == 126943973696372 { return 39 } // struct
    if value == 26982 { return 23 } // if
    if value == 1701606245 { return 24 } // else
    if value == 6713202 { return 31 } // for
    if value == 26990 { return 32 } // in
    if value == 27707097871574372 { return 13 } // bounded
    if value == 125780071117422 { return 25 } // return
    if value == 1953658213 { return 21 } // true
    if value == 439721161573 { return 22 } // false
    if value == 435778055796 { return 13 } // event
    if value == 125780103618924 { return 13 } // reveal
    if value == 1936023916 { return 13 } // seal
    if value == 469786452840 { return 13 } // match
    if value == 302415965284 { return 12 } // Field
    if value == 97059439209572 { return 13 } // XField
    if value == 1114599276 { return 20 } // Bool
    if value == 5583666 { return 28 } // U32
    if value == 1315927406 { return 34 } // Noun
    if value == 75219496956788 { return 35 } // Digest
    if value == 95 { return 13 } // _
    if value == 6386541 { return 13 } // asm
    1
}

#[pure]
pub fn punctuation(value: U32) -> Bool {
    let codes = [35,91,93,59,61,44,46,58,38,94,60,62]
    for i in 0..12 { if as_field(value) == codes[i] { return true } }
    false
}

// Call punctuation belongs to an identifier only on the same physical line.
#[pure]
#[requires((bytes.len(source) < end) == false)]
#[requires((end < start) == false)]
#[requires((syntax.SOURCE_CAP < bytes.len(source)) == false)]
pub fn same_line(source: bytes.Bytes, start: U32, end: U32) -> Bool {
    let mut pos = start
    for step in 0..65536 {
        if pos == end { return true }
        if bytes.get(source, pos) == as_u32(10) { return false }
        pos = syntax.inc(pos)
    }
    true
}

sources.std.compiler.nox.ast:
module std.compiler.nox.ast

use vm.nox.noun
use vm.core.convert
use std.nox.seq
use std.compiler.nox.syntax
use std.compiler.nox.types

pub const LITERAL: Field = 0
pub const LOCAL: Field = 1
pub const BOOLEAN: Field = 2
pub const ADD: Field = 3
pub const MUL: Field = 4
pub const EQUAL: Field = 5
pub const CALL: Field = 6
pub const UNIT_VALUE: Field = 7
pub const LESS: Field = 8
pub const BIT_AND: Field = 9
pub const BUILTIN: Field = 10
pub const DIGEST_INDEX: Field = 11
pub const TUPLE_VALUE: Field = 12
pub const PROJECT: Field = 13
pub const RECORD_VALUE: Field = 14
pub const RECORD_EDIT: Field = 15
pub const ARRAY_VALUE: Field = 16
pub const ARRAY_INDEX: Field = 17
pub const CONSTANT: Field = 18

// Postorder expression: [[kind [left right]] [type [start end]]].
// Child IDs precede their parent. AST operations are independent of token kinds.
#[pure]
pub fn typed(kind: Field, left: Field, right: Field, ty: Noun, start: U32, end: U32) -> Noun {
    let value = noun.pair(noun.atom(kind), noun.pair(noun.atom(left), noun.atom(right)))
    let span = noun.pair(noun.atom(as_field(start)), noun.atom(as_field(end)))
    noun.pair(value, noun.pair(ty, span))
}

// Internal component builders can omit source spans.
#[pure]
pub fn node(kind: Field, left: Field, right: Field) -> Noun {
    let mut ty = noun.atom(types.FIELD)
    if syntax.either(kind == BOOLEAN, kind == EQUAL) { ty = noun.atom(types.BOOL) }
    if kind == UNIT_VALUE { ty = noun.atom(types.UNIT) }
    if kind == LESS { ty = noun.atom(types.BOOL) }
    if kind == BIT_AND { ty = noun.atom(types.UINT32) }
    typed(kind, left, right, ty, syntax.ZERO, syntax.ZERO)
}

#[pure]
pub fn kind(node: Noun) -> Field { noun.as_field(noun.head(noun.head(node))) }

#[pure]
pub fn left(node: Noun) -> Field { noun.as_field(noun.head(noun.tail(noun.head(node)))) }

#[pure]
pub fn right(node: Noun) -> Field { noun.as_field(noun.tail(noun.tail(noun.head(node)))) }

#[pure]
pub fn ty(node: Noun) -> Noun { noun.head(noun.tail(node)) }

#[pure]
pub fn start(node: Noun) -> U32 { as_u32(noun.as_field(noun.head(noun.tail(noun.tail(node))))) }

#[pure]
pub fn end(node: Noun) -> U32 { as_u32(noun.as_field(noun.tail(noun.tail(noun.tail(node))))) }

#[pure]
pub fn issue(code: Field, node: Noun) -> syntax.Error { syntax.error(code, start(node), end(node)) }

#[pure]
pub fn store(stack: seq.Seq, length: U32, value: Noun, cap: U32) -> seq.Seq {
    if length < seq.len(stack) { return seq.set(stack, length, value) }
    seq.push(stack, value, cap)
}

#[pure]
pub fn failed(token: syntax.Token, fallback: Field) -> syntax.Error {
    if token.kind == as_u32(46) { return syntax.error(6, token.start, token.end) }
    if token.kind == as_u32(45) { return syntax.error(6, token.start, token.end) }
    if token.kind == as_u32(43) { return syntax.error(6, token.start, token.end) }
    if syntax.either(token.kind == as_u32(41), syntax.either(token.kind == as_u32(39), token.kind == as_u32(40))) { return syntax.error(6, token.start, token.end) }
    if token.kind == as_u32(35) { return syntax.error(6, token.start, token.end) }
    if syntax.either(token.kind == as_u32(34), token.kind == as_u32(28)) { return syntax.error(6, token.start, token.end) }
    if syntax.either(token.kind == as_u32(20), token.kind == as_u32(23)) { return syntax.error(6, token.start, token.end) }
    if token.kind == as_u32(14) { return syntax.error(1, token.start, token.end) }
    if syntax.either(syntax.either(syntax.either(token.kind == as_u32(13), token.kind == as_u32(10)), token.kind == as_u32(11)), token.kind == as_u32(12)) {
        return syntax.error(6, token.start, token.end)
    }
    syntax.error(fallback, token.start, token.end)
}

sources.std.compiler.nox.attributes:
module std.compiler.nox.attributes

use vm.core.convert
use vm.core.field
use std.nox.bytes
use std.compiler.nox.syntax
use std.compiler.nox.lexer
use std.compiler.nox.intrinsic_abi

pub const HASH: U32 = 46
pub struct Parsed {
    pub token: syntax.Token, pub error: syntax.Error, pub pure: Bool,
    pub intrinsic: Bool, pub identity: U32, pub intrinsic_start: U32, pub intrinsic_end: U32
}
struct Payload { token: syntax.Token, depth: U32, error: syntax.Error }

#[pure]
fn expected(token: syntax.Token) -> syntax.Error {
    if token.kind == as_u32(14) { return syntax.error(1, token.start, token.end) }
    syntax.error(2, token.start, token.end)
}

#[pure]
fn kind(source: bytes.Bytes, name: syntax.Token) -> Field {
    if name.value == 1886745189 { return 1 } // pure
    if name.value == 28550414818502003 { return 2 } // ensures
    let length = as_u32(field.sub(as_field(name.end), as_field(name.start)))
    let mut spelling = [105,110,116,114,105,110,115,105,99] // intrinsic
    let mut attribute: Field = 3
    if length == as_u32(8) {
        spelling = [114,101,113,117,105,114,101,115,0] // requires
        attribute = 2
    } else if (length == as_u32(9)) == false { return 0 }
    if syntax.spells(source, name, spelling) { return attribute }
    0
}

// The seed collects lexical metadata, balancing parentheses alone. No source
// expression is checked or executed here; its delimiter stack is independent.
#[pure]
fn payload(source: bytes.Bytes, opening: syntax.Token) -> Payload {
    let mut s = Payload { token: lexer.next(source, opening.end), depth: as_u32(1), error: syntax.error(0, opening.start, opening.end) }
    for turn in 0..4096 {
        if syntax.either(s.token.kind == syntax.ZERO, s.token.kind == as_u32(14)) { s.error = expected(s.token) return s }
        // asm has a special lexer in the seed, including inside attributes.
        if syntax.both(s.token.kind == as_u32(13), s.token.value == 6386541) { s.error = syntax.error(6, s.token.start, s.token.end) return s }
        if s.token.kind == as_u32(5) { s.depth = syntax.inc(s.depth) }
        if s.token.kind == as_u32(6) {
            s.depth = syntax.dec(s.depth)
            if s.depth == syntax.ZERO { s.token = lexer.next(source, s.token.end) return s }
        }
        s.token = lexer.next(source, s.token.end)
    }
    s.error = syntax.error(7, s.token.start, s.token.end)
    s
}

#[pure]
fn one(source: bytes.Bytes, input: Parsed) -> Parsed {
    let mut s = input
    let start = s.token.start
    s.token = lexer.next(source, s.token.end)
    if (s.token.kind == as_u32(36)) == false { s.error = expected(s.token) return s }
    let name = lexer.next(source, s.token.end)
    if (name.kind == as_u32(1)) == false { s.error = expected(name) return s }
    let attribute = kind(source, name)
    if attribute == 0 { s.error = syntax.error(6, name.start, name.end) return s }
    s.token = lexer.next(source, name.end)
    if attribute == 1 {
        if s.token.kind == as_u32(5) { s.error = syntax.error(6, name.start, s.token.end) return s }
        s.pure = true
    } else {
        if (s.token.kind == as_u32(5)) == false {
            if s.token.kind == as_u32(37) { s.error = syntax.error(6, name.start, s.token.end) }
            else { s.error = expected(s.token) }
            return s
        }
        if attribute == 3 {
            // Only the final attribute is resolved by the header checker.
            // The seed inserts spaces between payload tokens; more than one
            // token therefore cannot name one of our identifier identities.
            s.intrinsic = true
            s.identity = intrinsic_abi.NONE
            s.intrinsic_start = start
            let first = lexer.next(source, s.token.end)
            if first.kind == as_u32(1) {
                let after = lexer.next(source, first.end)
                if after.kind == as_u32(6) { s.identity = intrinsic_abi.lookup(source, first) }
            }
        }
        let collected = payload(source, s.token)
        s.token = collected.token
        s.error = collected.error
        if (s.error.code == syntax.ZERO) == false { return s }
    }
    if (s.token.kind == as_u32(37)) == false { s.error = expected(s.token) return s }
    if attribute == 3 { s.intrinsic_end = s.token.end }
    s.token = lexer.next(source, s.token.end)
    s
}

#[pure]
#[requires((syntax.SOURCE_CAP < bytes.len(source)) == false)]
pub fn parse(source: bytes.Bytes, start: syntax.Token) -> Parsed {
    let mut s = Parsed { token: start, error: syntax.error(0, start.start, start.end), pure: false,
        intrinsic: false, identity: intrinsic_abi.NONE, intrinsic_start: syntax.ZERO, intrinsic_end: syntax.ZERO }
    for turn in 0..4096 {
        if (s.token.kind == HASH) == false { return s }
        s = one(source, s)
        if (s.error.code == syntax.ZERO) == false { return s }
    }
    s.error = syntax.error(7, s.token.start, s.token.end)
    s
}

sources.std.compiler.nox.block_gen:
module std.compiler.nox.block_gen

use vm.nox.noun
use vm.core.convert
use std.nox.seq
use std.nox.tree
use std.compiler.nox.syntax
use std.compiler.nox.blocks
use std.compiler.nox.codegen
use std.compiler.nox.formula
use std.compiler.nox.flow
use std.compiler.nox.loop_records
use std.compiler.nox.loop_gen
use std.compiler.nox.call_codegen

pub struct Built { pub output: formula.Value }
struct Fold { output: formula.Value, remaining: Noun, failed: Bool }
pub struct Emitted { pub values: seq.Seq, pub next: U32, pub failed: Bool }

#[pure]
pub fn read(values: seq.Seq, id: U32) -> Built {
    Built { output: formula.value(values, id) }
}

#[pure]
fn statement(s: blocks.Statement, values: seq.Seq, emitted: seq.Seq, shape: tree.Shape, loops: seq.Seq, context: call_codegen.Context) -> Built {
    if s.kind == blocks.WRITE { return Built { output: flow.keep(codegen.edit(s.a, shape, formula.value(values, s.b))) } }
    if s.kind == blocks.RETURN { return Built { output: flow.returned(formula.value(values, s.a)) } }
    if s.kind == blocks.EVAL { return Built { output: flow.discard(formula.value(values, s.a)) } }
    if s.kind == blocks.FOR { return Built { output: loop_gen.initialize(loop_records.read(seq.get(loops, s.a)), s.a, shape, context) } }
    let yes = read(emitted, s.b)
    let mut no = Built { output: flow.keep(flow.axis(1)) }
    if (s.c == blocks.NONE) == false { no = read(emitted, s.c) }
    Built { output: flow.branch(formula.value(values, s.a), yes.output, no.output) }
}

#[pure]
fn chunk(statements: seq.Seq, values: seq.Seq, emitted: seq.Seq, shape: tree.Shape, input: Fold, depth_cap: U32, loops: seq.Seq, context: call_codegen.Context) -> Fold {
    let mut s = input
    for turn in 0..8 {
        if noun.eq(s.remaining, noun.atom(0)) { return s }
        let id = as_u32(noun.as_field(noun.head(s.remaining)))
        let current = statement(blocks.read_statement(seq.get(statements, id)), values, emitted, shape, loops, context)
        s.output = flow.then(current.output, s.output)
        s.remaining = noun.tail(s.remaining)
        if depth_cap < as_u32(as_field(s.output.depth) + 9) { s.failed = true return s }
    }
    s
}

#[pure]
fn tail(body: blocks.Block, terminal: Bool, values: seq.Seq) -> formula.Value {
    if body.has_tail {
        let value = formula.value(values, body.tail)
        if terminal { return flow.returned(value) }
        return flow.discard(value)
    }
    flow.keep(flow.axis(1))
}

#[pure]
fn block(body: blocks.Block, terminal: Bool, statements: seq.Seq, values: seq.Seq, emitted: seq.Seq, shape: tree.Shape, depth_cap: U32, loops: seq.Seq, context: call_codegen.Context) -> Fold {
    // Build only the continuation used by this block; discarded alternatives
    // otherwise consume the compiler's lifetime arena even for a simple tail.
    let mut s = Fold { output: tail(body, terminal, values), remaining: body.statements, failed: false }
    for turn in 0..512 {
        s = chunk(statements, values, emitted, shape, s, depth_cap, loops, context)
        if syntax.either(s.failed, noun.eq(s.remaining, noun.atom(0))) { return s }
    }
    s.failed = true
    s
}

#[pure]
fn block_chunk(bodies: seq.Seq, flags: Noun, statements: seq.Seq, values: seq.Seq, shape: tree.Shape, input: Emitted, depth_cap: U32, loops: seq.Seq, context: call_codegen.Context) -> Emitted {
    let mut s = input
    for turn in 0..8 {
        if s.next == seq.len(bodies) { return s }
        let terminal = noun.as_field(tree.get(flags, seq.len(bodies), s.next)) == 1
        let built = block(blocks.read(seq.get(bodies, s.next)), terminal, statements, values, s.values, shape, depth_cap, loops, context)
        if built.failed { s.failed = true return s }
        let output = noun.pair(noun.atom(as_field(built.output.depth)), built.output.formula)
        s.values = seq.push(s.values, output, seq.len(bodies))
        s.next = syntax.inc(s.next)
    }
    s
}

#[pure]
#[requires((syntax.TABLE_CAP < seq.len(bodies)) == false)]
pub fn generate(bodies: seq.Seq, flags: Noun, statements: seq.Seq, values: seq.Seq, shape: tree.Shape, depth_cap: U32, loops: seq.Seq, context: call_codegen.Context) -> Emitted {
    let mut s = Emitted { values: seq.empty(), next: syntax.ZERO, failed: false }
    for turn in 0..512 {
        s = block_chunk(bodies, flags, statements, values, shape, s, depth_cap, loops, context)
        if syntax.either(s.failed, s.next == seq.len(bodies)) { return s }
    }
    s.failed = true
    s
}

sources.std.compiler.nox.blocks:
module std.compiler.nox.blocks

use vm.nox.noun
use vm.core.convert

pub const WRITE: Field = 0
pub const IF: Field = 1
pub const RETURN: Field = 2
pub const EVAL: Field = 3
pub const FOR: Field = 4
pub const NONE: U32 = 4096

pub struct Statement { pub kind: Field, pub a: U32, pub b: U32, pub c: U32 }
pub struct Block {
    pub statements: Noun, pub has_tail: Bool, pub tail: U32,
    pub start: U32, pub end: U32
}

// Statement IDs are owned by one reversed list. Nested block IDs precede parents.
#[pure]
pub fn statement(kind: Field, a: U32, b: U32, c: U32) -> Statement { Statement { kind, a, b, c } }

#[pure]
pub fn pack_statement(s: Statement) -> Noun {
    noun.pair(noun.pair(noun.atom(s.kind), noun.atom(as_field(s.a))),
        noun.pair(noun.atom(as_field(s.b)), noun.atom(as_field(s.c))))
}

#[pure]
pub fn read_statement(value: Noun) -> Statement {
    let a = noun.head(value)
    let b = noun.tail(value)
    Statement { kind: noun.as_field(noun.head(a)), a: as_u32(noun.as_field(noun.tail(a))),
        b: as_u32(noun.as_field(noun.head(b))), c: as_u32(noun.as_field(noun.tail(b))) }
}

#[pure]
pub fn flag(value: Bool) -> Noun { if value { return noun.atom(1) } noun.atom(0) }

#[pure]
pub fn pack(b: Block) -> Noun {
    let tail = noun.pair(flag(b.has_tail), noun.atom(as_field(b.tail)))
    let span = noun.pair(noun.atom(as_field(b.start)), noun.atom(as_field(b.end)))
    noun.pair(noun.pair(b.statements, tail), span)
}

#[pure]
pub fn read(value: Noun) -> Block {
    let contents = noun.head(value)
    let tail = noun.tail(contents)
    let span = noun.tail(value)
    Block { statements: noun.head(contents), has_tail: noun.as_field(noun.head(tail)) == 1,
        tail: as_u32(noun.as_field(noun.tail(tail))), start: as_u32(noun.as_field(noun.head(span))),
        end: as_u32(noun.as_field(noun.tail(span))) }
}

sources.std.compiler.nox.body:
module std.compiler.nox.body

use std.compiler.nox.constants
use std.compiler.nox.check_scope
use std.compiler.nox.function_imports
use vm.nox.noun
use vm.core.convert
use std.nox.bytes
use std.nox.seq
use std.compiler.nox.type_registry
use std.compiler.nox.syntax
use std.compiler.nox.lexer
use std.compiler.nox.ast
use std.compiler.nox.expression
use std.compiler.nox.expression_state
use std.compiler.nox.blocks
use std.compiler.nox.body_state
use std.compiler.nox.declarations
use std.compiler.nox.control_parse
use std.compiler.nox.signatures
use std.compiler.nox.loop_parse
use std.compiler.nox.types
use std.compiler.nox.tuple_declarations
use std.compiler.nox.record_assign
use std.compiler.nox.halting
use std.compiler.nox.intrinsic_bindings

#[pure]
fn step(source: bytes.Bytes, input: body_state.State, cap: U32) -> body_state.State {
    let mut s = input
    // An else-if owns a synthetic block containing exactly the completed If.
    if syntax.both(s.synthetic, noun.eq(s.current, noun.atom(0)) == false) {
        return control_parse.close(source, s, cap, false)
    }
    if s.token.kind == as_u32(8) { return control_parse.close(source, s, cap, true) }
    if s.returned { s.error = syntax.error(5, s.token.start, s.token.end) return s }
    if s.token.kind == as_u32(15) { return declarations.parse(source, s, cap, s.token) }
    if s.token.kind == as_u32(1) {
        let next = lexer.next(source, s.token.end)
        if next.kind == as_u32(18) { return declarations.parse(source, s, cap, next) }
    }
    if s.token.kind == as_u32(23) { return control_parse.enter(source, s, cap) }
    if s.token.kind == as_u32(31) { return loop_parse.enter(source, s, cap) }
    let returning = s.token.kind == as_u32(25)
    if returning {
        s.token = lexer.next(source, s.token.end)
        if s.token.kind == as_u32(8) {
            if (noun.eq(s.returns, noun.atom(types.UNIT))) == false { s.error = syntax.error(5, s.token.start, s.token.end) return s }
            if seq.len(s.nodes) == cap { s.error = syntax.error(7, s.token.start, s.token.end) return s }
            let id = seq.len(s.nodes)
            s.nodes = seq.push(s.nodes, ast.typed(ast.UNIT_VALUE, 0, 0, noun.atom(types.UNIT), s.token.start, s.token.start), cap)
            s = body_state.append(s, blocks.statement(blocks.RETURN, id, syntax.ZERO, syntax.ZERO), cap)
            s.returned = true
            return s
        }
    }
    let value = expression.parse(source, s.token, expression_state.context(s.bindings, s.visible, s.scope), s.nodes, s.arguments, s.edges, cap, false)
    s.error = value.error
    if (s.error.code == syntax.ZERO) == false { return s }
    s.nodes = value.nodes
    s.arguments = value.arguments
    s.edges = value.edges
    if value.needs_get { s.needs_get = true }
    s.token = value.token
    if returning {
        let node = seq.get(s.nodes, value.value)
        if (noun.eq(ast.ty(node), s.returns)) == false {
            if halting.is_false_assert(node, s.nodes, s.arguments) == false { s.error = ast.issue(5, node) return s }
        }
        s = body_state.append(s, blocks.statement(blocks.RETURN, value.value, syntax.ZERO, syntax.ZERO), cap)
        s.returned = true
        return s
    }
    if s.token.kind == as_u32(18) {
        if ast.kind(seq.get(s.nodes, value.value)) == ast.PROJECT { return record_assign.assign(source, s, value.value, cap) }
        return tuple_declarations.assign(source, s, value.value, cap)
    }
    if s.token.kind == as_u32(8) {
        s.has_tail = true
        s.tail = value.value
        return control_parse.close(source, s, cap, true)
    }
    s.returned = halting.is_false_assert(seq.get(s.nodes, value.value), s.nodes, s.arguments)
    body_state.append(s, blocks.statement(blocks.EVAL, value.value, syntax.ZERO, syntax.ZERO), cap)
}

#[pure]
fn chunk(source: bytes.Bytes, input: body_state.State, cap: U32) -> body_state.State {
    let mut s = input
    for turn in 0..8 {
        s = step(source, s, cap)
        if syntax.either(s.done, (s.error.code == syntax.ZERO) == false) { return s }
    }
    s
}

#[pure]
fn drive(source: bytes.Bytes, input: body_state.State, cap: U32) -> body_state.State {
    let mut s = input
    if cap == syntax.ZERO { s.error = syntax.error(7, s.token.start, s.token.end) return s }
    for turn in 0..512 {
        s = chunk(source, s, cap)
        if syntax.either(s.done, (s.error.code == syntax.ZERO) == false) { return s }
    }
    s.error = syntax.error(7, s.token.start, s.token.end)
    s
}

#[pure]
#[requires((syntax.SOURCE_CAP < bytes.len(source)) == false)]
pub fn parse(source: bytes.Bytes, start: U32, cap: U32) -> body_state.State {
    let mut s = body_state.initial(lexer.next(source, start))
    s.start = syntax.dec(start)
    s = drive(source, s, cap)
    if syntax.both(s.error.code == syntax.ZERO, (s.token.kind == syntax.ZERO) == false) { s.error = ast.failed(s.token, 2) }
    s
}

struct Parameters { body: body_state.State, next: U32 }

#[pure]
fn parameter_chunk(input: Parameters, signature: signatures.Function, cap: U32) -> Parameters {
    let mut s = input
    for turn in 0..8 {
        if s.next == signature.count { return s }
        if seq.len(s.body.bindings) == cap { s.body.error = syntax.error(7, signature.name.start, signature.name.end) return s }
        let binding = seq.get(s.body.scope.params, as_u32(as_field(signature.params) + as_field(s.next)))
        s.body.bindings = seq.push(s.body.bindings, binding, cap)
        s.body.visible = noun.pair(noun.atom(as_field(s.next)), s.body.visible)
        s.next = syntax.inc(s.next)
    }
    s
}

#[pure]
#[requires((syntax.SOURCE_CAP < bytes.len(source)) == false)]
pub fn function(source: bytes.Bytes, signature: signatures.Function, functions: seq.Seq, params: seq.Seq, scope: type_registry.Scope, consts: constants.Scope, pure: Bool, cap: U32) -> body_state.State {
    function_in(source, signature, functions, params, scope, consts, pure, cap,
        syntax.ZERO, seq.len(functions), function_imports.empty())
}

#[pure]
#[requires((syntax.SOURCE_CAP < bytes.len(source)) == false)]
#[requires((end < start) == false)]
#[requires((seq.len(functions) < end) == false)]
pub fn function_in(source: bytes.Bytes, signature: signatures.Function, functions: seq.Seq, params: seq.Seq, scope: type_registry.Scope, consts: constants.Scope, pure: Bool, cap: U32, start: U32, end: U32, imports: function_imports.View) -> body_state.State {
    function_with_intrinsics(source, signature, functions, params, scope, consts, pure, cap,
        start, end, imports, intrinsic_bindings.empty())
}

#[pure]
#[requires((syntax.SOURCE_CAP < bytes.len(source)) == false)]
#[requires((end < start) == false)]
#[requires((seq.len(functions) < end) == false)]
pub fn function_with_intrinsics(source: bytes.Bytes, signature: signatures.Function, functions: seq.Seq, params: seq.Seq, scope: type_registry.Scope, consts: constants.Scope, pure: Bool, cap: U32, start: U32, end: U32, imports: function_imports.View, intrinsics: intrinsic_bindings.Bank) -> body_state.State {
    let context = check_scope.Scope { pure, types: scope, functions, params, constants: consts,
        function_start: start, function_end: end, imported_functions: imports, intrinsics }
    let initial = body_state.scoped(lexer.next(source, signature.open), syntax.dec(signature.open), signature.returns, context)
    let mut s = Parameters { body: initial, next: syntax.ZERO }
    for turn in 0..512 {
        s = parameter_chunk(s, signature, cap)
        if (s.body.error.code == syntax.ZERO) == false { return s.body }
        if s.next == signature.count {
            s.body = drive(source, s.body, cap)
            if syntax.both(s.body.error.code == syntax.ZERO, (s.body.end == signature.close) == false) {
                s.body.error = syntax.error(2, s.body.start, s.body.end)
            }
            return s.body
        }
    }
    s.body.error = syntax.error(7, signature.name.start, signature.name.end)
    s.body
}

sources.std.compiler.nox.body_state:
module std.compiler.nox.body_state

use std.compiler.nox.check_scope
use vm.nox.noun
use vm.core.convert
use std.nox.seq
use std.compiler.nox.syntax
use std.compiler.nox.blocks
use std.compiler.nox.types

pub struct State {
    // Every parsed statement advances the token and propagates a diagnostic.
    // Keep these and statement-list writes before the cold persistent context.
    pub token: syntax.Token, pub error: syntax.Error,
    pub nodes: seq.Seq, pub statements: seq.Seq, pub current: Noun,
    pub arguments: seq.Seq, pub edges: Noun, pub loops: seq.Seq,
    pub scope: check_scope.Scope, pub returns: Noun, pub blocks: seq.Seq,
    pub bindings: seq.Seq, pub visible: Noun,
    pub frames: Noun, pub depth: U32, pub start: U32, pub end: U32,
    pub synthetic: Bool, pub returned: Bool, pub has_tail: Bool, pub tail: U32,
    pub done: Bool, pub root: U32, pub needs_get: Bool
}

#[pure]
pub fn scoped(token: syntax.Token, start: U32, returns: Noun, scope: check_scope.Scope) -> State {
    let zero = syntax.ZERO
    State { nodes: seq.empty(), arguments: seq.empty(), edges: noun.atom(0), loops: seq.empty(),
        scope, returns, statements: seq.empty(), blocks: seq.empty(),
        bindings: seq.empty(), visible: noun.atom(0), current: noun.atom(0),
        frames: noun.atom(0), depth: zero, start, end: token.start, synthetic: false,
        returned: false, has_tail: false, tail: zero, token,
        error: syntax.error(0, zero, zero), done: false, root: zero, needs_get: false }
}

#[pure]
pub fn initial(token: syntax.Token) -> State {
    scoped(token, token.start, noun.atom(types.FIELD), check_scope.empty())
}

#[pure]
pub fn append(input: State, statement: blocks.Statement, cap: U32) -> State {
    let mut s = input
    if seq.len(s.statements) == cap {
        s.error = syntax.error(7, s.token.start, s.token.end)
        return s
    }
    let id = seq.len(s.statements)
    s.statements = seq.push(s.statements, blocks.pack_statement(statement), cap)
    s.current = noun.pair(noun.atom(as_field(id)), s.current)
    s
}

sources.std.compiler.nox.body_store:
module std.compiler.nox.body_store

use vm.nox.noun
use vm.core.convert
use std.nox.seq
use std.compiler.nox.syntax
use std.compiler.nox.body_state
use std.compiler.nox.blocks

// Body records are compiler-owned. Public Seq handles are serialized here and
// validated once when that body reaches emission; graph reads use only edges.
#[pure]
pub fn pack(s: body_state.State, terminal: Noun) -> Noun {
    let helpers = noun.pair(noun.atom(as_field(seq.len(s.loops))), blocks.flag(s.needs_get))
    let sizes = noun.pair(noun.atom(as_field(seq.len(s.bindings))), noun.pair(noun.atom(as_field(s.root)), helpers))
    let expressions = noun.pair(seq.to_noun(s.nodes), seq.to_noun(s.arguments))
    let control = noun.pair(seq.to_noun(s.statements), noun.pair(seq.to_noun(s.blocks), seq.to_noun(s.loops)))
    let flow = noun.pair(s.returns, noun.pair(s.edges, terminal))
    noun.pair(sizes, noun.pair(expressions, noun.pair(control, flow)))
}

// Bodyless declarations retain only the flow spine read by the call graph.
// Their zero expression/control slots intentionally cannot decode as a Body.
// Resolved intrinsic calls have no function edge, and entry validation rejects
// intrinsic entries, so no executable plan can reach this graph-only record.
#[pure]
pub fn opaque() -> Noun {
    let zero = noun.atom(0)
    let flow = noun.pair(zero, noun.pair(zero, zero))
    noun.pair(zero, noun.pair(zero, noun.pair(zero, flow)))
}

#[pure]
pub fn locals(value: Noun) -> U32 { as_u32(noun.as_field(noun.head(noun.head(value)))) }

#[pure]
pub fn loop_count(value: Noun) -> U32 { as_u32(noun.as_field(noun.head(noun.tail(noun.tail(noun.head(value)))))) }

#[pure]
pub fn needs_get(value: Noun) -> Bool { noun.as_field(noun.tail(noun.tail(noun.tail(noun.head(value))))) == 1 }

#[pure]
pub fn edges(value: Noun) -> Noun { noun.head(noun.tail(noun.tail(noun.tail(noun.tail(value))))) }

#[pure]
pub fn terminal(value: Noun) -> Noun { noun.tail(noun.tail(noun.tail(noun.tail(noun.tail(value))))) }

// Emission retains only checked code and the metadata needed by its consumers.
// Source token/scope/continuation state ends at pack; it is never reconstructed.
pub struct Body {
    pub nodes: seq.Seq, pub arguments: seq.Seq, pub statements: seq.Seq,
    pub blocks: seq.Seq, pub loops: seq.Seq, pub root: U32,
    pub returns: Noun, pub needs_get: Bool
}

#[pure]
pub fn checked(s: body_state.State) -> Body {
    Body { nodes: s.nodes, arguments: s.arguments, statements: s.statements,
        blocks: s.blocks, loops: s.loops, root: s.root, returns: s.returns, needs_get: s.needs_get }
}

#[pure]
#[requires((syntax.TABLE_CAP < cap) == false)]
pub fn read(value: Noun, cap: U32) -> Body {
    let sizes = noun.head(value)
    let contents = noun.tail(value)
    let expressions = noun.head(contents)
    let tail = noun.tail(contents)
    let control = noun.head(tail)
    let flow = noun.tail(tail)
    // Public sequence handles retain complete admission checks.
    let visits = as_u32(as_field(cap) * 4 + 1)
    Body {
        nodes: seq.from_noun(noun.head(expressions), cap, visits),
        arguments: seq.from_noun(noun.tail(expressions), cap, visits),
        statements: seq.from_noun(noun.head(control), cap, visits),
        blocks: seq.from_noun(noun.head(noun.tail(control)), cap, visits),
        loops: seq.from_noun(noun.tail(noun.tail(control)), cap, visits),
        root: as_u32(noun.as_field(noun.head(noun.tail(sizes)))),
        returns: noun.head(flow), needs_get: needs_get(value)
    }
}

// Intrinsic preflight needs only expression nodes. Keep their complete sequence
// validation without decoding the unrelated statements, blocks and loop banks.
#[pure]
#[requires((syntax.TABLE_CAP < cap) == false)]
#[ensures((cap < seq.len(result)) == false)]
pub fn expression_nodes(value: Noun, cap: U32) -> seq.Seq {
    let expressions = noun.head(noun.tail(value))
    seq.from_noun(noun.head(expressions), cap, as_u32(as_field(cap) * 4 + 1))
}

sources.std.compiler.nox.builtin_gen:
module std.compiler.nox.builtin_gen

use std.compiler.nox.syntax
use vm.nox.noun
use vm.core.convert
use std.nox.seq
use std.compiler.nox.builtins
use std.compiler.nox.formula
use std.compiler.nox.flow

#[pure]
fn binary(opcode: Field, left: formula.Value, right: formula.Value) -> formula.Value {
    formula.Value { formula: noun.pair(noun.atom(opcode), noun.pair(left.formula, right.formula)),
        depth: as_u32(as_field(formula.maximum(left.depth, right.depth)) + 2) }
}

#[pure]
fn assertion(condition: formula.Value) -> formula.Value {
    let zero = flow.literal(0)
    let crash = formula.Value { formula: noun.pair(noun.atom(8), zero.formula), depth: as_u32(2) }
    flow.branch(condition, zero, crash)
}

// The checker owns arity and linked arguments. Links are reversed; a binary
// builtin reconstructs left/right explicitly to preserve evaluation order.
#[pure]
#[requires(syntax.ZERO < kind)]
#[requires(kind < builtins.COUNT)]
#[requires(head < seq.len(arguments))]
pub fn generate(kind: U32, values: seq.Seq, arguments: seq.Seq, head: U32) -> formula.Value {
    let link = seq.get(arguments, head)
    let right = formula.value(values, as_u32(noun.as_field(noun.head(link))))
    if builtins.arity(kind) == as_u32(2) {
        let first = seq.get(arguments, as_u32(noun.as_field(noun.tail(link))))
        let left = formula.value(values, as_u32(noun.as_field(noun.head(first))))
        if kind == builtins.ASSERT_EQ { return assertion(binary(9, left, right)) }
        if kind == builtins.NOUN_PAIR { return formula.pair(left, right) }
        if kind == builtins.NOUN_EQ { return binary(9, left, right) }
        assert(kind == builtins.SUBTRACT)
        return binary(6, left, right)
    }
    if kind == builtins.ASSERT { return assertion(right) }
    if kind == builtins.NOUN_IDENTITY { return flow.compose(right, flow.axis(0)) }
    if kind == builtins.NOUN_HEAD { return flow.compose(right, flow.axis(2)) }
    if kind == builtins.NOUN_TAIL { return flow.compose(right, flow.axis(3)) }
    if kind == builtins.NOUN_FIELD { return binary(5, right, flow.literal(0)) }
    if kind == builtins.NOUN_ATOM { return right }
    if kind == builtins.TO_FIELD { return right }
    assert(kind == builtins.TO_U32)
    let crash = formula.Value { formula: noun.pair(noun.atom(8), flow.literal(0).formula), depth: as_u32(2) }
    let condition = binary(10, flow.axis(1), flow.literal(4294967296))
    flow.compose(right, flow.branch(condition, flow.axis(1), crash))
}

sources.std.compiler.nox.builtins:
module std.compiler.nox.builtins

use vm.nox.noun
use vm.core.convert
use vm.core.field
use std.nox.bytes
use std.compiler.nox.syntax
use std.compiler.nox.types

pub const NONE: U32 = 0
pub const TO_U32: U32 = 1
pub const TO_FIELD: U32 = 2
pub const SUBTRACT: U32 = 3
pub const NOUN_ATOM: U32 = 4
pub const NOUN_PAIR: U32 = 5
pub const NOUN_HEAD: U32 = 6
pub const NOUN_TAIL: U32 = 7
pub const NOUN_FIELD: U32 = 8
pub const NOUN_EQ: U32 = 9
pub const NOUN_IDENTITY: U32 = 10
pub const ASSERT: U32 = 11
pub const ASSERT_EQ: U32 = 12
pub const COUNT: U32 = 13

// Called only after lookup in the final user function namespace fails.
#[pure]
#[requires((bytes.len(source) < token.end) == false)]
#[requires((token.end < token.start) == false)]
#[ensures(result < COUNT)]
pub fn lookup(source: bytes.Bytes, token: syntax.Token) -> U32 {
    let length = as_u32(field.sub(as_field(token.end), as_field(token.start)))
    if syntax.both(length == as_u32(6), token.value == 107148485161588) { return ASSERT }
    if length == as_u32(9) {
        if syntax.spells(source, token, [97,115,115,101,114,116,95,101,113]) == false { return NONE }
        return ASSERT_EQ
    }
    if syntax.both(length == as_u32(6), token.value == 107148150649650) { return TO_U32 }
    if syntax.both(length == as_u32(3), token.value == 7566690) { return SUBTRACT }
    // The lexer retains a packed identifier only through seven bytes.
    if length == as_u32(8) {
        let spelling = [97,115,95,102,105,101,108,100]
        for i in 0..8 {
            if (as_field(bytes.get(source, as_u32(as_field(token.start) + as_field(i)))) == spelling[i]) == false { return NONE }
        }
        return TO_FIELD
    }
    if syntax.either(length == as_u32(11), syntax.either(length == as_u32(13), length == as_u32(17))) == false { return NONE }
    let prefix = [110,111,120,95,110,111,117,110,95]
    for i in 0..9 {
        if (as_field(bytes.get(source, as_u32(as_field(token.start) + as_field(i)))) == prefix[i]) == false { return NONE }
    }
    let suffix = as_u32(field.sub(as_field(length), 9))
    let mut packed: Field = 0
    for i in 0..8 {
        if i < suffix { packed = packed * 256 + as_field(bytes.get(source, as_u32(as_field(token.start) + 9 + as_field(i)))) }
    }
    // Identifier bytes are ASCII: even an eight-byte suffix fits below 2^63.
    if syntax.both(suffix == as_u32(4), packed == 1635020653) { return NOUN_ATOM }
    if syntax.both(suffix == as_u32(4), packed == 1885432178) { return NOUN_PAIR }
    if syntax.both(suffix == as_u32(4), packed == 1751474532) { return NOUN_HEAD }
    if syntax.both(suffix == as_u32(4), packed == 1952541036) { return NOUN_TAIL }
    if syntax.both(suffix == as_u32(8), packed == 7022061137460292708) { return NOUN_FIELD }
    if syntax.both(suffix == as_u32(8), packed == 7594306396727374969) { return NOUN_IDENTITY }
    if syntax.both(suffix == as_u32(2), packed == 25969) { return NOUN_EQ }
    NONE
}

#[pure]
#[requires(kind < COUNT)]
#[ensures(result < as_u32(3))]
pub fn arity(kind: U32) -> U32 {
    if kind == NONE { return syntax.ZERO }
    if syntax.either(kind == ASSERT_EQ, syntax.either(kind == SUBTRACT, syntax.either(kind == NOUN_PAIR, kind == NOUN_EQ))) { return as_u32(2) }
    as_u32(1)
}

#[pure]
#[requires(kind < COUNT)]
pub fn parameter(kind: U32) -> Noun {
    if kind == ASSERT { return noun.atom(types.BOOL) }
    if kind == ASSERT_EQ { return noun.atom(types.FIELD) }
    if NOUN_ATOM < kind { return noun.atom(types.NOUN) }
    if kind == TO_FIELD { return noun.atom(types.UINT32) }
    noun.atom(types.FIELD)
}

#[pure]
#[requires(kind < COUNT)]
pub fn returns(kind: U32) -> Noun {
    if syntax.either(kind == ASSERT, kind == ASSERT_EQ) { return noun.atom(types.UNIT) }
    if kind == NOUN_EQ { return noun.atom(types.BOOL) }
    if kind == NOUN_IDENTITY { return noun.atom(types.DIGEST) }
    if syntax.both((kind < NOUN_ATOM) == false, (kind == NOUN_FIELD) == false) { return noun.atom(types.NOUN) }
    if kind == TO_U32 { return noun.atom(types.UINT32) }
    noun.atom(types.FIELD)
}

sources.std.compiler.nox.call_codegen:
module std.compiler.nox.call_codegen

use vm.nox.noun
use vm.core.convert
use std.nox.seq
use std.nox.tree
use std.compiler.nox.syntax
use std.compiler.nox.signatures
use std.compiler.nox.body_store
use std.compiler.nox.formula
use std.compiler.nox.flow

pub struct Context {
    pub arguments: seq.Seq, pub bodies: seq.Seq, pub slots: Noun,
    pub functions: U32, pub table: tree.Shape, pub capacity: U32, pub loop_base: U32, pub get_slot: U32
}
pub struct Built { pub output: formula.Value, pub failed: Bool }
struct Collected { reversed: seq.Seq, head: U32, failed: Bool }
struct Folded { values: seq.Seq, next: U32 }

#[pure]
pub fn empty() -> Context {
    Context { arguments: seq.empty(), bodies: seq.empty(), slots: noun.atom(0),
        functions: syntax.ZERO, table: tree.shape(syntax.ZERO), capacity: syntax.ZERO, loop_base: syntax.ZERO, get_slot: signatures.NONE }
}

#[pure]
fn collect_chunk(context: Context, values: seq.Seq, input: Collected) -> Collected {
    let mut s = input
    for turn in 0..8 {
        if s.head == signatures.NONE { return s }
        if seq.len(s.reversed) == context.capacity { s.failed = true return s }
        let link = seq.get(context.arguments, s.head)
        s.reversed = seq.push(s.reversed, seq.get(values, as_u32(noun.as_field(noun.head(link)))), context.capacity)
        s.head = as_u32(noun.as_field(noun.tail(link)))
    }
    s
}

#[pure]
fn collect(context: Context, values: seq.Seq, head: U32) -> Collected {
    let mut s = Collected { reversed: seq.empty(), head, failed: false }
    for turn in 0..512 {
        s = collect_chunk(context, values, s)
        if syntax.either(s.failed, s.head == signatures.NONE) { return s }
    }
    s.failed = true
    s
}

#[pure]
fn reverse_chunk(values: seq.Seq, input: Folded) -> Folded {
    let mut s = input
    for turn in 0..8 {
        if s.next == syntax.ZERO { return s }
        s.next = syntax.dec(s.next)
        s.values = seq.push(s.values, seq.get(values, s.next), seq.len(values))
    }
    s
}

#[pure]
fn ordered(values: seq.Seq) -> seq.Seq {
    let mut s = Folded { values: seq.empty(), next: seq.len(values) }
    for turn in 0..512 {
        s = reverse_chunk(values, s)
        if s.next == syntax.ZERO { return s.values }
    }
    s.values
}

#[pure]
fn padding(level: U32) -> formula.Value {
    formula.Value { formula: noun.pair(noun.atom(1), tree.empty(level)), depth: syntax.inc(level) }
}

#[pure]
fn fold_chunk(values: seq.Seq, level: U32, input: Folded) -> Folded {
    let mut s = input
    for turn in 0..8 {
        if s.next == seq.len(values) { return s }
        let left = formula.value(values, s.next)
        s.next = syntax.inc(s.next)
        let mut right = padding(level)
        if s.next < seq.len(values) {
            right = formula.value(values, s.next)
            s.next = syntax.inc(s.next)
        }
        s.values = seq.push(s.values, formula.pack(formula.pair(left, right)), seq.len(values))
    }
    s
}

#[pure]
fn fold(values: seq.Seq, level: U32) -> seq.Seq {
    let mut s = Folded { values: seq.empty(), next: syntax.ZERO }
    for turn in 0..512 {
        s = fold_chunk(values, level, s)
        if s.next == seq.len(values) { return s.values }
    }
    s.values
}

// CONS evaluates the owned argument leaves once, in source order. All other
// callee slots are canonical zero padding, independent of the caller's frame.
#[pure]
fn frame(arguments: seq.Seq, height: U32) -> formula.Value {
    if seq.len(arguments) == syntax.ZERO { return padding(height) }
    let mut values = ordered(arguments)
    for level in 0..12 {
        if level == height { return formula.value(values, syntax.ZERO) }
        values = fold(values, level)
    }
    formula.value(values, syntax.ZERO)
}

#[pure]
#[requires(callee < context.functions)]
pub fn generate(context: Context, values: seq.Seq, callee: U32, head: U32) -> Built {
    let mut s = Built { output: flow.literal(0), failed: false }
    let collected = collect(context, values, head)
    if collected.failed { s.failed = true return s }
    let shape = tree.shape(body_store.locals(seq.get(context.bodies, callee)))
    let environment = frame(collected.reversed, shape.height)
    let subject = formula.pair(flow.axis(2), formula.pair(flow.literal(0), environment))
    let occupied = noun.as_field(tree.get(context.slots, context.functions, callee))
    if occupied == 0 { s.failed = true return s }
    let slot = syntax.dec(as_u32(occupied))
    s.output = formula.apply(subject, flow.axis(2 * context.table.capacity + as_field(slot)))
    s
}

sources.std.compiler.nox.call_frames:
module std.compiler.nox.call_frames

use vm.nox.noun
use vm.core.convert

pub struct Frame {
    pub callee: U32, pub start: U32, pub ops: U32, pub vals: U32,
    pub count: U32, pub head: U32, pub builtin: U32
}

#[pure]
pub fn pack(f: Frame) -> Noun {
    let name = noun.pair(noun.atom(as_field(f.callee)), noun.pair(noun.atom(as_field(f.start)), noun.atom(as_field(f.builtin))))
    let base = noun.pair(noun.atom(as_field(f.ops)), noun.atom(as_field(f.vals)))
    let args = noun.pair(noun.atom(as_field(f.count)), noun.atom(as_field(f.head)))
    noun.pair(name, noun.pair(base, args))
}

#[pure]
pub fn read(value: Noun) -> Frame {
    let name = noun.head(value)
    let state = noun.tail(value)
    let base = noun.head(state)
    let args = noun.tail(state)
    let called = noun.tail(name)
    Frame { callee: as_u32(noun.as_field(noun.head(name))), start: as_u32(noun.as_field(noun.head(called))),
        builtin: as_u32(noun.as_field(noun.tail(called))),
        ops: as_u32(noun.as_field(noun.head(base))), vals: as_u32(noun.as_field(noun.tail(base))),
        count: as_u32(noun.as_field(noun.head(args))), head: as_u32(noun.as_field(noun.tail(args))) }
}

sources.std.compiler.nox.call_graph:
module std.compiler.nox.call_graph

use vm.nox.noun
use vm.core.convert
use std.nox.seq
use std.nox.tree
use std.compiler.nox.syntax
use std.compiler.nox.signatures
use std.compiler.nox.body_store

pub const DEPTH_CAP: U32 = 128
pub struct Walked {
    pub colors: Noun, pub heights: Noun, pub frames: Noun, pub depth: U32, pub next: U32,
    pub done: Bool, pub error: syntax.Error, pub error_function: U32
}

#[pure]
fn push(functions: seq.Seq, bodies: seq.Seq, input: Walked, id: U32, cap: U32) -> Walked {
    let mut s = input
    let mut limit = cap
    if DEPTH_CAP < limit { limit = DEPTH_CAP }
    if s.depth == limit {
        let declaration = signatures.read(seq.get(functions, id))
        s.error = syntax.error(7, declaration.name.start, declaration.name.end)
        s.error_function = id
        return s
    }
    s.colors = tree.set(s.colors, seq.len(functions), id, noun.atom(1))
    let frame = noun.pair(noun.atom(as_field(id)), noun.pair(body_store.edges(seq.get(bodies, id)), noun.atom(0)))
    s.frames = noun.pair(frame, s.frames)
    s.depth = syntax.inc(s.depth)
    s
}

// Remember the longest completed child, including memoized shared suffixes.
#[pure]
fn remember(input: Walked, height: U32) -> Walked {
    let mut s = input
    if noun.eq(s.frames, noun.atom(0)) { return s }
    let frame = noun.head(s.frames)
    let rest = noun.tail(frame)
    let old = as_u32(noun.as_field(noun.tail(rest)))
    if old < height {
        let changed = noun.pair(noun.head(frame), noun.pair(noun.head(rest), noun.atom(as_field(height))))
        s.frames = noun.pair(changed, noun.tail(s.frames))
    }
    s
}

#[pure]
fn step(functions: seq.Seq, bodies: seq.Seq, roots: seq.Seq, input: Walked, cap: U32) -> Walked {
    let mut s = input
    if noun.eq(s.frames, noun.atom(0)) {
        if s.next == seq.len(roots) { s.done = true return s }
        let id = as_u32(noun.as_field(seq.get(roots, s.next)))
        s.next = syntax.inc(s.next)
        if noun.as_field(tree.get(s.colors, seq.len(functions), id)) == 0 { return push(functions, bodies, s, id, cap) }
        return s
    }
    let frame = noun.head(s.frames)
    let id = as_u32(noun.as_field(noun.head(frame)))
    let edges = noun.head(noun.tail(frame))
    let longest = as_u32(noun.as_field(noun.tail(noun.tail(frame))))
    if noun.eq(edges, noun.atom(0)) {
        s.colors = tree.set(s.colors, seq.len(functions), id, noun.atom(2))
        let height = syntax.inc(longest)
        s.heights = tree.set(s.heights, seq.len(functions), id, noun.atom(as_field(height)))
        s.frames = noun.tail(s.frames)
        s.depth = syntax.dec(s.depth)
        return remember(s, height)
    }
    let callee = as_u32(noun.as_field(noun.head(edges)))
    s.frames = noun.pair(noun.pair(noun.atom(as_field(id)), noun.pair(noun.tail(edges), noun.atom(as_field(longest)))), noun.tail(s.frames))
    let color = noun.as_field(tree.get(s.colors, seq.len(functions), callee))
    if color == 1 {
        let declaration = signatures.read(seq.get(functions, callee))
        s.error = syntax.error(5, declaration.name.start, declaration.name.end)
        s.error_function = callee
        return s
    }
    if color == 0 { return push(functions, bodies, s, callee, cap) }
    let height = as_u32(noun.as_field(tree.get(s.heights, seq.len(functions), callee)))
    let mut limit = cap
    if DEPTH_CAP < limit { limit = DEPTH_CAP }
    if limit < as_u32(as_field(s.depth) + as_field(height)) {
        let declaration = signatures.read(seq.get(functions, callee))
        s.error = syntax.error(7, declaration.name.start, declaration.name.end)
        s.error_function = callee
        return s
    }
    remember(s, height)
}

#[pure]
fn chunk(functions: seq.Seq, bodies: seq.Seq, roots: seq.Seq, input: Walked, cap: U32) -> Walked {
    let mut s = input
    for turn in 0..16 {
        s = step(functions, bodies, roots, s, cap)
        if syntax.either(s.done, (s.error.code == syntax.ZERO) == false) { return s }
    }
    s
}

// Each pass allows 16384 traversal steps, independently of source bytes.
// Exhaustion reports capacity even when every function table fits TABLE_CAP.
// Reuse this traversal for all final definitions, then for reachability from main.
#[pure]
#[requires((syntax.TABLE_CAP < seq.len(functions)) == false)]
pub fn walk(functions: seq.Seq, bodies: seq.Seq, roots: seq.Seq, cap: U32) -> Walked {
    let zero = syntax.ZERO
    let mut s = Walked { colors: tree.empty(tree.shape(seq.len(functions)).height), heights: tree.empty(tree.shape(seq.len(functions)).height), frames: noun.atom(0),
        depth: zero, next: zero, done: false, error: syntax.error(0, zero, zero), error_function: signatures.NONE }
    for turn in 0..1024 {
        s = chunk(functions, bodies, roots, s, cap)
        if syntax.either(s.done, (s.error.code == zero) == false) { return s }
    }
    s.error = syntax.error(7, zero, zero)
    s
}

sources.std.compiler.nox.call_parse:
module std.compiler.nox.call_parse

use vm.nox.noun
use vm.core.convert
use std.nox.bytes
use std.nox.seq
use std.compiler.nox.syntax
use std.compiler.nox.ast
use std.compiler.nox.lexer
use std.compiler.nox.signatures
use std.compiler.nox.call_frames
use std.compiler.nox.expression_state
use std.compiler.nox.builtins
use std.compiler.nox.purity
use std.compiler.nox.function_imports
use std.compiler.nox.qualified_name
use std.compiler.nox.intrinsic_abi
use std.compiler.nox.intrinsic_bindings

#[pure]
fn open(source: bytes.Bytes, opening: syntax.Token, callee: U32, builtin: U32, start: U32, input: expression_state.State) -> expression_state.State {
    let mut s = input
    if s.ops == s.capacity { s.error = syntax.error(7, opening.start, opening.end) return s }
    let frame = call_frames.Frame { callee, start, ops: s.ops, vals: s.vals,
        count: syntax.ZERO, head: signatures.NONE, builtin }
    s.frames = noun.pair(call_frames.pack(frame), s.frames)
    s.operators = ast.store(s.operators, s.ops, noun.atom(as_field(expression_state.CALL_MARKER)), s.capacity)
    s.ops = syntax.inc(s.ops)
    s.token = lexer.next(source, opening.end)
    s.operand = true
    s
}

#[pure]
pub fn enter(source: bytes.Bytes, opening: syntax.Token, input: expression_state.State) -> expression_state.State {
    let mut s = input
    if s.context.scope.pure {
        if purity.is_io(source, s.token) { s.error = syntax.error(5, s.token.start, s.token.end) return s }
    }
    let callee = signatures.lookup_range(source, s.token, s.context.scope.functions,
        s.context.scope.function_start, s.context.scope.function_end)
    let mut builtin = builtins.NONE
    if callee == signatures.NONE {
        builtin = builtins.lookup(source, s.token)
        if builtin == builtins.NONE { s.error = syntax.error(5, s.token.start, s.token.end) return s }
    } else {
        builtin = intrinsic_bindings.kind(s.context.scope.intrinsics, callee)
    }
    open(source, opening, callee, builtin, s.token.start, s)
}

// Final declaration identity selects a builtin, while the source member name
// independently controls purity. Ordinary wrappers retain ordinary call edges.
#[pure]
#[requires(name.token.kind == as_u32(5))]
pub fn enter_qualified(source: bytes.Bytes, name: qualified_name.Name, input: expression_state.State) -> expression_state.State {
    let mut s = input
    if s.context.scope.pure {
        if purity.is_io(source, name.member) { s.error = syntax.error(5, name.start, name.end) return s }
    }
    let found = function_imports.lookup(source, name, s.context.scope.imported_functions)
    if found.exists == false { s.error = syntax.error(5, name.start, name.end) return s }
    if (found.target < seq.len(s.context.scope.functions)) == false {
        s.error = syntax.error(5, name.start, name.end) return s
    }
    let builtin = intrinsic_bindings.kind(s.context.scope.intrinsics, found.target)
    open(source, name.token, found.target, builtin, name.start, s)
}

// Called only when the nearest delimiter is this call's operator marker.
#[pure]
pub fn finish(source: bytes.Bytes, input: expression_state.State, closing: Bool) -> expression_state.State {
    let mut s = input
    let mut frame = call_frames.read(noun.head(s.frames))
    let mut count = intrinsic_abi.arity(frame.builtin)
    let mut returns = intrinsic_abi.returns(frame.builtin)
    let mut params = syntax.ZERO
    if frame.builtin == builtins.NONE {
        let function = signatures.read(seq.get(s.context.scope.functions, frame.callee))
        count = function.count
        returns = function.returns
        params = function.params
    }
    if s.operand == false {
        if (s.vals == syntax.inc(frame.vals)) == false { s.error = syntax.error(2, frame.start, s.token.end) return s }
        if frame.count == count { s.error = syntax.error(5, frame.start, s.token.end) return s }
        let value = as_u32(noun.as_field(seq.get(s.values, frame.vals)))
        let argument = seq.get(s.nodes, value)
        let mut ty = intrinsic_abi.parameter(frame.builtin, frame.count)
        if frame.builtin == builtins.NONE {
            let parameter = seq.get(s.context.scope.params, as_u32(as_field(params) + as_field(frame.count)))
            ty = noun.tail(noun.tail(parameter))
        }
        if (noun.eq(ast.ty(argument), ty)) == false { s.error = ast.issue(5, argument) return s }
        if seq.len(s.arguments) == s.node_cap { s.error = syntax.error(7, frame.start, s.token.end) return s }
        let link = seq.len(s.arguments)
        s.arguments = seq.push(s.arguments, noun.pair(noun.atom(as_field(value)), noun.atom(as_field(frame.head))), s.node_cap)
        frame.head = link
        frame.count = syntax.inc(frame.count)
        s.vals = frame.vals
    } else if closing == false { s.error = syntax.error(2, s.token.start, s.token.end) return s }
    if closing {
        if (frame.count == count) == false { s.error = syntax.error(5, frame.start, s.token.end) return s }
        if syntax.either(seq.len(s.nodes) == s.node_cap, s.vals == s.capacity) { s.error = syntax.error(7, frame.start, s.token.end) return s }
        let id = seq.len(s.nodes)
        let mut kind = ast.CALL
        let mut target = frame.callee
        if (frame.builtin == builtins.NONE) == false { kind = ast.BUILTIN target = frame.builtin }
        s.nodes = seq.push(s.nodes, ast.typed(kind, as_field(target), as_field(frame.head), returns, frame.start, s.token.end), s.node_cap)
        s.values = ast.store(s.values, s.vals, noun.atom(as_field(id)), s.capacity)
        s.vals = syntax.inc(s.vals)
        s.ops = frame.ops
        s.frames = noun.tail(s.frames)
        if frame.builtin == builtins.NONE { s.edges = noun.pair(noun.atom(as_field(frame.callee)), s.edges) }
        s.operand = false
    } else {
        s.frames = noun.pair(call_frames.pack(frame), noun.tail(s.frames))
        s.operand = true
    }
    s.token = lexer.next(source, s.token.end)
    s
}

sources.std.compiler.nox.check_functions:
module std.compiler.nox.check_functions

use vm.nox.noun
use vm.core.convert
use std.compiler.nox.constants
use std.nox.bytes
use std.nox.seq
use std.compiler.nox.type_registry
use std.compiler.nox.syntax
use std.compiler.nox.signatures
use std.compiler.nox.body
use std.compiler.nox.body_store
use std.compiler.nox.coverage
use std.compiler.nox.function_imports
use std.compiler.nox.intrinsic_bindings
use std.compiler.nox.intrinsic_abi

pub struct Checked { pub bodies: seq.Seq, pub next: U32, pub error: syntax.Error, pub pure_next: U32 }

#[pure]
fn chunk(source: bytes.Bytes, functions: seq.Seq, params: seq.Seq, pure_functions: seq.Seq, scope: type_registry.Scope, consts: constants.Scope, input: Checked, cap: U32, start: U32, end: U32, imports: function_imports.View, intrinsics: intrinsic_bindings.Bank) -> Checked {
    let mut s = input
    for turn in 0..8 {
        if s.next == end { return s }
        let signature = signatures.read(seq.get(functions, s.next))
        let mut pure = false
        if s.pure_next < seq.len(pure_functions) {
            if noun.as_field(seq.get(pure_functions, s.pure_next)) == as_field(s.next) {
                pure = true
                s.pure_next = syntax.inc(s.pure_next)
            }
        }
        let mut stored = noun.atom(0)
        if (intrinsic_bindings.kind(intrinsics, s.next) == intrinsic_abi.NONE) == false {
            stored = body_store.opaque()
        } else {
            let parsed = body.function_with_intrinsics(source, signature, functions, params, scope, consts, pure, cap, start, end, imports, intrinsics)
            s.error = parsed.error
            if (s.error.code == syntax.ZERO) == false { return s }
            let checked = coverage.check(parsed)
            s.error = checked.error
            if (s.error.code == syntax.ZERO) == false { return s }
            stored = body_store.pack(parsed, checked.flags)
        }
        if seq.len(s.bodies) == cap { s.error = syntax.error(7, signature.name.start, signature.name.end) return s }
        s.bodies = seq.push(s.bodies, stored, cap)
        s.next = syntax.inc(s.next)
    }
    s
}

// Every declaration is checked, even if its callable binding is replaced later.
#[pure]
#[requires((syntax.SOURCE_CAP < bytes.len(source)) == false)]
#[requires((syntax.TABLE_CAP < cap) == false)]
pub fn check(source: bytes.Bytes, functions: seq.Seq, params: seq.Seq, pure_functions: seq.Seq, scope: type_registry.Scope, consts: constants.Scope, cap: U32) -> Checked {
    check_range(source, functions, params, pure_functions, scope, consts, cap,
        syntax.ZERO, seq.len(functions), function_imports.empty(), seq.empty())
}

// Pure IDs belong to this owner's range and retain declaration order. Every
// appended body occupies its global declaration ID, including replaced bodies.
#[pure]
#[requires((syntax.SOURCE_CAP < bytes.len(source)) == false)]
#[requires((syntax.TABLE_CAP < cap) == false)]
#[requires((end < start) == false)]
#[requires((seq.len(functions) < end) == false)]
#[requires(seq.len(bodies) == start)]
pub fn check_range(source: bytes.Bytes, functions: seq.Seq, params: seq.Seq, pure_functions: seq.Seq, scope: type_registry.Scope, consts: constants.Scope, cap: U32, start: U32, end: U32, imports: function_imports.View, bodies: seq.Seq) -> Checked {
    check_range_with_intrinsics(source, functions, params, pure_functions, scope, consts, cap,
        start, end, imports, bodies, intrinsic_bindings.empty())
}

#[pure]
#[requires((syntax.SOURCE_CAP < bytes.len(source)) == false)]
#[requires((syntax.TABLE_CAP < cap) == false)]
#[requires((end < start) == false)]
#[requires((seq.len(functions) < end) == false)]
#[requires(seq.len(bodies) == start)]
pub fn check_range_with_intrinsics(source: bytes.Bytes, functions: seq.Seq, params: seq.Seq, pure_functions: seq.Seq, scope: type_registry.Scope, consts: constants.Scope, cap: U32, start: U32, end: U32, imports: function_imports.View, bodies: seq.Seq, intrinsics: intrinsic_bindings.Bank) -> Checked {
    let zero = syntax.ZERO
    let mut s = Checked { bodies, next: start, error: syntax.error(0, zero, zero), pure_next: zero }
    if syntax.either(syntax.either((end < start), (seq.len(functions) < end)), (seq.len(bodies) == start) == false) {
        s.error = syntax.error(7, zero, zero) return s
    }
    for turn in 0..512 {
        s = chunk(source, functions, params, pure_functions, scope, consts, s, cap, start, end, imports, intrinsics)
        if syntax.either(s.next == end, (s.error.code == zero) == false) { return s }
    }
    s.error = syntax.error(7, zero, zero)
    s
}

sources.std.compiler.nox.check_scope:
module std.compiler.nox.check_scope

use std.nox.seq
use std.compiler.nox.type_registry
use std.compiler.nox.constants
use std.compiler.nox.function_imports
use std.compiler.nox.syntax
use std.compiler.nox.intrinsic_bindings

// One immutable scope per checked function. Expressions share it while their
// lexical bindings change, without rebuilding the cold module metadata.
pub struct Scope {
    pub pure: Bool, pub types: type_registry.Scope,
    pub functions: seq.Seq, pub params: seq.Seq, pub constants: constants.Scope,
    pub function_start: U32, pub function_end: U32, pub imported_functions: function_imports.View,
    pub intrinsics: intrinsic_bindings.Bank
}

#[pure]
pub fn empty() -> Scope {
    local(false, type_registry.empty(), seq.empty(), seq.empty(), constants.empty())
}

// Whole-bank scope for the existing single-source and component entrypoints.
#[pure]
pub fn local(pure: Bool, types: type_registry.Scope, functions: seq.Seq, params: seq.Seq, constants: constants.Scope) -> Scope {
    Scope { pure, types, functions, params, constants, function_start: syntax.ZERO,
        function_end: seq.len(functions), imported_functions: function_imports.empty(), intrinsics: intrinsic_bindings.empty() }
}

sources.std.compiler.nox.code_plan:
module std.compiler.nox.code_plan

use vm.nox.noun
use vm.core.convert
use std.nox.seq
use std.nox.tree
use std.compiler.nox.syntax
use std.compiler.nox.body_store
use std.compiler.nox.function_plan
use std.compiler.nox.signatures

// Functions retain their old slots; loops follow, grouped by sorted owner.
pub struct Plan { pub count: U32, pub bases: Noun, pub next: U32, pub failed: Bool, pub needs_get: Bool, pub get_slot: U32 }

#[pure]
fn chunk(bodies: seq.Seq, functions: function_plan.Plan, input: Plan, cap: U32) -> Plan {
    let mut s = input
    for turn in 0..8 {
        if s.next == seq.len(functions.order) { return s }
        let owner = as_u32(noun.as_field(seq.get(functions.order, s.next)))
        let stored = seq.get(bodies, owner)
        if body_store.needs_get(stored) { s.needs_get = true }
        let count = body_store.loop_count(stored)
        let total = as_u32(as_field(s.count) + as_field(count))
        if cap < total { s.failed = true return s }
        s.bases = tree.set(s.bases, seq.len(bodies), owner, noun.atom(as_field(s.count)))
        s.count = total
        s.next = syntax.inc(s.next)
    }
    s
}

#[pure]
fn finish(input: Plan, cap: U32) -> Plan {
    let mut s = input
    if s.needs_get {
        if (s.count < cap) == false { s.failed = true return s }
        s.get_slot = s.count
        s.count = syntax.inc(s.count)
    }
    s
}

#[pure]
#[requires((syntax.TABLE_CAP < cap) == false)]
pub fn extend(bodies: seq.Seq, functions: function_plan.Plan, cap: U32) -> Plan {
    let mut s = Plan { count: seq.len(functions.order), bases: tree.empty(tree.shape(seq.len(bodies)).height),
        next: syntax.ZERO, failed: cap < seq.len(functions.order), needs_get: false, get_slot: signatures.NONE }
    for turn in 0..512 {
        if s.failed { return s }
        if s.next == seq.len(functions.order) { return finish(s, cap) }
        s = chunk(bodies, functions, s, cap)
    }
    if (s.next == seq.len(functions.order)) == false { s.failed = true return s }
    finish(s, cap)
}

sources.std.compiler.nox.codegen:
module std.compiler.nox.codegen

use vm.nox.noun
use vm.core.convert
use vm.core.field
use std.nox.seq
use std.nox.tree
use std.compiler.nox.syntax
use std.compiler.nox.ast
use std.compiler.nox.emit
use std.compiler.nox.formula
use std.compiler.nox.call_codegen
use std.compiler.nox.builtin_gen
use std.compiler.nox.digest_gen
use std.compiler.nox.aggregate_gen
use std.compiler.nox.record_edit_gen
use std.compiler.nox.array_gen
use std.compiler.nox.types
use std.compiler.nox.signatures
use std.compiler.nox.flow

const HALF: Field = 9223372034707292161
pub struct Compiled { pub formula: Noun, pub error: syntax.Error }
// Deepest ancestor first; every sibling axis reads the old subject.
#[pure]
fn zipper(slot: U32, shape: tree.Shape) -> Noun {
    let mut path = noun.atom(0)
    let mut offset = slot
    let mut capacity = shape.capacity
    let mut address: Field = 7
    for level in 0..12 {
        if level == shape.height { return path }
        capacity = capacity * HALF
        let mut right: Field = 0
        let mut sibling = address * 2 + 1
        address = address * 2
        if (offset < as_u32(capacity)) == false {
            right = 1
            sibling = address
            address = address + 1
            offset = as_u32(field.sub(as_field(offset), capacity))
        }
        path = noun.pair(noun.pair(noun.atom(right), noun.atom(sibling)), path)
    }
    path
}

#[pure]
fn frame(value: formula.Value) -> formula.Value {
    formula.Value { formula: formula.cons(formula.axis(2), formula.cons(formula.axis(6), value.formula)), depth: as_u32(as_field(value.depth) + 4) }
}

// The replacement occurs once; reconstruction preserves all sibling slots.
#[pure]
pub fn edit(slot: U32, shape: tree.Shape, replacement: formula.Value) -> formula.Value {
    let mut path = zipper(slot, shape)
    let mut result = replacement
    for level in 0..12 {
        if level == shape.height { return frame(result) }
        let step = noun.head(path)
        let sibling = formula.axis(noun.as_field(noun.tail(step)))
        if noun.as_field(noun.head(step)) == 0 { result.formula = formula.cons(result.formula, sibling) }
        else { result.formula = formula.cons(sibling, result.formula) }
        result.depth = as_u32(as_field(formula.maximum(result.depth, as_u32(1))) + 2)
        path = noun.tail(path)
    }
    frame(result)
}

pub struct Expressions { pub values: seq.Seq, pub next: U32, pub failed: Bool }

#[pure]
fn expression_chunk(nodes: seq.Seq, shape: tree.Shape, input: Expressions, context: call_codegen.Context, depth_cap: U32) -> Expressions {
    let mut s = input
    for turn in 0..8 {
        if s.next == seq.len(nodes) { return s }
        let node = seq.get(nodes, s.next)
        let kind = ast.kind(node)
        let mut code = emit.literal(ast.left(node))
        let mut depth = as_u32(1)
        if kind == 1 { code = formula.axis(7 * shape.capacity + ast.left(node)) }
        else if kind == ast.BUILTIN {
            let called = builtin_gen.generate(as_u32(ast.left(node)), s.values, context.arguments, as_u32(ast.right(node)))
            code = called.formula
            depth = called.depth
        }
        else if syntax.either(kind == ast.TUPLE_VALUE, kind == ast.RECORD_VALUE) {
            let aggregate = aggregate_gen.generate(s.values, context.arguments, as_u32(ast.right(node)), as_u32(ast.left(node)))
            code = aggregate.formula
            depth = aggregate.depth
        }
        else if kind == ast.ARRAY_VALUE {
            let aggregate = array_gen.values(s.values, context.arguments, as_u32(ast.right(node)), as_u32(ast.left(node)))
            code = aggregate.formula
            depth = aggregate.depth
        }
        else if kind == ast.ARRAY_INDEX {
            if context.get_slot == signatures.NONE { s.failed = true return s }
            let length = types.array_info(ast.ty(seq.get(nodes, as_u32(ast.left(node))))).length
            let indexed = array_gen.read(formula.value(s.values, as_u32(ast.left(node))), formula.value(s.values, as_u32(ast.right(node))), length, context.table, context.get_slot)
            code = indexed.formula
            depth = indexed.depth
        }
        else if kind == ast.RECORD_EDIT {
            let edited = record_edit_gen.generate(nodes, s.values, as_u32(ast.left(node)), as_u32(ast.right(node)))
            code = edited.formula
            depth = edited.depth
        }
        else if kind == ast.PROJECT {
            let projection = flow.compose(formula.value(s.values, as_u32(ast.left(node))), flow.axis(ast.right(node)))
            code = projection.formula
            depth = projection.depth
        }
        else if kind == ast.DIGEST_INDEX {
            let indexed = digest_gen.read(formula.value(s.values, as_u32(ast.left(node))), formula.value(s.values, as_u32(ast.right(node))))
            code = indexed.formula
            depth = indexed.depth
        }
        else if kind == ast.CALL {
            let called = call_codegen.generate(context, s.values, as_u32(ast.left(node)), as_u32(ast.right(node)))
            if called.failed { s.failed = true return s }
            code = called.output.formula
            depth = called.output.depth
        }
        else if syntax.either(syntax.either(kind == ast.LITERAL, kind == ast.BOOLEAN), syntax.either(kind == ast.UNIT_VALUE, kind == ast.CONSTANT)) == false {
            let left = formula.value(s.values, as_u32(ast.left(node)))
            let right = formula.value(s.values, as_u32(ast.right(node)))
            code = emit.binary(as_u32(kind), left.formula, right.formula)
            depth = as_u32(as_field(formula.maximum(left.depth, right.depth)) + 2)
        }
        // RES1 wraps ART1 with nine noun levels above the formula.
        if depth_cap < as_u32(as_field(depth) + 9) { s.failed = true return s }
        s.values = seq.push(s.values, noun.pair(noun.atom(as_field(depth)), code), seq.len(nodes))
        s.next = syntax.inc(s.next)
    }
    s
}

#[pure]
pub fn with_calls(nodes: seq.Seq, shape: tree.Shape, context: call_codegen.Context, depth_cap: U32) -> Expressions {
    let mut s = Expressions { values: seq.empty(), next: syntax.ZERO, failed: false }
    for block in 0..512 {
        s = expression_chunk(nodes, shape, s, context, depth_cap)
        if syntax.either(s.failed, s.next == seq.len(nodes)) { return s }
    }
    s.failed = true
    s
}

#[pure]
pub fn expressions(nodes: seq.Seq, shape: tree.Shape, depth_cap: U32) -> Expressions {
    with_calls(nodes, shape, call_codegen.empty(), depth_cap)
}

pub struct Statements { pub output: formula.Value, pub remaining: U32, pub failed: Bool }

#[pure]
fn statement_chunk(statements: seq.Seq, values: seq.Seq, shape: tree.Shape, input: Statements, depth_cap: U32) -> Statements {
    let mut s = input
    for turn in 0..8 {
        if s.remaining == syntax.ZERO { return s }
        s.remaining = syntax.dec(s.remaining)
        let statement = seq.get(statements, s.remaining)
        let transformer = edit(as_u32(noun.as_field(noun.head(statement))), shape,
            formula.value(values, as_u32(noun.as_field(noun.tail(statement)))))
        s.output.formula = formula.compose(transformer.formula, s.output.formula)
        s.output.depth = as_u32(as_field(formula.maximum(transformer.depth, syntax.inc(s.output.depth))) + 2)
        if depth_cap < as_u32(as_field(s.output.depth) + 9) { s.failed = true return s }
    }
    s
}

#[pure]
pub fn statements(statements: seq.Seq, values: seq.Seq, shape: tree.Shape, result: U32, depth_cap: U32) -> Statements {
    let mut s = Statements { output: formula.value(values, result), remaining: seq.len(statements), failed: false }
    for block in 0..512 {
        s = statement_chunk(statements, values, shape, s, depth_cap)
        if syntax.either(s.failed, s.remaining == syntax.ZERO) { return s }
    }
    s.failed = true
    s
}

#[pure]
#[requires((syntax.TABLE_CAP < seq.len(nodes)) == false)]
#[requires((syntax.TABLE_CAP < locals) == false)]
pub fn generate(nodes: seq.Seq, writes: seq.Seq, result: U32, locals: U32, depth_cap: U32) -> Compiled {
    let zero = syntax.ZERO
    let failure = Compiled { formula: noun.atom(0), error: syntax.error(7, zero, zero) }
    let shape = tree.shape(locals)
    let emitted = expressions(nodes, shape, depth_cap)
    if emitted.failed { return failure }
    let folded = statements(writes, emitted.values, shape, result, depth_cap)
    if folded.failed { return failure }
    let mut output = folded.output
    if (locals == zero) == false {
        let frame = noun.pair(noun.atom(0), noun.pair(noun.atom(0), tree.empty(shape.height)))
        output.formula = formula.compose(noun.pair(noun.atom(1), frame), output.formula)
        output.depth = as_u32(as_field(formula.maximum(as_u32(as_field(shape.height) + 3), syntax.inc(output.depth))) + 2)
    }
    if depth_cap < as_u32(as_field(output.depth) + 9) { return failure }
    Compiled { formula: output.formula, error: syntax.error(0, zero, zero) }
}

sources.std.compiler.nox.const_module:
module std.compiler.nox.const_module

use std.nox.bytes
use std.nox.seq
use std.compiler.nox.syntax
use std.compiler.nox.lexer
use std.compiler.nox.constants
use std.compiler.nox.const_parse
use std.compiler.nox.constant_imports
use std.compiler.nox.constant_exports

pub struct Published { pub exports: constant_exports.Bank, pub error: syntax.Error }
struct Scan { scope: constants.Scope, token: syntax.Token, error: syntax.Error, done: Bool }

#[pure]
fn step(source: bytes.Bytes, input: Scan, cap: U32) -> Scan {
    let mut s = input
    if s.token.kind == syntax.ZERO { s.done = true return s }
    let mut public = false
    if s.token.kind == as_u32(40) { public = true s.token = lexer.next(source, s.token.end) }
    if (s.token.kind == as_u32(45)) == false {
        let mut code: Field = 6
        if s.token.kind == as_u32(14) { code = 1 }
        if s.token.kind == syntax.ZERO { code = 2 }
        s.error = syntax.error(code, s.token.start, s.token.end)
        return s
    }
    let parsed = const_parse.parse(source, s.token, s.scope, public, cap)
    s.scope = parsed.scope
    s.token = parsed.token
    s.error = parsed.error
    s
}

#[pure]
fn chunk(source: bytes.Bytes, input: Scan, cap: U32) -> Scan {
    let mut s = input
    for turn in 0..16 {
        s = step(source, s, cap)
        if syntax.either(s.done, (s.error.code == syntax.ZERO) == false) { return s }
    }
    s
}

// Resolve every declaration before selecting final public exports. Replaced
// and private declarations retain the seed's validation obligations.
#[pure]
#[requires((syntax.SOURCE_CAP < bytes.len(source)) == false)]
#[requires((syntax.TABLE_CAP < cap) == false)]
pub fn parse(source: bytes.Bytes, start: U32, owner: bytes.Bytes, imports: constant_imports.View, cap: U32) -> constants.Resolved {
    let mut scope = constants.empty()
    scope.owner = owner
    scope.imports = imports
    let mut s = Scan { scope, token: lexer.next(source, start), error: syntax.error(0, start, start), done: false }
    for block in 0..257 {
        s = chunk(source, s, cap)
        if (s.error.code == syntax.ZERO) == false { return constants.Resolved { scope: s.scope, error: s.error } }
        if s.done { return constants.resolve(source, s.scope) }
    }
    constants.Resolved { scope: s.scope, error: syntax.error(7, s.token.start, s.token.end) }
}

#[pure]
#[requires((syntax.TABLE_CAP < seq.len(scope.declarations)) == false)]
pub fn publish(source: bytes.Bytes, scope: constants.Scope, owner: U32, bank: constant_exports.Bank, cap: U32) -> Published {
    let mut s = Published { exports: bank, error: syntax.error(0, syntax.ZERO, syntax.ZERO) }
    for id in 0..4096 {
        if id == seq.len(scope.declarations) { return s }
        let item = constants.read(seq.get(scope.declarations, id))
        if item.public {
            let final = constants.find(source, item.name, scope)
            if final.index == id {
                if constant_exports.len(s.exports) == cap {
                    s.error = syntax.error(7, item.name.start, item.name.end) return s
                }
                let origin = constants.terminal(scope, id, owner)
                let binding = constant_exports.Binding { owner, name: item.name, ty: item.ty,
                    value: origin.literal.value, literal_owner: origin.owner, literal: origin.literal }
                s.exports = constant_exports.push(s.exports, binding, cap)
            }
        }
    }
    s
}

sources.std.compiler.nox.const_parse:
module std.compiler.nox.const_parse

use vm.core.convert
use vm.core.field
use std.nox.bytes
use std.nox.seq
use std.compiler.nox.syntax
use std.compiler.nox.lexer
use std.compiler.nox.ast
use std.compiler.nox.constants
use std.compiler.nox.types
use std.compiler.nox.qualified_name

pub struct Parsed { pub scope: constants.Scope, pub token: syntax.Token, pub error: syntax.Error }

// The lexer has already checked u64, but its value is reduced in Goldilocks.
// Reject before multiplying so narrowing can never hide a raw U32 overflow.
#[pure]
fn uint32(source: bytes.Bytes, token: syntax.Token) -> syntax.Error {
    let mut pos = token.start
    let mut value = syntax.ZERO
    for turn in 0..4096 {
        if pos == token.end { return syntax.error(0, token.start, token.end) }
        let digit = as_u32(field.sub(as_field(bytes.get(source, pos)), 48))
        if syntax.either(as_u32(429496729) < value, syntax.both(value == as_u32(429496729), as_u32(5) < digit)) {
            return syntax.error(5, token.start, token.end)
        }
        value = as_u32(as_field(value) * 10 + as_field(digit))
        pos = syntax.inc(pos)
    }
    syntax.error(7, token.start, token.end)
}

#[pure]
fn boundary(kind: U32) -> Bool {
    if kind == as_u32(46) { return true }
    syntax.either(syntax.either(kind == syntax.ZERO, kind == as_u32(45)), syntax.either(kind == as_u32(11), syntax.either(kind == as_u32(39), kind == as_u32(40))))
}

#[pure]
fn expected(token: syntax.Token) -> syntax.Error {
    if token.kind == as_u32(14) { return syntax.error(1, token.start, token.end) }
    if syntax.either(token.kind == as_u32(13), syntax.either(token.kind == as_u32(41), token.kind == as_u32(43))) { return syntax.error(6, token.start, token.end) }
    syntax.error(2, token.start, token.end)
}

#[pure]
fn unexpected(token: syntax.Token) -> syntax.Error {
    // Complete arithmetic/call initializers are semantic errors in the seed.
    if syntax.either(token.kind == as_u32(3), syntax.either(token.kind == as_u32(4), token.kind == as_u32(5))) {
        return syntax.error(5, token.start, token.end)
    }
    if syntax.either(token.kind == as_u32(19), syntax.either(token.kind == as_u32(29), token.kind == as_u32(30))) { return syntax.error(5, token.start, token.end) }
    expected(token)
}

struct Groups { token: syntax.Token, count: U32, error: syntax.Error }

#[pure]
fn groups(source: bytes.Bytes, token: syntax.Token, cap: U32) -> Groups {
    let mut s = Groups { token, count: syntax.ZERO, error: syntax.error(0, token.start, token.end) }
    let mut nesting = cap
    if syntax.STACK_CAP < nesting { nesting = syntax.STACK_CAP }
    for turn in 0..65 {
        if (s.token.kind == as_u32(5)) == false { return s }
        if s.count == nesting { s.error = syntax.error(7, s.token.start, s.token.end) return s }
        s.count = syntax.inc(s.count)
        s.token = lexer.next(source, s.token.end)
    }
    s.error = syntax.error(7, s.token.start, s.token.end)
    s
}

#[pure]
fn close(source: bytes.Bytes, input: Parsed, groups: U32, item: constants.Declaration, cap: U32) -> Parsed {
    let mut s = input
    let mut remaining = groups
    for turn in 0..65 {
        if remaining == syntax.ZERO {
            if boundary(s.token.kind) == false { s.error = unexpected(s.token) return s }
            s.scope.declarations = seq.push(s.scope.declarations, constants.pack(item), cap)
            return s
        }
        if (s.token.kind == as_u32(6)) == false { s.error = unexpected(s.token) return s }
        remaining = syntax.dec(remaining)
        s.token = lexer.next(source, s.token.end)
    }
    s.error = syntax.error(7, s.token.start, s.token.end)
    s
}

#[pure]
#[requires((syntax.SOURCE_CAP < bytes.len(source)) == false)]
#[requires((syntax.TABLE_CAP < cap) == false)]
pub fn parse(source: bytes.Bytes, token: syntax.Token, scope: constants.Scope, public: Bool, cap: U32) -> Parsed {
    let mut s = Parsed { scope, token, error: syntax.error(0, token.start, token.end) }
    if seq.len(scope.declarations) == cap { s.error = syntax.error(7, token.start, token.end) return s }
    let name = lexer.next(source, token.end)
    if (name.kind == as_u32(1)) == false { s.error = expected(name) return s }
    s.token = lexer.next(source, name.end)
    if (s.token.kind == as_u32(17)) == false { s.error = expected(s.token) return s }
    s.token = lexer.next(source, s.token.end)
    let mut ty = types.FIELD
    if s.token.kind == as_u32(28) { ty = types.UINT32 }
    else if (s.token.kind == as_u32(12)) == false { s.error = ast.failed(s.token, 5) return s }
    s.token = lexer.next(source, s.token.end)
    if (s.token.kind == as_u32(18)) == false { s.error = expected(s.token) return s }
    s.token = lexer.next(source, s.token.end)
    let grouped = groups(source, s.token, cap)
    s.error = grouped.error
    if (s.error.code == syntax.ZERO) == false { return s }
    s.token = grouped.token
    let mut initializer = s.token
    if syntax.either(initializer.kind == as_u32(1), initializer.kind == as_u32(2)) == false { s.error = ast.failed(initializer, 5) return s }
    if syntax.both(initializer.kind == as_u32(2), ty == types.UINT32) {
        s.error = uint32(source, initializer)
        if (s.error.code == syntax.ZERO) == false { return s }
    }
    if initializer.kind == as_u32(1) {
        let name = qualified_name.parse(source, initializer)
        s.error = name.error
        if (s.error.code == syntax.ZERO) == false { return s }
        if (bytes.len(name.prefix) == syntax.ZERO) == false {
            initializer = syntax.token(as_field(constants.QUALIFIED), name.start, name.end, 0)
        }
        s.token = name.token
    } else { s.token = lexer.next(source, initializer.end) }
    close(source, s, grouped.count, constants.Declaration { name, ty, public, initializer }, cap)
}

sources.std.compiler.nox.constant_exports:
module std.compiler.nox.constant_exports

use vm.nox.noun
use vm.core.field
use std.nox.bytes
use std.nox.seq
use std.nox.tree
use std.compiler.nox.syntax

// Export IDs are stable across dependency modules. Linked lists index only
// final public bindings; source spans always belong to their recorded owner.
pub struct Bank { records: seq.Seq, heads: Noun, modules: U32 }
pub struct Binding {
    pub owner: U32, pub name: syntax.Token, pub ty: Field, pub value: Field,
    pub literal_owner: U32, pub literal: syntax.Token
}
pub struct Found { pub exists: Bool, pub id: U32 }

#[pure]
pub fn empty(modules: U32) -> Bank {
    Bank { records: seq.empty(), heads: tree.empty(tree.shape(modules).height), modules }
}

#[pure]
pub fn len(bank: Bank) -> U32 { seq.len(bank.records) }

#[pure]
fn span(token: syntax.Token) -> Noun {
    noun.pair(noun.atom(as_field(token.start)), noun.atom(as_field(token.end)))
}

#[pure]
fn token(value: Noun, kind: Field, literal: Field) -> syntax.Token {
    syntax.token(kind, as_u32(noun.as_field(noun.head(value))), as_u32(noun.as_field(noun.tail(value))), literal)
}

#[pure]
#[requires(id < len(bank))]
pub fn read(bank: Bank, id: U32) -> Binding {
    let row = noun.tail(seq.get(bank.records, id))
    let name = noun.tail(row)
    let ty = noun.tail(name)
    let value = noun.tail(ty)
    let origin = noun.tail(value)
    let number = noun.as_field(noun.head(value))
    Binding { owner: as_u32(noun.as_field(noun.head(row))), name: token(noun.head(name), 1, 0),
        ty: noun.as_field(noun.head(ty)), value: number,
        literal_owner: as_u32(noun.as_field(noun.head(origin))), literal: token(noun.tail(origin), 2, number) }
}

// Callers check source-work capacity before publishing. The bank keeps its own
// typed storage and never admits externally supplied serialized record handles.
#[pure]
#[requires(len(bank) < cap)]
pub fn push(bank: Bank, item: Binding, cap: U32) -> Bank {
    assert(item.owner < bank.modules)
    assert(item.literal_owner < bank.modules)
    let id = len(bank)
    let next = tree.get(bank.heads, bank.modules, item.owner)
    let origin = noun.pair(noun.atom(as_field(item.literal_owner)), span(item.literal))
    let value = noun.pair(noun.atom(item.value), origin)
    let row = noun.pair(noun.atom(as_field(item.owner)), noun.pair(span(item.name), noun.pair(noun.atom(item.ty), value)))
    Bank { records: seq.push(bank.records, noun.pair(next, row), cap),
        heads: tree.set(bank.heads, bank.modules, item.owner, noun.atom(as_field(id) + 1)), modules: bank.modules }
}

// Two independent source buffers prevent a foreign declaration's offsets from
// accidentally selecting unrelated bytes in the importing source.
#[pure]
fn same(caller: bytes.Bytes, query: syntax.Token, source: bytes.Bytes, name: syntax.Token) -> Bool {
    if (field.sub(as_field(query.end), as_field(query.start)) == field.sub(as_field(name.end), as_field(name.start))) == false { return false }
    let mut a = query.start
    let mut b = name.start
    for step in 0..65536 {
        if a == query.end { return true }
        if (bytes.get(caller, a) == bytes.get(source, b)) == false { return false }
        a = syntax.inc(a)
        b = syntax.inc(b)
    }
    a == query.end
}

#[pure]
#[requires(owner < bank.modules)]
#[requires((syntax.TABLE_CAP < len(bank)) == false)]
pub fn find(bank: Bank, owner: U32, source: bytes.Bytes, caller: bytes.Bytes, query: syntax.Token) -> Found {
    let mut cursor = as_u32(noun.as_field(tree.get(bank.heads, bank.modules, owner)))
    for step in 0..4096 {
        if cursor == syntax.ZERO { return Found { exists: false, id: syntax.ZERO } }
        let id = syntax.dec(cursor)
        // Only the name and predecessor participate in lookup. This private
        // bank already owns the complete type/value/literal provenance row.
        let row = seq.get(bank.records, id)
        let name = token(noun.head(noun.tail(noun.tail(row))), 1, 0)
        if same(caller, query, source, name) { return Found { exists: true, id } }
        cursor = as_u32(noun.as_field(noun.head(row)))
    }
    Found { exists: false, id: syntax.ZERO }
}

sources.std.compiler.nox.constant_imports:
module std.compiler.nox.constant_imports

use vm.nox.noun
use std.nox.bytes
use std.compiler.nox.syntax
use std.compiler.nox.qualified_name
use std.compiler.nox.constant_exports

// An immutable direct-use view. The graph owns cached validated sources/names;
// each dependency publishes its final exports before this view is constructed.
pub struct View {
    pub sources: bytes.BytesTable, pub names: bytes.BytesTable,
    pub exports: constant_exports.Bank, pub uses: Noun
}

#[pure]
pub fn empty() -> View {
    View { sources: bytes.table_empty(), names: bytes.table_empty(),
        exports: constant_exports.empty(syntax.ZERO), uses: noun.atom(0) }
}

#[pure]
pub fn lookup(source: bytes.Bytes, name: qualified_name.Name, view: View) -> constant_exports.Found {
    let mut found = constant_exports.Found { exists: false, id: syntax.ZERO }
    if bytes.len(name.prefix) == syntax.ZERO { return found }
    let mut rest = view.uses
    for step in 0..4096 {
        if noun.eq(rest, noun.atom(0)) { return found }
        // module_store.Use starts with its compact target ID. Lookup retains
        // the complete record while reading only this field from the graph.
        let target = as_u32(noun.as_field(noun.head(noun.head(rest))))
        let owner = bytes.table_get(view.names, target)
        if qualified_name.matches_owner(name.prefix, owner) {
            let candidate = constant_exports.find(view.exports, target,
                bytes.table_get(view.sources, target), source, name.member)
            // Missing/private members of a later same-basename owner leave the
            // earlier public symbol visible. Repeated uses retain source order.
            if candidate.exists { found = candidate }
        }
        rest = noun.tail(rest)
    }
    assert(noun.eq(rest, noun.atom(0)))
    found
}

sources.std.compiler.nox.constants:
module std.compiler.nox.constants

use vm.nox.noun
use vm.core.convert
use vm.core.field
use std.nox.bytes
use std.nox.seq
use std.nox.tree
use std.compiler.nox.syntax
use std.compiler.nox.symbols
use std.compiler.nox.types
use std.compiler.nox.lexer
use std.compiler.nox.qualified_name
use std.compiler.nox.constant_exports
use std.compiler.nox.constant_imports

// Declaration names remain local to source; imported terminal IDs address an
// immutable export bank whose records retain their own source provenance.
pub struct Scope { pub owner: bytes.Bytes, pub declarations: seq.Seq, pub memo: Noun, pub imports: constant_imports.View }
pub struct Declaration { pub name: syntax.Token, pub ty: Field, pub public: Bool, pub initializer: syntax.Token }
pub struct Found { pub exists: Bool, pub index: U32 }
pub struct Value { pub exists: Bool, pub ty: Noun, pub value: Field, pub public: Bool }
pub struct Resolved { pub scope: Scope, pub error: syntax.Error }
pub struct Origin { pub owner: U32, pub literal: syntax.Token }
pub const QUALIFIED: U32 = 48
struct State { scope: Scope, next: U32, cursor: U32, trail: Noun, error: syntax.Error }

#[pure]
pub fn empty() -> Scope {
    Scope { owner: bytes.empty(), declarations: seq.empty(), memo: noun.atom(0), imports: constant_imports.empty() }
}

#[pure]
fn span(token: syntax.Token) -> Noun { noun.pair(noun.atom(as_field(token.start)), noun.atom(as_field(token.end))) }

// Name is first so symbols.same compares every byte, including long prefixes.
#[pure]
pub fn pack(item: Declaration) -> Noun {
    let mut public: Field = 0
    if item.public { public = 1 }
    let init = item.initializer
    let value = noun.pair(noun.atom(as_field(init.kind)), noun.pair(noun.atom(init.value), span(init)))
    noun.pair(span(item.name), noun.pair(noun.atom(item.ty), noun.pair(noun.atom(public), value)))
}

#[pure]
pub fn read(value: Noun) -> Declaration {
    let name = noun.head(value)
    let metadata = noun.tail(value)
    let flags = noun.tail(metadata)
    let init = noun.tail(flags)
    let payload = noun.tail(init)
    let location = noun.tail(payload)
    Declaration {
        name: syntax.token(1, as_u32(noun.as_field(noun.head(name))), as_u32(noun.as_field(noun.tail(name))), 0),
        ty: noun.as_field(noun.head(metadata)), public: noun.as_field(noun.head(flags)) == 1,
        initializer: syntax.token(noun.as_field(noun.head(init)), as_u32(noun.as_field(noun.head(location))), as_u32(noun.as_field(noun.tail(location))), noun.as_field(noun.head(payload))) }
}

#[pure]
#[requires((syntax.TABLE_CAP < seq.len(scope.declarations)) == false)]
pub fn find(source: bytes.Bytes, name: syntax.Token, scope: Scope) -> Found {
    let mut remaining = seq.len(scope.declarations)
    for turn in 0..4096 {
        if remaining == syntax.ZERO { return Found { exists: false, index: remaining } }
        remaining = syntax.dec(remaining)
        if symbols.same(source, name, seq.get(scope.declarations, remaining)) { return Found { exists: true, index: remaining } }
    }
    Found { exists: false, index: syntax.ZERO }
}

// Memo: 0 unseen, 1 visiting, local literal ID+2, or count+2+export ID.
// Only resolved scopes enter expression checking; aliases share the terminal.
#[pure]
pub fn terminal(scope: Scope, declaration: U32, owner: U32) -> Origin {
    let count = seq.len(scope.declarations)
    let status = as_u32(noun.as_field(tree.get(scope.memo, count, declaration)))
    assert(as_u32(1) < status)
    let id = syntax.dec(syntax.dec(status))
    if id < count { return Origin { owner, literal: read(seq.get(scope.declarations, id)).initializer } }
    let imported = constant_exports.read(scope.imports.exports, as_u32(field.sub(as_field(id), as_field(count))))
    Origin { owner: imported.literal_owner, literal: imported.literal }
}

#[pure]
pub fn lookup(source: bytes.Bytes, name: syntax.Token, scope: Scope) -> Value {
    let found = find(source, name, scope)
    if found.exists == false { return Value { exists: false, ty: noun.atom(types.INVALID), value: 0, public: false } }
    let item = read(seq.get(scope.declarations, found.index))
    let origin = terminal(scope, found.index, syntax.ZERO)
    Value { exists: true, ty: noun.atom(item.ty), value: origin.literal.value, public: item.public }
}

#[pure]
pub fn imported(source: bytes.Bytes, name: qualified_name.Name, scope: Scope) -> Value {
    let found = constant_imports.lookup(source, name, scope.imports)
    if found.exists == false { return Value { exists: false, ty: noun.atom(types.INVALID), value: 0, public: false } }
    let item = constant_exports.read(scope.imports.exports, found.id)
    Value { exists: true, ty: noun.atom(item.ty), value: item.value, public: true }
}

#[pure]
fn step(source: bytes.Bytes, input: State) -> State {
    let mut s = input
    let count = seq.len(s.scope.declarations)
    let status = noun.as_field(tree.get(s.scope.memo, count, s.cursor))
    if as_u32(1) < as_u32(status) {
        if noun.eq(s.trail, noun.atom(0)) {
            s.next = syntax.inc(s.next)
            s.cursor = s.next
        } else {
            s.cursor = as_u32(noun.as_field(noun.head(s.trail)))
            s.trail = noun.tail(s.trail)
            s.scope.memo = tree.set(s.scope.memo, count, s.cursor, noun.atom(status))
        }
        return s
    }
    let item = read(seq.get(s.scope.declarations, s.cursor))
    let init = item.initializer
    if status == 1 { s.error = syntax.error(5, init.start, init.end) return s }
    if init.kind == as_u32(2) {
        s.scope.memo = tree.set(s.scope.memo, count, s.cursor, noun.atom(as_field(s.cursor) + 2))
        return s
    }
    if init.kind == QUALIFIED {
        let name = qualified_name.parse(source, lexer.next(source, init.start))
        if (name.error.code == syntax.ZERO) == false { s.error = name.error return s }
        let found = constant_imports.lookup(source, name, s.scope.imports)
        if found.exists == false { s.error = syntax.error(5, init.start, init.end) return s }
        let target = constant_exports.read(s.scope.imports.exports, found.id)
        if (item.ty == target.ty) == false { s.error = syntax.error(5, init.start, init.end) return s }
        s.scope.memo = tree.set(s.scope.memo, count, s.cursor, noun.atom(as_field(count) + as_field(found.id) + 2))
        return s
    }
    let found = find(source, init, s.scope)
    if found.exists == false { s.error = syntax.error(5, init.start, init.end) return s }
    let target = read(seq.get(s.scope.declarations, found.index))
    if (item.ty == target.ty) == false { s.error = syntax.error(5, init.start, init.end) return s }
    s.scope.memo = tree.set(s.scope.memo, count, s.cursor, noun.atom(1))
    s.trail = noun.pair(noun.atom(as_field(s.cursor)), s.trail)
    s.cursor = found.index
    s
}

#[pure]
fn chunk(source: bytes.Bytes, input: State) -> State {
    let mut s = input
    for turn in 0..32 {
        s = step(source, s)
        if syntax.either(s.next == seq.len(s.scope.declarations), (s.error.code == syntax.ZERO) == false) { return s }
    }
    s
}

// Each declaration expands once, unwinds at most once and finishes once.
#[pure]
#[requires((syntax.TABLE_CAP < seq.len(scope.declarations)) == false)]
#[requires((syntax.SOURCE_CAP < bytes.len(source)) == false)]
pub fn resolve(source: bytes.Bytes, scope: Scope) -> Resolved {
    let zero = syntax.ZERO
    let mut s = State { scope, next: zero, cursor: zero, trail: noun.atom(0), error: syntax.error(0, zero, zero) }
    if seq.len(scope.declarations) == zero { return Resolved { scope, error: s.error } }
    s.scope.memo = tree.empty(tree.shape(seq.len(scope.declarations)).height)
    for turn in 0..512 {
        s = chunk(source, s)
        if syntax.either(s.next == seq.len(scope.declarations), (s.error.code == zero) == false) { return Resolved { scope: s.scope, error: s.error } }
    }
    Resolved { scope: s.scope, error: syntax.error(7, zero, zero) }
}

sources.std.compiler.nox.contexts:
module std.compiler.nox.contexts

use vm.nox.noun
use vm.core.convert
use std.compiler.nox.blocks

// A frame remembers its parent list/scope while one conditional arm is parsed.
// Phase0 awaits then; phase1 awaits else; phase2 owns a loop in condition.
// Synthetic else-if blocks close without
// consuming an extra source brace, using the same ownership as the seed parser.
pub struct Frame {
    pub statements: Noun, pub visible: Noun, pub returned: Bool,
    pub synthetic: Bool, pub start: U32, pub condition: U32,
    pub then_block: U32, pub phase: Field
}

#[pure]
pub fn pack(f: Frame) -> Noun {
    let environment = noun.pair(f.statements, f.visible)
    let flags = noun.pair(blocks.flag(f.returned), blocks.flag(f.synthetic))
    let owner = noun.pair(noun.atom(as_field(f.start)), noun.atom(as_field(f.condition)))
    let arms = noun.pair(noun.atom(as_field(f.then_block)), noun.atom(f.phase))
    noun.pair(noun.pair(environment, flags), noun.pair(owner, arms))
}

#[pure]
pub fn read(value: Noun) -> Frame {
    let parent = noun.head(value)
    let environment = noun.head(parent)
    let flags = noun.tail(parent)
    let child = noun.tail(value)
    let owner = noun.head(child)
    let arms = noun.tail(child)
    Frame { statements: noun.head(environment), visible: noun.tail(environment),
        returned: noun.as_field(noun.head(flags)) == 1, synthetic: noun.as_field(noun.tail(flags)) == 1,
        start: as_u32(noun.as_field(noun.head(owner))), condition: as_u32(noun.as_field(noun.tail(owner))),
        then_block: as_u32(noun.as_field(noun.head(arms))), phase: noun.as_field(noun.tail(arms)) }
}

sources.std.compiler.nox.control_gen:
module std.compiler.nox.control_gen

use vm.nox.noun
use vm.core.convert
use std.nox.seq
use std.nox.tree
use std.compiler.nox.syntax
use std.compiler.nox.blocks
use std.compiler.nox.body_state
use std.compiler.nox.body_store
use std.compiler.nox.coverage
use std.compiler.nox.codegen
use std.compiler.nox.formula
use std.compiler.nox.flow
use std.compiler.nox.block_gen
use std.compiler.nox.call_codegen
use std.compiler.nox.loop_gen
use std.compiler.nox.entry_frame

struct Linear { writes: seq.Seq, next: U32, eligible: Bool }

#[pure]
fn linear_chunk(statements: seq.Seq, input: Linear) -> Linear {
    let mut s = input
    for turn in 0..8 {
        if s.next == seq.len(statements) { return s }
        let current = blocks.read_statement(seq.get(statements, s.next))
        if (current.kind == blocks.WRITE) == false { s.eligible = false return s }
        s.writes = seq.push(s.writes, noun.pair(noun.atom(as_field(current.a)), noun.atom(as_field(current.b))), seq.len(statements))
        s.next = syntax.inc(s.next)
    }
    s
}

// Keep the canonical formula of the already accepted straight-line subset.
#[pure]
fn linear(statements: seq.Seq) -> Linear {
    let mut s = Linear { writes: seq.empty(), next: syntax.ZERO, eligible: true }
    for turn in 0..512 {
        s = linear_chunk(statements, s)
        if syntax.either(s.eligible == false, s.next == seq.len(statements)) { return s }
    }
    s.eligible = false
    s
}

pub struct Built { pub output: formula.Value, pub loops: seq.Seq, pub failed: Bool }

// A reusable body consumes the existing [table [0 frame]] subject. Callers
// initialize parameters and local padding; body emission never resets them.
#[pure]
#[requires(s.root < seq.len(s.blocks))]
pub fn reusable(s: body_store.Body, flags: Noun, locals: U32, context: call_codegen.Context, depth_cap: U32) -> Built {
    let failure = Built { output: flow.literal(0), loops: seq.empty(), failed: true }
    let shape = tree.shape(locals)
    let expressions = codegen.with_calls(s.nodes, shape, context, depth_cap)
    if expressions.failed { return failure }
    let root = blocks.read(seq.get(s.blocks, s.root))
    if syntax.both(root.has_tail, seq.len(s.blocks) == as_u32(1)) {
        let simple = linear(s.statements)
        if simple.eligible {
            let output = codegen.statements(simple.writes, expressions.values, shape, root.tail, depth_cap)
            return Built { output: output.output, loops: seq.empty(), failed: output.failed }
        }
    }
    let emitted = block_gen.generate(s.blocks, flags, s.statements, expressions.values, shape, depth_cap, s.loops, context)
    if emitted.failed { return failure }
    let loops = loop_gen.generate(s.loops, emitted.values, shape, context, depth_cap)
    if loops.failed { return failure }
    let output = flow.result(block_gen.read(emitted.values, s.root).output)
    Built { output, loops: loops.values, failed: depth_cap < as_u32(as_field(output.depth) + 9) }
}

#[pure]
pub fn standalone(built: Built, locals: U32, depth_cap: U32, structured: Bool) -> codegen.Compiled {
    let zero = syntax.ZERO
    let failure = codegen.Compiled { formula: noun.atom(0), error: syntax.error(7, zero, zero) }
    if syntax.either(built.failed, (seq.len(built.loops) == zero) == false) { return failure }
    let mut output = built.output
    if (locals == zero) == false {
        let shape = tree.shape(locals)
        let frame = noun.pair(noun.atom(0), noun.pair(noun.atom(0), tree.empty(shape.height)))
        let mut initial = formula.Value { formula: noun.pair(noun.atom(1), frame), depth: as_u32(as_field(shape.height) + 3) }
        if structured { initial = entry_frame.subject(flow.literal(0), shape.height) }
        output = flow.compose(initial, output)
    }
    if depth_cap < as_u32(as_field(output.depth) + 9) { return failure }
    codegen.Compiled { formula: output.formula, error: syntax.error(0, zero, zero) }
}

#[pure]
#[requires(s.root < seq.len(s.blocks))]
pub fn generate(s: body_state.State, depth_cap: U32) -> codegen.Compiled {
    let marked = coverage.check(s)
    if (marked.error.code == syntax.ZERO) == false { return codegen.Compiled { formula: noun.atom(0), error: marked.error } }
    let locals = seq.len(s.bindings)
    let mut context = call_codegen.empty()
    context.arguments = s.arguments
    let built = reusable(body_store.checked(s), marked.flags, locals, context, depth_cap)
    standalone(built, locals, depth_cap, false)
}

