module std.compiler.nox.expression_state

use std.compiler.nox.check_scope
use vm.nox.noun
use std.nox.seq
use std.compiler.nox.syntax

pub const CALL_MARKER: U32 = 27
// Internal marker: a parenthesized expression becomes a tuple at its first comma.
pub const TUPLE_MARKER: U32 = 38
pub const RECORD_MARKER: U32 = 42
pub const ARRAY_MARKER: U32 = 44
pub struct Context {
    pub bindings: seq.Seq, pub visible: Noun, pub scope: check_scope.Scope
}
pub struct Parsed {
    pub nodes: seq.Seq, pub arguments: seq.Seq, pub edges: Noun,
    pub value: U32, pub token: syntax.Token, pub error: syntax.Error, pub needs_get: Bool
}
pub struct State {
    // Delimiters update this list at every open/close. Keep it at the head of
    // the persistent record so nested groups do not rebuild its whole spine.
    pub frames: Noun, pub token: syntax.Token,
    pub ops: U32, pub operators: seq.Seq, pub nodes: seq.Seq,
    pub values: seq.Seq, pub vals: U32, pub operand: Bool,
    pub done: Bool, pub error: syntax.Error,
    pub capacity: U32, pub node_cap: U32,
    pub context: Context, pub before_block: Bool,
    pub arguments: seq.Seq, pub edges: Noun, pub needs_get: Bool
}

#[pure]
pub fn context(bindings: seq.Seq, visible: Noun, scope: check_scope.Scope) -> Context {
    Context { bindings, visible, scope }
}

sources.std.compiler.nox.flow:
module std.compiler.nox.flow

use vm.nox.noun
use vm.core.convert
use std.compiler.nox.formula
use std.compiler.nox.emit

// A formula and its exact noun depth travel together through every constructor.
#[pure]
pub fn axis(value: Field) -> formula.Value { formula.Value { formula: formula.axis(value), depth: as_u32(1) } }

#[pure]
pub fn literal(value: Field) -> formula.Value { formula.Value { formula: emit.literal(value), depth: as_u32(1) } }

#[pure]
pub fn cons(a: formula.Value, b: formula.Value) -> formula.Value {
    formula.Value { formula: formula.cons(a.formula, b.formula), depth: as_u32(as_field(formula.maximum(a.depth, b.depth)) + 2) }
}

#[pure]
pub fn compose(a: formula.Value, b: formula.Value) -> formula.Value {
    formula.Value { formula: formula.compose(a.formula, b.formula), depth: as_u32(as_field(formula.maximum(a.depth, as_u32(as_field(b.depth) + 1))) + 2) }
}

#[pure]
pub fn branch(condition: formula.Value, yes: formula.Value, no: formula.Value) -> formula.Value {
    let arms = noun.pair(yes.formula, no.formula)
    let depth = as_u32(as_field(formula.maximum(yes.depth, no.depth)) + 1)
    formula.Value { formula: noun.pair(noun.atom(4), noun.pair(condition.formula, arms)),
        depth: as_u32(as_field(formula.maximum(condition.depth, depth)) + 2) }
}

#[pure]
pub fn keep(subject: formula.Value) -> formula.Value { cons(literal(0), subject) }

#[pure]
pub fn returned(value: formula.Value) -> formula.Value { cons(literal(1), value) }

#[pure]
pub fn then(first: formula.Value, next: formula.Value) -> formula.Value {
    compose(first, branch(axis(2), compose(axis(3), next), axis(1)))
}

#[pure]
pub fn result(value: formula.Value) -> formula.Value {
    compose(value, branch(axis(2), literal(0), axis(3)))
}

// Evaluate the discarded expression once, and retain its original subject.
#[pure]
pub fn discard(value: formula.Value) -> formula.Value {
    compose(cons(value, axis(1)), keep(axis(3)))
}

sources.std.compiler.nox.formula:
module std.compiler.nox.formula

use vm.nox.noun
use vm.core.convert
use std.nox.seq

pub struct Value { pub formula: Noun, pub depth: U32 }

#[pure]
pub fn axis(value: Field) -> Noun { noun.pair(noun.atom(0), noun.atom(value)) }

#[pure]
pub fn cons(a: Noun, b: Noun) -> Noun { noun.pair(noun.atom(3), noun.pair(a, b)) }

// Fixed continuations are quoted; dynamic table dispatch uses apply instead.
#[pure]
pub fn compose(subject: Noun, code: Noun) -> Noun {
    noun.pair(noun.atom(2), noun.pair(subject, noun.pair(noun.atom(1), code)))
}

#[pure]
pub fn maximum(a: U32, b: U32) -> U32 { if a < b { return b } a }

#[pure]
pub fn value(values: seq.Seq, id: U32) -> Value {
    let record = seq.get(values, id)
    Value { formula: noun.tail(record), depth: as_u32(noun.as_field(noun.head(record))) }
}

#[pure]
pub fn pack(value: Value) -> Noun { noun.pair(noun.atom(as_field(value.depth)), value.formula) }

#[pure]
pub fn pair(a: Value, b: Value) -> Value {
    Value { formula: cons(a.formula, b.formula), depth: as_u32(as_field(maximum(a.depth, b.depth)) + 2) }
}

#[pure]
pub fn apply(subject: Value, producer: Value) -> Value {
    Value { formula: noun.pair(noun.atom(2), noun.pair(subject.formula, producer.formula)),
        depth: as_u32(as_field(maximum(subject.depth, producer.depth)) + 2) }
}

sources.std.compiler.nox.function_exports:
module std.compiler.nox.function_exports

use vm.nox.noun
use vm.core.field
use std.nox.bytes
use std.nox.seq
use std.nox.tree
use std.compiler.nox.syntax

// The driver publishes only final public bindings. Export record IDs and
// global callable targets are separate; signatures stay in the function bank.
pub struct Bank { records: seq.Seq, heads: Noun, modules: U32 }
pub struct Binding { pub owner: U32, pub name: syntax.Token, pub target: U32 }
pub struct Found { pub exists: Bool, pub target: U32 }

#[pure]
#[requires((syntax.TABLE_CAP < modules) == false)]
pub fn empty(modules: U32) -> Bank {
    assert((syntax.TABLE_CAP < modules) == false)
    Bank { records: seq.empty(), heads: tree.empty(tree.shape(modules).height), modules }
}

#[pure]
pub fn len(bank: Bank) -> U32 { seq.len(bank.records) }

#[pure]
fn span(token: syntax.Token) -> Noun {
    noun.pair(noun.atom(as_field(token.start)), noun.atom(as_field(token.end)))
}

#[pure]
#[requires(id < len(bank))]
pub fn read(bank: Bank, id: U32) -> Binding {
    let row = noun.tail(seq.get(bank.records, id))
    let rest = noun.tail(row)
    let name = noun.head(rest)
    Binding { owner: as_u32(noun.as_field(noun.head(row))),
        name: syntax.token(1, as_u32(noun.as_field(noun.head(name))), as_u32(noun.as_field(noun.tail(name))), 0),
        target: as_u32(noun.as_field(noun.tail(rest))) }
}

// Callers check source-work capacity before publishing. The opaque bank bounds
// its own storage and has no constructor for externally serialized records.
#[pure]
#[requires(len(bank) < cap)]
#[requires((syntax.TABLE_CAP < cap) == false)]
#[requires(item.owner < bank.modules)]
#[requires(item.target < syntax.TABLE_CAP)]
pub fn push(bank: Bank, item: Binding, cap: U32) -> Bank {
    assert((syntax.TABLE_CAP < cap) == false)
    assert(item.owner < bank.modules)
    assert(item.target < syntax.TABLE_CAP)
    let id = len(bank)
    let next = tree.get(bank.heads, bank.modules, item.owner)
    let row = noun.pair(noun.atom(as_field(item.owner)), noun.pair(span(item.name), noun.atom(as_field(item.target))))
    Bank { records: seq.push(bank.records, noun.pair(next, row), cap),
        heads: tree.set(bank.heads, bank.modules, item.owner, noun.atom(as_field(id) + 1)), modules: bank.modules }
}

// Name offsets belong to their own source buffers, including long identifiers.
#[pure]
fn same(caller: bytes.Bytes, query: syntax.Token, source: bytes.Bytes, name: syntax.Token) -> Bool {
    if (field.sub(as_field(query.end), as_field(query.start)) == field.sub(as_field(name.end), as_field(name.start))) == false { return false }
    let mut a = query.start
    let mut b = name.start
    for step in 0..65536 {
        if a == query.end { return true }
        if (bytes.get(caller, a) == bytes.get(source, b)) == false { return false }
        a = syntax.inc(a)
        b = syntax.inc(b)
    }
    a == query.end
}

#[pure]
#[requires(owner < bank.modules)]
#[requires((syntax.SOURCE_CAP < bytes.len(source)) == false)]
#[requires((syntax.SOURCE_CAP < bytes.len(caller)) == false)]
pub fn find(bank: Bank, owner: U32, source: bytes.Bytes, caller: bytes.Bytes, query: syntax.Token) -> Found {
    let mut cursor = as_u32(noun.as_field(tree.get(bank.heads, bank.modules, owner)))
    for step in 0..4096 {
        if cursor == syntax.ZERO { return Found { exists: false, target: syntax.ZERO } }
        let id = syntax.dec(cursor)
        // The bank owns validated records. Read this chain link once and decode
        // only the name until it matches; owner and target are not search keys.
        let row = seq.get(bank.records, id)
        let rest = noun.tail(noun.tail(row))
        let span = noun.head(rest)
        let name = syntax.token(1, as_u32(noun.as_field(noun.head(span))), as_u32(noun.as_field(noun.tail(span))), 0)
        if same(caller, query, source, name) {
            return Found { exists: true, target: as_u32(noun.as_field(noun.tail(rest))) }
        }
        cursor = as_u32(noun.as_field(noun.head(row)))
    }
    Found { exists: false, target: syntax.ZERO }
}

sources.std.compiler.nox.function_gen:
module std.compiler.nox.function_gen

use vm.nox.noun
use vm.core.convert
use std.nox.seq
use std.nox.tree
use std.compiler.nox.syntax
use std.compiler.nox.codegen
use std.compiler.nox.control_gen
use std.compiler.nox.body_store
use std.compiler.nox.function_plan
use std.compiler.nox.call_codegen
use std.compiler.nox.formula
use std.compiler.nox.flow
use std.compiler.nox.code_plan
use std.compiler.nox.entry_frame
use std.compiler.nox.array_gen

struct Emitted { table: Noun, depth: U32, next: U32, failed: Bool }

#[pure]
fn install(loops: seq.Seq, base: U32, count: U32, input: Emitted) -> Emitted {
    let mut s = input
    for id in 0..4096 {
        if id == seq.len(loops) { return s }
        let value = formula.value(loops, id)
        s.table = tree.set(s.table, count, as_u32(as_field(base) + as_field(id)), value.formula)
        s.depth = formula.maximum(s.depth, value.depth)
    }
    s
}

#[pure]
fn chunk(bodies: seq.Seq, plan: function_plan.Plan, codes: code_plan.Plan, input: Emitted, cap: U32, depth_cap: U32) -> Emitted {
    let mut s = input
    for turn in 0..8 {
        if s.next == seq.len(plan.order) { return s }
        let id = as_u32(noun.as_field(seq.get(plan.order, s.next)))
        let stored = seq.get(bodies, id)
        let body = body_store.read(stored, cap)
        let base = as_u32(noun.as_field(tree.get(codes.bases, seq.len(bodies), id)))
        let context = call_codegen.Context { arguments: body.arguments, bodies, slots: plan.slots,
            functions: seq.len(bodies), table: tree.shape(codes.count), capacity: cap, loop_base: base, get_slot: codes.get_slot }
        let built = control_gen.reusable(body, body_store.terminal(stored), body_store.locals(stored), context, depth_cap)
        if built.failed { s.failed = true return s }
        s.table = tree.set(s.table, codes.count, s.next, built.output.formula)
        s.depth = formula.maximum(s.depth, built.output.depth)
        s = install(built.loops, base, codes.count, s)
        s.next = syntax.inc(s.next)
    }
    s
}

#[pure]
#[requires(entry < seq.len(bodies))]
#[requires((syntax.TABLE_CAP < cap) == false)]
pub fn generate(bodies: seq.Seq, plan: function_plan.Plan, entry: U32, cap: U32, depth_cap: U32, structured: Bool) -> codegen.Compiled {
    let zero = syntax.ZERO
    let failure = codegen.Compiled { formula: noun.atom(0), error: syntax.error(7, zero, zero) }
    let stored = seq.get(bodies, entry)
    // An acyclic one-body closure contains no user calls. Preserve the existing
    // arithmetic, locals and control artifact identities, even with unused defs.
    if syntax.both(syntax.both(seq.len(plan.order) == as_u32(1), body_store.loop_count(stored) == zero), body_store.needs_get(stored) == false) {
        let body = body_store.read(stored, cap)
        let mut context = call_codegen.empty()
        context.arguments = body.arguments
        context.capacity = cap
        let built = control_gen.reusable(body, body_store.terminal(stored), body_store.locals(stored), context, depth_cap)
        return control_gen.standalone(built, body_store.locals(stored), depth_cap, structured)
    }
    let codes = code_plan.extend(bodies, plan, cap)
    if codes.failed { return failure }
    let shape = tree.shape(codes.count)
    let mut s = Emitted { table: tree.empty(shape.height), depth: zero, next: zero, failed: false }
    if codes.needs_get {
        let helper = array_gen.helper(shape, codes.get_slot)
        s.table = tree.set(s.table, codes.count, codes.get_slot, helper.formula)
        s.depth = helper.depth
    }
    for turn in 0..512 {
        s = chunk(bodies, plan, codes, s, cap, depth_cap)
        if s.failed { return failure }
        if s.next == seq.len(plan.order) {
            let frame = tree.shape(body_store.locals(stored))
            let subject = noun.pair(s.table, noun.pair(noun.atom(0), tree.empty(frame.height)))
            let table_depth = as_u32(as_field(s.depth) + as_field(shape.height))
            let subject_depth = syntax.inc(formula.maximum(table_depth, syntax.inc(frame.height)))
            let mut initial = formula.Value { formula: noun.pair(noun.atom(1), subject), depth: syntax.inc(subject_depth) }
            if structured {
                let table = formula.Value { formula: noun.pair(noun.atom(1), s.table), depth: syntax.inc(table_depth) }
                initial = entry_frame.subject(table, frame.height)
            }
            let occupied = noun.as_field(tree.get(plan.slots, seq.len(bodies), entry))
            let slot = syntax.dec(as_u32(occupied))
            let dispatch = formula.apply(flow.axis(1), flow.axis(2 * shape.capacity + as_field(slot)))
            let output = flow.compose(initial, dispatch)
            if depth_cap < as_u32(as_field(output.depth) + 9) { return failure }
            return codegen.Compiled { formula: output.formula, error: syntax.error(0, zero, zero) }
        }
    }
    failure
}

sources.std.compiler.nox.function_imports:
module std.compiler.nox.function_imports

use vm.nox.noun
use std.nox.bytes
use std.compiler.nox.syntax
use std.compiler.nox.qualified_name
use std.compiler.nox.function_exports

// The graph owns validated source/name handles. Each dependency publishes its
// final public callable IDs before this immutable direct-use view is checked.
pub struct View {
    pub sources: bytes.BytesTable, pub names: bytes.BytesTable,
    pub exports: function_exports.Bank, pub uses: Noun
}

#[pure]
pub fn empty() -> View {
    View { sources: bytes.table_empty(), names: bytes.table_empty(),
        exports: function_exports.empty(syntax.ZERO), uses: noun.atom(0) }
}

#[pure]
#[requires((syntax.SOURCE_CAP < bytes.len(source)) == false)]
pub fn lookup(source: bytes.Bytes, name: qualified_name.Name, view: View) -> function_exports.Found {
    let mut found = function_exports.Found { exists: false, target: syntax.ZERO }
    if bytes.len(name.prefix) == syntax.ZERO { return found }
    let mut rest = view.uses
    for step in 0..4096 {
        if noun.eq(rest, noun.atom(0)) { return found }
        // module_store.Use starts with the compact target module ID. The
        // complete record and source-order list remain owned by the graph.
        let target = as_u32(noun.as_field(noun.head(noun.head(rest))))
        let owner = bytes.table_get(view.names, target)
        if qualified_name.matches_owner(name.prefix, owner) {
            let candidate = function_exports.find(view.exports, target,
                bytes.table_get(view.sources, target), source, name.member)
            // A missing/private member of a later same-basename owner leaves
            // an earlier public binding visible. Repeated uses retain order.
            if candidate.exists { found = candidate }
        }
        rest = noun.tail(rest)
    }
    assert(noun.eq(rest, noun.atom(0)))
    found
}

sources.std.compiler.nox.function_order:
module std.compiler.nox.function_order

use vm.nox.noun
use vm.core.convert
use std.nox.bytes
use std.nox.seq
use std.compiler.nox.syntax
use std.compiler.nox.signatures

pub struct Ordered { pub ids: seq.Seq, pub next: U32, pub error: syntax.Error }
struct Insert { ids: seq.Seq, gap: U32, done: Bool }
struct Merge { output: seq.Seq, left: U32, right: U32, middle: U32, end: U32 }

#[pure]
fn before(source: bytes.Bytes, left: syntax.Token, right: syntax.Token) -> Bool {
    let mut a = left.start
    let mut b = right.start
    for turn in 0..65536 {
        if a == left.end { return (b == right.end) == false }
        if b == right.end { return false }
        let x = bytes.get(source, a)
        let y = bytes.get(source, b)
        if x < y { return true }
        if y < x { return false }
        a = syntax.inc(a)
        b = syntax.inc(b)
    }
    false
}

#[pure]
fn insert_chunk(source: bytes.Bytes, functions: seq.Seq, name: syntax.Token, input: Insert) -> Insert {
    let mut s = input
    for turn in 0..8 {
        if s.gap == syntax.ZERO { s.done = true return s }
        let previous = seq.get(s.ids, syntax.dec(s.gap))
        let declaration = signatures.read(seq.get(functions, as_u32(noun.as_field(previous))))
        if before(source, name, declaration.name) == false { s.done = true return s }
        s.ids = seq.set(s.ids, s.gap, previous)
        s.gap = syntax.dec(s.gap)
    }
    s
}

#[pure]
fn insert(source: bytes.Bytes, functions: seq.Seq, input: seq.Seq, id: U32, cap: U32) -> seq.Seq {
    let declaration = signatures.read(seq.get(functions, id))
    let value = noun.atom(as_field(id))
    let mut s = Insert { ids: seq.push(input, value, cap), gap: seq.len(input), done: false }
    for turn in 0..512 {
        s = insert_chunk(source, functions, declaration.name, s)
        if s.done { return seq.set(s.ids, s.gap, value) }
    }
    // At most TABLE_CAP final bindings can precede this insertion.
    seq.set(s.ids, s.gap, value)
}

#[pure]
fn merge_chunk(source: bytes.Bytes, functions: seq.Seq, values: seq.Seq, input: Merge, cap: U32) -> Merge {
    let mut s = input
    for step in 0..8 {
        if seq.len(s.output) == s.end { return s }
        let mut take_right = s.left == s.middle
        if syntax.both(s.left < s.middle, s.right < s.end) {
            let left = signatures.read(seq.get(functions, as_u32(noun.as_field(seq.get(values, s.left))))).name
            let right = signatures.read(seq.get(functions, as_u32(noun.as_field(seq.get(values, s.right))))).name
            take_right = before(source, right, left)
        }
        if take_right {
            s.output = seq.push(s.output, seq.get(values, s.right), cap)
            s.right = syntax.inc(s.right)
        } else {
            s.output = seq.push(s.output, seq.get(values, s.left), cap)
            s.left = syntax.inc(s.left)
        }
    }
    s
}

#[pure]
fn merge(source: bytes.Bytes, functions: seq.Seq, values: seq.Seq, width: U32, output: seq.Seq, cap: U32) -> seq.Seq {
    let start = seq.len(output)
    let mut middle = as_u32(as_field(start) + as_field(width))
    if seq.len(values) < middle { middle = seq.len(values) }
    let mut end = as_u32(as_field(middle) + as_field(width))
    if seq.len(values) < end { end = seq.len(values) }
    let mut s = Merge { output, left: start, right: middle, middle, end }
    for block in 0..512 {
        s = merge_chunk(source, functions, values, s, cap)
        if seq.len(s.output) == s.end { return s.output }
    }
    s.output
}

#[pure]
fn pass(source: bytes.Bytes, functions: seq.Seq, values: seq.Seq, width: U32, cap: U32) -> seq.Seq {
    let mut output = seq.empty()
    for run in 0..4096 {
        if seq.len(output) == seq.len(values) { return output }
        output = merge(source, functions, values, width, output, cap)
    }
    output
}

// Explicit roots already own final binding selection and original tie order.
// Package compilation calls this on one owner's bucket; no owner/rank metadata
// enters the member comparator. The ordinary sort entry keeps its old path.
#[pure]
#[requires((syntax.TABLE_CAP < seq.len(functions)) == false)]
#[requires((syntax.TABLE_CAP < cap) == false)]
#[requires((cap < seq.len(roots)) == false)]
pub fn sort_roots(source: bytes.Bytes, functions: seq.Seq, roots: seq.Seq, cap: U32) -> seq.Seq {
    let mut output = roots
    let mut width = as_u32(1)
    for level in 0..12 {
        if (width < seq.len(output)) == false { return output }
        output = pass(source, functions, output, width, cap)
        width = as_u32(as_field(width) * 2)
    }
    output
}

#[pure]
fn chunk(source: bytes.Bytes, functions: seq.Seq, input: Ordered, cap: U32) -> Ordered {
    let mut s = input
    for turn in 0..8 {
        if s.next == seq.len(functions) { return s }
        let declaration = signatures.read(seq.get(functions, s.next))
        if signatures.lookup(source, declaration.name, functions) == s.next {
            if seq.len(s.ids) == cap { s.error = syntax.error(7, declaration.name.start, declaration.name.end) return s }
            s.ids = insert(source, functions, s.ids, s.next, cap)
        }
        s.next = syntax.inc(s.next)
    }
    s
}

#[pure]
#[requires((syntax.TABLE_CAP < seq.len(functions)) == false)]
pub fn sort(source: bytes.Bytes, functions: seq.Seq, cap: U32) -> Ordered {
    let zero = syntax.ZERO
    let mut s = Ordered { ids: seq.empty(), next: zero, error: syntax.error(0, zero, zero) }
    for turn in 0..512 {
        s = chunk(source, functions, s, cap)
        if syntax.either(s.next == seq.len(functions), (s.error.code == zero) == false) { return s }
    }
    s.error = syntax.error(7, zero, zero)
    s
}

sources.std.compiler.nox.function_plan:
module std.compiler.nox.function_plan

use vm.nox.noun
use vm.core.convert
use std.nox.seq
use std.nox.tree
use std.nox.bytes
use std.compiler.nox.signatures
use std.compiler.nox.syntax
use std.compiler.nox.function_order
use std.compiler.nox.call_graph

pub struct Plan { pub order: seq.Seq, pub slots: Noun, pub next: U32, pub error: syntax.Error, pub error_function: U32 }

#[pure]
fn chunk(ordered: seq.Seq, reachable: Noun, functions: U32, input: Plan, cap: U32) -> Plan {
    let mut s = input
    for turn in 0..8 {
        if s.next == seq.len(ordered) { return s }
        let value = seq.get(ordered, s.next)
        let id = as_u32(noun.as_field(value))
        if noun.as_field(tree.get(reachable, functions, id)) == 2 {
            if seq.len(s.order) == cap { s.error = syntax.error(7, syntax.ZERO, syntax.ZERO) return s }
            // Zero is absent. Occupied table indices are stored plus one.
            s.slots = tree.set(s.slots, functions, id, noun.atom(as_field(seq.len(s.order)) + 1))
            s.order = seq.push(s.order, value, cap)
        }
        s.next = syntax.inc(s.next)
    }
    s
}

#[pure]
#[requires(entry < seq.len(functions))]
pub fn plan(source: bytes.Bytes, functions: seq.Seq, bodies: seq.Seq, entry: U32, cap: U32) -> Plan {
    ordered(functions, bodies, function_order.sort(source, functions, cap), entry, cap)
}

#[pure]
#[requires(entry < seq.len(functions))]
pub fn ordered(functions: seq.Seq, bodies: seq.Seq, sorted: function_order.Ordered, entry: U32, cap: U32) -> Plan {
    let zero = syntax.ZERO
    let mut s = Plan { order: seq.empty(), slots: tree.empty(tree.shape(seq.len(functions)).height),
        next: zero, error: syntax.error(0, zero, zero), error_function: signatures.NONE }
    if cap == zero { s.error = syntax.error(7, zero, zero) return s }
    s.error = sorted.error
    if (s.error.code == zero) == false { return s }
    let checked = call_graph.walk(functions, bodies, sorted.ids, cap)
    s.error = checked.error
    s.error_function = checked.error_function
    if (s.error.code == zero) == false { return s }
    let roots = seq.push(seq.empty(), noun.atom(as_field(entry)), cap)
    let reachable = call_graph.walk(functions, bodies, roots, cap)
    s.error = reachable.error
    s.error_function = reachable.error_function
    if (s.error.code == zero) == false { return s }
    for turn in 0..512 {
        s = chunk(sorted.ids, reachable.colors, seq.len(functions), s, cap)
        if syntax.either(s.next == seq.len(sorted.ids), (s.error.code == zero) == false) { return s }
    }
    s.error = syntax.error(7, zero, zero)
    s
}

sources.std.compiler.nox.group_parse:
module std.compiler.nox.group_parse

use vm.nox.noun
use vm.core.convert
use std.nox.bytes
use std.nox.seq
use std.compiler.nox.syntax
use std.compiler.nox.ast
use std.compiler.nox.types
use std.compiler.nox.lexer
use std.compiler.nox.signatures
use std.compiler.nox.expression_state

struct Frame { start: U32, vals: U32, count: U32, head: U32 }

#[pure]
fn pack(f: Frame) -> Noun {
    let position = noun.pair(noun.atom(as_field(f.start)), noun.atom(as_field(f.vals)))
    let values = noun.pair(noun.atom(as_field(f.count)), noun.atom(as_field(f.head)))
    noun.pair(position, values)
}

#[pure]
fn read(record: Noun) -> Frame {
    let position = noun.head(record)
    let values = noun.tail(record)
    Frame { start: as_u32(noun.as_field(noun.head(position))), vals: as_u32(noun.as_field(noun.tail(position))),
        count: as_u32(noun.as_field(noun.head(values))), head: as_u32(noun.as_field(noun.tail(values))) }
}

#[pure]
pub fn finish(source: bytes.Bytes, input: expression_state.State, closing: Bool, tuple: Bool) -> expression_state.State {
    let mut s = input
    let mut f = Frame { start: syntax.ZERO, vals: syntax.ZERO, count: syntax.ZERO, head: signatures.NONE }
    if tuple { f = read(noun.head(s.frames)) }
    else {
        let position = noun.head(s.frames)
        f.start = as_u32(noun.as_field(noun.head(position)))
        f.vals = as_u32(noun.as_field(noun.tail(position)))
        s.operators = seq.set(s.operators, syntax.dec(s.ops), noun.atom(as_field(expression_state.TUPLE_MARKER)))
    }
    if s.operand {
        // Only a tuple with at least two completed items may trail a comma.
        if syntax.either(closing == false, f.count < as_u32(2)) { s.error = ast.failed(s.token, 2) return s }
    } else {
        if (s.vals == syntax.inc(f.vals)) == false { s.error = ast.failed(s.token, 2) return s }
        if syntax.either(f.count == types.MAX_ARITY, seq.len(s.arguments) == s.node_cap) {
            s.error = ast.failed(s.token, 7) return s
        }
        let value = noun.as_field(seq.get(s.values, f.vals))
        let link = seq.len(s.arguments)
        s.arguments = seq.push(s.arguments, noun.pair(noun.atom(value), noun.atom(as_field(f.head))), s.node_cap)
        f.head = link
        f.count = syntax.inc(f.count)
        s.vals = f.vals
    }
    if closing {
        // Links are reversed. Gather their types once, in source order.
        let mut cursor = f.head
        let mut ordered = noun.atom(0)
        for i in 0..16 {
            if i < f.count {
                let link = seq.get(s.arguments, cursor)
                let child = seq.get(s.nodes, as_u32(noun.as_field(noun.head(link))))
                ordered = noun.pair(ast.ty(child), ordered)
                cursor = as_u32(noun.as_field(noun.tail(link)))
            }
        }
        let mut children = seq.empty()
        for i in 0..16 {
            if i < f.count {
                children = seq.push(children, noun.head(ordered), s.node_cap)
                ordered = noun.tail(ordered)
            }
        }
        let built = types.tuple(children, s.node_cap, s.capacity)
        if built.failed { s.error = ast.failed(s.token, 7) return s }
        if syntax.either(seq.len(s.nodes) == s.node_cap, s.vals == s.capacity) { s.error = ast.failed(s.token, 7) return s }
        let id = seq.len(s.nodes)
        s.nodes = seq.push(s.nodes, ast.typed(ast.TUPLE_VALUE, as_field(f.count), as_field(f.head), built.ty, f.start, s.token.end), s.node_cap)
        s.values = ast.store(s.values, s.vals, noun.atom(as_field(id)), s.capacity)
        s.vals = syntax.inc(s.vals)
        s.ops = syntax.dec(s.ops)
        s.frames = noun.tail(s.frames)
        s.operand = false
    } else {
        s.frames = noun.pair(pack(f), noun.tail(s.frames))
        s.operand = true
    }
    s.token = lexer.next(source, s.token.end)
    s
}

sources.std.compiler.nox.halting:
module std.compiler.nox.halting

use vm.nox.noun
use vm.core.convert
use std.nox.seq
use std.compiler.nox.ast
use std.compiler.nox.builtins

// Checked calls own their arity and argument links. Callable resolution has
// already distinguished an ordinary function named assert from the builtin.
#[pure]
pub fn is_false_assert(node: Noun, nodes: seq.Seq, arguments: seq.Seq) -> Bool {
    if (ast.kind(node) == ast.BUILTIN) == false { return false }
    if (ast.left(node) == as_field(builtins.ASSERT)) == false { return false }
    let link = seq.get(arguments, as_u32(ast.right(node)))
    let value = seq.get(nodes, as_u32(noun.as_field(noun.head(link))))
    if (ast.kind(value) == ast.BOOLEAN) == false { return false }
    ast.left(value) == 1
}

sources.std.compiler.nox.header_state:
module std.compiler.nox.header_state

use std.compiler.nox.constants
use vm.nox.noun
use std.nox.seq
use std.compiler.nox.type_registry
use std.compiler.nox.syntax
use std.compiler.nox.signatures
use std.compiler.nox.types
use std.compiler.nox.intrinsic_bindings
use std.compiler.nox.intrinsic_abi

pub struct Metadata {
    pub pure: Bool, pub exported: Bool, pub intrinsic: Bool,
    pub identity: U32, pub start: U32, pub end: U32
}

#[pure]
pub fn metadata() -> Metadata {
    Metadata { pure: false, exported: false, intrinsic: false,
        identity: intrinsic_abi.NONE, start: syntax.ZERO, end: syntax.ZERO }
}

pub struct State {
    // The header scan advances tokens much more often than declarations.
    pub token: syntax.Token, pub error: syntax.Error,
    pub types: type_registry.Scope, pub functions: seq.Seq, pub params: seq.Seq, pub entry: U32,
    pub structured: Bool, pub current: signatures.Function,
    pub phase: Field, pub nesting: U32, pub done: Bool, pub constants: constants.Scope,
    pub metadata: Metadata, pub pure_functions: seq.Seq,
    // Sparse declaration IDs are absolute indices into the shared function table.
    pub intrinsics: intrinsic_bindings.Bank, pub public_functions: seq.Seq
}

#[pure]
#[ensures(seq.len(result.functions) == syntax.ZERO)]
#[ensures(seq.len(result.params) == syntax.ZERO)]
#[ensures(seq.len(result.public_functions) == syntax.ZERO)]
pub fn initial(token: syntax.Token) -> State {
    let zero = syntax.ZERO
    State { types: type_registry.empty(), functions: seq.empty(), params: seq.empty(), entry: signatures.NONE, token,
        current: signatures.Function { name: token, params: zero, count: zero, returns: noun.atom(types.UNIT), open: zero, close: zero },
        structured: false, phase: 0, nesting: zero, error: syntax.error(0, zero, zero), done: false, constants: constants.empty(),
        metadata: metadata(), pure_functions: seq.empty(), intrinsics: intrinsic_bindings.empty(), public_functions: seq.empty() }
}

sources.std.compiler.nox.headers:
module std.compiler.nox.headers

use std.compiler.nox.const_parse
use std.compiler.nox.constants
use std.compiler.nox.constant_imports
use std.compiler.nox.attributes
use vm.core.convert
use vm.core.field
use vm.nox.noun
use std.nox.bytes
use std.nox.seq
use std.compiler.nox.syntax
use std.compiler.nox.ast
use std.compiler.nox.lexer
use std.compiler.nox.symbols
use std.compiler.nox.signatures
use std.compiler.nox.header_state
use std.compiler.nox.types
use std.compiler.nox.struct_parse
use std.compiler.nox.type_parse
use std.compiler.nox.type_imports
use std.compiler.nox.intrinsic_abi
use std.compiler.nox.intrinsic_bindings

#[pure]
fn expected(token: syntax.Token) -> syntax.Error {
    if token.kind == as_u32(14) { return syntax.error(1, token.start, token.end) }
    if token.kind == as_u32(46) { return syntax.error(6, token.start, token.end) }
    if token.kind == as_u32(13) { return syntax.error(6, token.start, token.end) }
    syntax.error(2, token.start, token.end)
}

#[pure]
pub fn scalar(token: syntax.Token) -> Field { type_parse.scalar(token) }

// One completed signature occupies one global declaration ID. Cold metadata
// resets here so adjacent unannotated declarations cannot inherit an identity.
#[pure]
fn complete(input: header_state.State, cap: U32) -> header_state.State {
    let mut s = input
    let id = seq.len(s.functions)
    if s.current.name.value == 1835100526 { s.entry = id }
    if s.metadata.pure { s.pure_functions = seq.push(s.pure_functions, noun.atom(as_field(id)), cap) }
    if s.metadata.exported { s.public_functions = seq.push(s.public_functions, noun.atom(as_field(id)), cap) }
    if s.metadata.intrinsic {
        s.intrinsics = intrinsic_bindings.append(s.intrinsics, id, s.metadata.identity, cap)
    }
    s.functions = seq.push(s.functions, signatures.pack(s.current), cap)
    s.metadata = header_state.metadata()
    s.phase = 0
    s
}

#[pure]
fn open(source: bytes.Bytes, input: header_state.State, cap: U32) -> header_state.State {
    let mut s = input
    // Called at the closing parameter parenthesis, with an optional annotation.
    s.token = lexer.next(source, s.token.end)
    if s.token.kind == as_u32(9) {
        s.token = lexer.next(source, s.token.end)
        let parsed = type_parse.parse(source, s.token, s.types, cap)
        s.error = parsed.error
        if (s.error.code == syntax.ZERO) == false { return s }
        s.current.returns = parsed.ty
        s.token = parsed.token
    }
    if s.metadata.intrinsic {
        if s.token.kind == as_u32(7) {
            s.error = syntax.error(6, s.metadata.start, s.metadata.end) return s
        }
        if intrinsic_abi.valid(s.metadata.identity, s.current, s.params) == false {
            s.error = syntax.error(5, s.metadata.start, s.metadata.end) return s
        }
        s.current.close = s.token.start
        return complete(s, cap)
    }
    if (s.token.kind == as_u32(7)) == false { s.error = expected(s.token) return s }
    s.current.open = s.token.end
    s.phase = 2
    s.nesting = as_u32(1)
    s.token = lexer.next(source, s.token.end)
    s
}

#[pure]
fn parameter(source: bytes.Bytes, input: header_state.State, cap: U32) -> header_state.State {
    let mut s = input
    if s.token.kind == as_u32(6) { return open(source, s, cap) }
    let name = s.token
    if (name.kind == as_u32(1)) == false { s.error = expected(name) return s }
    s.token = lexer.next(source, name.end)
    if (s.token.kind == as_u32(17)) == false { s.error = expected(s.token) return s }
    s.token = lexer.next(source, s.token.end)
    let parsed = type_parse.parse(source, s.token, s.types, cap)
    s.error = parsed.error
    if (s.error.code == syntax.ZERO) == false { return s }
    if seq.len(s.params) == cap { s.error = syntax.error(7, name.start, name.end) return s }
    s.params = seq.push(s.params, symbols.binding(name, false, parsed.ty), cap)
    s.current.count = syntax.inc(s.current.count)
    s.token = parsed.token
    if s.token.kind == as_u32(6) { return open(source, s, cap) }
    if (s.token.kind == as_u32(26)) == false { s.error = expected(s.token) return s }
    s.token = lexer.next(source, s.token.end)
    s
}

#[pure]
fn step(source: bytes.Bytes, input: header_state.State, cap: U32, type_limit: U32) -> header_state.State {
    let mut s = input
    if s.phase == 1 { return parameter(source, s, cap) }
    if s.phase == 2 {
        if s.token.kind == syntax.ZERO { s.error = expected(s.token) return s }
        if s.token.kind == as_u32(14) { s.error = ast.failed(s.token, 1) return s }
        if s.token.kind == as_u32(7) { s.nesting = syntax.inc(s.nesting) }
        if s.token.kind == as_u32(8) {
            s.nesting = syntax.dec(s.nesting)
            if s.nesting == syntax.ZERO {
                s.current.close = s.token.end
                s = complete(s, cap)
            }
        }
        s.token = lexer.next(source, s.token.end)
        return s
    }
    if s.token.kind == syntax.ZERO { s.done = true return s }
    let annotated = s.token.kind == attributes.HASH
    if annotated {
        let parsed = attributes.parse(source, s.token)
        s.token = parsed.token
        s.error = parsed.error
        if (s.error.code == syntax.ZERO) == false { return s }
        s.metadata = header_state.Metadata { pure: parsed.pure, exported: false,
            intrinsic: parsed.intrinsic, identity: parsed.identity,
            start: parsed.intrinsic_start, end: parsed.intrinsic_end }
    }
    let mut public = false
    if s.token.kind == as_u32(40) { public = true s.token = lexer.next(source, s.token.end) }
    if annotated {
        if (s.token.kind == as_u32(11)) == false {
            if s.token.kind == as_u32(14) { s.error = syntax.error(1, s.token.start, s.token.end) }
            else { s.error = syntax.error(2, s.token.start, s.token.end) }
            return s
        }
    }
    if s.token.kind == as_u32(45) {
        s.constants.owner = s.types.owner
        let parsed = const_parse.parse(source, s.token, s.constants, public, cap)
        s.constants = parsed.scope
        s.token = parsed.token
        s.error = parsed.error
        return s
    }
    if s.token.kind == as_u32(39) {
        if seq.len(s.types.records) == type_limit { s.error = ast.failed(lexer.next(source, s.token.end), 7) return s }
        let parsed = struct_parse.parse(source, s.token, s.types, public, cap)
        s.types = parsed.scope
        s.token = parsed.token
        s.error = parsed.error
        return s
    }
    if (s.token.kind == as_u32(11)) == false { s.error = expected(s.token) return s }
    if s.metadata.intrinsic {
        if intrinsic_abi.allowed_owner(s.types.owner) == false {
            s.error = syntax.error(5, s.metadata.start, s.metadata.end) return s
        }
        if s.metadata.identity == intrinsic_abi.NONE {
            s.error = syntax.error(6, s.metadata.start, s.metadata.end) return s
        }
    }
    if seq.len(s.functions) == cap { s.error = syntax.error(7, s.token.start, s.token.end) return s }
    let name = lexer.next(source, s.token.end)
    if (name.kind == as_u32(1)) == false { s.error = expected(name) return s }
    s.token = lexer.next(source, name.end)
    if syntax.both(s.metadata.intrinsic, s.token.kind == as_u32(29)) {
        s.error = syntax.error(6, s.metadata.start, s.metadata.end) return s
    }
    if (s.token.kind == as_u32(5)) == false { s.error = expected(s.token) return s }
    s.current = signatures.Function { name, params: seq.len(s.params), count: syntax.ZERO, returns: noun.atom(types.UNIT), open: syntax.ZERO, close: syntax.ZERO }
    s.metadata.exported = public
    s.phase = 1
    s.token = lexer.next(source, s.token.end)
    s
}

#[pure]
fn chunk(source: bytes.Bytes, input: header_state.State, cap: U32, type_limit: U32) -> header_state.State {
    let mut s = input
    for turn in 0..16 {
        s = step(source, s, cap, type_limit)
        if syntax.either(s.done, (s.error.code == syntax.ZERO) == false) { return s }
    }
    s
}

// Braces are tokens; braces inside comments never delimit bodies.
#[pure]
#[requires((syntax.SOURCE_CAP < bytes.len(source)) == false)]
#[requires((syntax.TABLE_CAP < cap) == false)]
pub fn parse(source: bytes.Bytes, start: U32, owner: bytes.Bytes, cap: U32) -> header_state.State {
    parse_imports(source, start, owner, constant_imports.empty(), cap)
}

#[pure]
#[requires((syntax.SOURCE_CAP < bytes.len(source)) == false)]
#[requires((syntax.TABLE_CAP < cap) == false)]
pub fn parse_imports(source: bytes.Bytes, start: U32, owner: bytes.Bytes, imports: constant_imports.View, cap: U32) -> header_state.State {
    validate_entry(scan_module(source, start, owner, imports, type_imports.empty(), syntax.ZERO, seq.empty(), seq.empty(), cap))
}

// Shared tables retain prior owners' declarations. This scan records only the
// current owner's entry/purity/visibility and resolves all of its constants.
// Dependency Unit returns use the ordinary omitted return annotation.
#[pure]
#[requires((syntax.SOURCE_CAP < bytes.len(source)) == false)]
#[requires((syntax.TABLE_CAP < cap) == false)]
#[requires((cap < seq.len(functions)) == false)]
#[requires((cap < seq.len(params)) == false)]
#[requires((cap < type_start) == false)]
#[ensures((cap < seq.len(result.functions)) == false)]
#[ensures((cap < seq.len(result.params)) == false)]
#[ensures((cap < seq.len(result.public_functions)) == false)]
pub fn scan_module(source: bytes.Bytes, start: U32, owner: bytes.Bytes, imports: constant_imports.View,
    imported_types: type_imports.View, type_start: U32, functions: seq.Seq, params: seq.Seq, cap: U32) -> header_state.State {
    scan_with_intrinsics(source, start, owner, imports, imported_types, type_start,
        functions, params, cap, intrinsic_bindings.empty())
}

#[pure]
#[requires((syntax.SOURCE_CAP < bytes.len(source)) == false)]
#[requires((syntax.TABLE_CAP < cap) == false)]
#[requires((cap < seq.len(functions)) == false)]
#[requires((cap < seq.len(params)) == false)]
#[requires((cap < type_start) == false)]
pub fn scan_with_intrinsics(source: bytes.Bytes, start: U32, owner: bytes.Bytes, imports: constant_imports.View,
    imported_types: type_imports.View, type_start: U32, functions: seq.Seq, params: seq.Seq, cap: U32,
    intrinsics: intrinsic_bindings.Bank) -> header_state.State {
    let mut s = header_state.initial(lexer.next(source, start))
    s.intrinsics = intrinsics
    s.functions = functions
    s.params = params
    s.types.owner = owner
    s.types.imports = imported_types
    assert((cap < type_start) == false)
    let type_limit = as_u32(field.sub(as_field(cap), as_field(type_start)))
    s.constants.imports = imports
    for turn in 0..512 {
        s = chunk(source, s, cap, type_limit)
        if (s.error.code == syntax.ZERO) == false { return s }
        if s.done {
            let resolved = constants.resolve(source, s.constants)
            s.constants = resolved.scope
            s.error = resolved.error
            return s
        }
    }
    s.error = syntax.error(7, s.token.start, s.token.end)
    s
}

// The entry check runs after a successful module scan, never for dependencies.
#[pure]
#[requires(syntax.either(input.entry == signatures.NONE, input.entry < seq.len(input.functions)))]
#[ensures(seq.len(result.functions) == seq.len(input.functions))]
#[ensures(seq.len(result.params) == seq.len(input.params))]
pub fn validate_entry(input: header_state.State) -> header_state.State {
    let mut s = input
    if (s.error.code == syntax.ZERO) == false { return s }
    if s.entry == signatures.NONE { s.error = syntax.error(3, s.token.start, s.token.end) return s }
    let entry = signatures.read(seq.get(s.functions, s.entry))
    if (intrinsic_bindings.kind(s.intrinsics, s.entry) == intrinsic_abi.NONE) == false {
        s.error = syntax.error(6, entry.name.start, entry.name.end) return s
    }
    if syntax.both(entry.count == syntax.ZERO, noun.eq(entry.returns, noun.atom(types.FIELD))) { return s }
    if syntax.both(entry.count == as_u32(1), noun.eq(entry.returns, noun.atom(types.NOUN))) {
        let parameter = seq.get(s.params, entry.params)
        if noun.eq(noun.tail(noun.tail(parameter)), noun.atom(types.NOUN)) { s.structured = true return s }
    }
    s.error = syntax.error(3, entry.name.start, entry.name.end)
    s
}

// The header has already passed the ordinary scalar/structured entry check.
// Compiler-profile output must preserve the entire JOB1 subject and RES1 value.
#[pure]
#[requires(syntax.either(profile == 0, profile == 1))]
pub fn require_profile(input: header_state.State, profile: Field) -> header_state.State {
    let mut s = input
    if (s.error.code == syntax.ZERO) == false { return s }
    if syntax.both(profile == 1, s.structured == false) {
        let entry = signatures.read(seq.get(s.functions, s.entry))
        s.error = syntax.error(3, entry.name.start, entry.name.end)
    }
    s
}

sources.std.compiler.nox.index_parse:
module std.compiler.nox.index_parse

use vm.nox.noun
use vm.core.convert
use std.nox.bytes
use std.nox.seq
use std.compiler.nox.syntax
use std.compiler.nox.ast
use std.compiler.nox.types
use std.compiler.nox.lexer
use std.compiler.nox.expression_state
use std.compiler.nox.array_size

// Index and call frames share a delimiter-owned stack. An index frame keeps
// [base-node saved-value-count]; the '[' marker owns its matching ']'.
#[pure]
pub fn enter(source: bytes.Bytes, input: expression_state.State) -> expression_state.State {
    let mut s = input
    if s.ops == s.capacity { s.error = ast.failed(s.token, 7) return s }
    s.vals = syntax.dec(s.vals)
    let base = seq.get(s.values, s.vals)
    let node = seq.get(s.nodes, as_u32(noun.as_field(base)))
    if noun.eq(ast.ty(node), noun.atom(types.DIGEST)) == false {
        if types.array_info(ast.ty(node)).valid == false { s.error = ast.issue(5, node) return s }
    }
    s.frames = noun.pair(noun.pair(base, noun.atom(as_field(s.vals))), s.frames)
    s.operators = ast.store(s.operators, s.ops, noun.atom(36), s.capacity)
    s.ops = syntax.inc(s.ops)
    s.token = lexer.next(source, s.token.end)
    s.operand = true
    s
}

#[pure]
pub fn finish(source: bytes.Bytes, input: expression_state.State) -> expression_state.State {
    let mut s = input
    let frame = noun.head(s.frames)
    let base = noun.as_field(noun.head(frame))
    let saved = as_u32(noun.as_field(noun.tail(frame)))
    if s.vals == syntax.inc(saved) {
        let index = noun.as_field(seq.get(s.values, saved))
        let node = seq.get(s.nodes, as_u32(index))
        let ty = ast.ty(node)
        if syntax.either(noun.eq(ty, noun.atom(types.FIELD)), noun.eq(ty, noun.atom(types.UINT32))) == false {
            s.error = ast.issue(5, node) return s
        }
        if seq.len(s.nodes) == s.node_cap { s.error = ast.failed(s.token, 7) return s }
        let id = seq.len(s.nodes)
        let parent = seq.get(s.nodes, as_u32(base))
        let start = ast.start(parent)
        let mut kind = ast.DIGEST_INDEX
        if noun.eq(ast.ty(parent), noun.atom(types.DIGEST)) == false {
            kind = ast.ARRAY_INDEX
            if ast.kind(node) == ast.LITERAL {
                let length = types.array_info(ast.ty(parent)).length
                let literal = array_size.decimal(source, ast.start(node), ast.end(node), length)
                if syntax.either(literal.exceeded, (literal.value < length) == false) {
                    s.error = syntax.error(5, start, s.token.end) return s
                }
            }
            s.needs_get = true
        }
        s.nodes = seq.push(s.nodes, ast.typed(kind, base, index, noun.atom(types.FIELD), start, s.token.end), s.node_cap)
        s.values = seq.set(s.values, saved, noun.atom(as_field(id)))
        s.ops = syntax.dec(s.ops)
        s.frames = noun.tail(s.frames)
        s.token = lexer.next(source, s.token.end)
        s.operand = false
        return s
    }
    s.error = ast.failed(s.token, 2)
    s
}

sources.std.compiler.nox.intrinsic_abi:
module std.compiler.nox.intrinsic_abi

use vm.nox.noun
use vm.core.convert
use vm.core.field
use std.nox.bytes
use std.nox.seq
use std.compiler.nox.syntax
use std.compiler.nox.types
use std.compiler.nox.signatures
use std.compiler.nox.builtins

// IDs 1..12 remain the existing guest lowering ABI.
pub const NONE: U32 = 0
pub const TO_U32: U32 = 1
pub const TO_FIELD: U32 = 2
pub const SUBTRACT: U32 = 3
pub const NOUN_ATOM: U32 = 4
pub const NOUN_PAIR: U32 = 5
pub const NOUN_HEAD: U32 = 6
pub const NOUN_TAIL: U32 = 7
pub const NOUN_FIELD: U32 = 8
pub const NOUN_EQ: U32 = 9
pub const NOUN_IDENTITY: U32 = 10
pub const ASSERT: U32 = 11
pub const ASSERT_EQ: U32 = 12
pub const FIELD_ADD: U32 = 13
pub const FIELD_MUL: U32 = 14
pub const NEG: U32 = 15
pub const INV: U32 = 16
pub const SPLIT: U32 = 17
pub const COUNT: U32 = 18

// Known declarations and reachable lowering are separate decisions. A known
// unsupported operation keeps its ABI identity for an unsupported diagnostic.
#[pure]
pub fn lowerable(kind: U32) -> Bool {
    syntax.both((NONE < kind), (kind < builtins.COUNT))
}

#[pure]
#[requires((syntax.SOURCE_CAP < bytes.len(source)) == false)]
#[requires((bytes.len(source) < token.end) == false)]
#[requires((token.end < token.start) == false)]
#[ensures(result < COUNT)]
pub fn lookup(source: bytes.Bytes, token: syntax.Token) -> U32 {
    let length = as_u32(field.sub(as_field(token.end), as_field(token.start)))
    if syntax.both(length == as_u32(3), token.value == 7234919) { return NEG }
    if syntax.both(length == as_u32(3), token.value == 6909558) { return INV }
    if syntax.both(length == as_u32(5), token.value == 495807392116) { return SPLIT }
    if length == as_u32(9) {
        if syntax.spells(source, token, [102,105,101,108,100,95,97,100,100]) { return FIELD_ADD }
        if syntax.spells(source, token, [102,105,101,108,100,95,109,117,108]) { return FIELD_MUL }
    }
    builtins.lookup(source, token)
}

#[pure]
#[ensures(result < as_u32(3))]
pub fn arity(kind: U32) -> U32 {
    if syntax.either(kind == NONE, (kind < COUNT) == false) { return syntax.ZERO }
    if kind < builtins.COUNT { return builtins.arity(kind) }
    if syntax.either(kind == FIELD_ADD, kind == FIELD_MUL) { return as_u32(2) }
    as_u32(1)
}

#[pure]
pub fn parameter(kind: U32, index: U32) -> Noun {
    if (index < arity(kind)) == false { return noun.atom(types.INVALID) }
    if kind < builtins.COUNT { return builtins.parameter(kind) }
    noun.atom(types.FIELD)
}

#[pure]
pub fn returns(kind: U32) -> Noun {
    if syntax.either(kind == NONE, (kind < COUNT) == false) { return noun.atom(types.INVALID) }
    if kind < builtins.COUNT { return builtins.returns(kind) }
    if kind == SPLIT {
        let mut children = seq.push(seq.empty(), noun.atom(types.UINT32), as_u32(2))
        children = seq.push(children, noun.atom(types.UINT32), as_u32(2))
        return types.tuple(children, as_u32(3), as_u32(1)).ty
    }
    noun.atom(types.FIELD)
}

// Function/parameter records are compiler-owned; only their ordered types
// participate in this check. Names, body spans and parameter flags do not.
#[pure]
#[requires((syntax.TABLE_CAP < seq.len(params)) == false)]
pub fn valid(kind: U32, f: signatures.Function, params: seq.Seq) -> Bool {
    if syntax.either(kind == NONE, (kind < COUNT) == false) { return false }
    if (f.count == arity(kind)) == false { return false }
    if seq.len(params) < f.params { return false }
    let remaining = as_u32(field.sub(as_field(seq.len(params)), as_field(f.params)))
    if remaining < f.count { return false }
    if noun.eq(f.returns, returns(kind)) == false { return false }
    for i in 0..2 {
        if i < f.count {
            let binding = seq.get(params, as_u32(as_field(f.params) + as_field(i)))
            if noun.eq(noun.tail(noun.tail(binding)), parameter(kind, i)) == false { return false }
        }
    }
    true
}

#[pure]
#[requires((syntax.SOURCE_CAP < bytes.len(owner)) == false)]
pub fn allowed_owner(owner: bytes.Bytes) -> Bool {
    let length = bytes.len(owner)
    let mut suffix = syntax.ZERO
    // The low three prior bytes plus one byte fit U32 exactly. Testing the
    // previous four-byte window before shifting recognizes the complete .ext.
    // segment with one source read per position and no modular packing alias.
    for i in 0..65536 {
        if i == length { return false }
        let byte = bytes.get(owner, i)
        if syntax.both(suffix == as_u32(778401908), byte == as_u32(46)) { return true }
        suffix = as_u32(as_field(suffix & as_u32(16777215)) * 256 + as_field(byte))
        if i == as_u32(2) {
            if syntax.either(suffix == as_u32(7761198), suffix == as_u32(7303982)) { return true }
        }
        if i == as_u32(3) {
            if syntax.either(suffix == as_u32(1937007662), suffix == as_u32(1702392878)) { return true }
        }
    }
    false
}

sources.std.compiler.nox.intrinsic_bindings:
module std.compiler.nox.intrinsic_bindings

use vm.nox.noun
use vm.core.convert
use std.nox.tree
use std.compiler.nox.syntax
use std.compiler.nox.intrinsic_abi

// A persistent index over the bounded global declaration space. Empty banks
// allocate no tree; the first intrinsic creates shared zero subtrees. IDs stay
// sparse and monotonically appended, while lookup takes one bounded tree walk.
pub struct Bank { root: Noun, count: U32, last: U32, unsupported: Bool }

#[pure]
pub fn empty() -> Bank {
    Bank { root: noun.atom(0), count: syntax.ZERO, last: syntax.ZERO, unsupported: false }
}

#[pure]
#[requires(target < syntax.TABLE_CAP)]
#[requires(syntax.ZERO < kind)]
#[requires(kind < intrinsic_abi.COUNT)]
#[requires((syntax.TABLE_CAP < cap) == false)]
pub fn append(bank: Bank, target: U32, kind: U32, cap: U32) -> Bank {
    assert(target < syntax.TABLE_CAP)
    assert(syntax.ZERO < kind)
    assert(kind < intrinsic_abi.COUNT)
    assert((syntax.TABLE_CAP < cap) == false)
    assert(bank.count < cap)
    let mut root = bank.root
    if bank.count == syntax.ZERO { root = tree.empty(tree.shape(syntax.TABLE_CAP).height) }
    else { assert(bank.last < target) }
    root = tree.set(root, syntax.TABLE_CAP, target, noun.atom(as_field(kind)))
    Bank { root, count: syntax.inc(bank.count), last: target,
        unsupported: syntax.either(bank.unsupported, intrinsic_abi.lowerable(kind) == false) }
}

// Missing IDs are zero, including a later ordinary replacement of an intrinsic.
#[pure]
#[requires(target < syntax.TABLE_CAP)]
#[ensures(result < intrinsic_abi.COUNT)]
pub fn kind(bank: Bank, target: U32) -> U32 {
    if bank.count == syntax.ZERO { return intrinsic_abi.NONE }
    as_u32(noun.as_field(tree.get(bank.root, syntax.TABLE_CAP, target)))
}

#[pure]
pub fn needs_lowering(bank: Bank) -> Bool { bank.unsupported }

sources.std.compiler.nox.intrinsic_plan:
module std.compiler.nox.intrinsic_plan

use vm.nox.noun
use vm.core.convert
use std.nox.seq
use std.compiler.nox.syntax
use std.compiler.nox.ast
use std.compiler.nox.body_store
use std.compiler.nox.function_plan
use std.compiler.nox.intrinsic_abi
use std.compiler.nox.intrinsic_bindings

#[pure]
fn operation_error(nodes: seq.Seq) -> syntax.Error {
    for index in 0..4096 {
        if index == seq.len(nodes) { return syntax.error(0, syntax.ZERO, syntax.ZERO) }
        let node = seq.get(nodes, index)
        if ast.kind(node) == ast.BUILTIN {
            if intrinsic_abi.lowerable(as_u32(ast.left(node))) == false { return ast.issue(6, node) }
        }
    }
    syntax.error(0, syntax.ZERO, syntax.ZERO)
}

// Checked but unused declarations retain known ABI identities. Only expressions
// in reachable ordinary functions must have executable lowering at this point.
#[pure]
#[requires((syntax.TABLE_CAP < cap) == false)]
pub fn check(input: function_plan.Plan, bodies: seq.Seq, bank: intrinsic_bindings.Bank, cap: U32) -> function_plan.Plan {
    let mut s = input
    if (s.error.code == syntax.ZERO) == false { return s }
    if intrinsic_bindings.needs_lowering(bank) == false { return s }
    for position in 0..4096 {
        if position == seq.len(s.order) { return s }
        let id = as_u32(noun.as_field(seq.get(s.order, position)))
        let nodes = body_store.expression_nodes(seq.get(bodies, id), cap)
        s.error = operation_error(nodes)
        if (s.error.code == syntax.ZERO) == false {
            s.error_function = id
            return s
        }
    }
    s
}

sources.std.compiler.nox.job:
module std.compiler.nox.job

use vm.nox.noun
use vm.core.field
use std.nox.bytes
use std.nox.seq
use std.nox.tree
use std.compiler.nox.syntax

const INV2: Field = 9223372034707292161
const INV4: Field = 13835058052060938241

// All handles have already crossed their structural admission boundary.
// The remaining allowance follows every later lookup/open, never each record.
pub struct Package {
    pub modules: seq.Seq, pub read_cost: U32, pub remaining: U32,
    pub source_limit: U32, pub options: Noun
}
// Joy validates the complete JOB1 and compiler identity before this guest runs.
// This view validates the records/collections it consumes; it does no I/O.
pub struct View {
    pub source: bytes.Bytes, pub name: bytes.Bytes, pub index: U32,
    pub sequence_limit: U32, pub depth_limit: U32, pub error: syntax.Error,
    pub package: Package, pub profile: Field
}

pub struct Found { pub exists: Bool, pub index: U32, pub remaining: U32 }
pub struct Source { pub content: bytes.Bytes, pub remaining: U32, pub error: syntax.Error }

#[pure]
#[requires((remaining < cost) == false)]
fn charge(remaining: U32, cost: U32) -> U32 {
    assert((remaining < cost) == false)
    as_u32(field.sub(as_field(remaining), as_field(cost)))
}

// Exactly index tails and one head. The caller charges these projections.
#[pure]
#[requires(index < as_u32(11))]
fn slot(body: Noun, index: U32) -> Noun {
    let mut cursor = body
    for i in 0..11 {
        if i == index { return noun.head(cursor) }
        cursor = noun.tail(cursor)
    }
    assert_eq(0, 1)
    noun.atom(0)
}

// Tag head + atom + body tail, arity tails, and terminator atom = arity+4.
#[pure]
fn record(value: Noun, tag: Field, arity: U32, remaining: U32) -> (Noun, U32) {
    let left = charge(remaining, as_u32(as_field(arity) + 4))
    assert_eq(noun.as_field(noun.head(value)), tag)
    let body = noun.tail(value)
    let mut cursor = body
    for i in 0..12 {
        if i == arity {
            assert_eq(noun.as_field(cursor), 0)
            return (body, left)
        }
        cursor = noun.tail(cursor)
    }
    assert_eq(0, 1)
    (body, left)
}

#[pure]
fn reject(name: bytes.Bytes, index: U32, code: Field) -> View {
    let zero = syntax.ZERO
    View { source: bytes.empty(), name, index, sequence_limit: zero,
        depth_limit: zero, error: syntax.error(code, zero, zero),
        profile: 0, package: Package { modules: seq.empty(), read_cost: zero, remaining: zero,
            source_limit: zero, options: noun.atom(0) } }
}

#[pure]
fn byte_cost(value: bytes.Bytes) -> U32 {
    let length = bytes.len(value)
    let rest = length & as_u32(3)
    let mut words = as_u32(field.sub(as_field(length), as_field(rest)) * INV4)
    if (rest == syntax.ZERO) == false { words = as_u32(as_field(words) + 1) }
    as_u32(as_field(tree.shape(words).height) + 1)
}

// Both paths are validated; repeated comparison reads still spend admission work.
#[pure]
#[requires((as_u32(255) < bytes.len(left)) == false)]
#[requires((as_u32(255) < bytes.len(right)) == false)]
fn before(left: bytes.Bytes, right: bytes.Bytes, allowance: U32) -> (Bool, U32) {
    let mut remaining = allowance
    let cost = as_u32(as_field(byte_cost(left)) + as_field(byte_cost(right)))
    let left_length = bytes.len(left)
    let right_length = bytes.len(right)
    let mut index = syntax.ZERO
    // Every block starts at lane zero. A partial final word returns at the
    // first end or differing byte; its canonical padding never orders paths.
    for block in 0..64 {
        if index == bytes.len(left) { return (index < bytes.len(right), remaining) }
        if index == bytes.len(right) { return (false, remaining) }
        // Cover the first path reads before fetching either packed word.
        remaining = charge(remaining, cost)
        let a = bytes.word_at(left, index)
        let b = bytes.word_at(right, index)
        let end = as_u32(as_field(index) + 4)
        let mut complete_equal = false
        if a == b { complete_equal = syntax.both((left_length < end) == false, (right_length < end) == false) }
        if complete_equal {
            // The first byte pair was already charged; retain the other three
            // historical charges even though the packed equality shares work.
            remaining = charge(remaining, as_u32(as_field(cost) * 3))
            index = end
        } else {
            for lane in 0..4 {
                if (lane == syntax.ZERO) == false {
                    if index == left_length { return ((index < right_length), remaining) }
                    if index == right_length { return (false, remaining) }
                    remaining = charge(remaining, cost)
                }
                let first = bytes.word_byte(a, lane)
                let second = bytes.word_byte(b, lane)
                if first < second { return (true, remaining) }
                if second < first { return (false, remaining) }
                index = syntax.inc(index)
            }
        }
    }
    (false, remaining)
}

// Binary search the admitted ASCII-sorted table: at most seventeen probes for
// 65536 records. Package indices never use the source/AST capacity sentinel.
#[pure]
#[requires((as_u32(65536) < seq.len(package.modules)) == false)]
#[requires((as_u32(255) < bytes.len(name)) == false)]
pub fn find(package: Package, name: bytes.Bytes) -> Found {
    assert((as_u32(65536) < seq.len(package.modules)) == false)
    assert((as_u32(255) < bytes.len(name)) == false)
    let wanted = bytes.to_noun(name)
    let mut remaining = package.remaining
    let mut low = syntax.ZERO
    let mut high = seq.len(package.modules)
    for turn in 0..17 {
        if low == high { return Found { exists: false, index: seq.len(package.modules), remaining } }
        let sum = as_u32(as_field(low) + as_field(high))
        let index = as_u32(field.sub(as_field(sum), as_field(sum & as_u32(1))) * INV2)
        remaining = charge(remaining, package.read_cost)
        let (body, left) = record(seq.get(package.modules, index), 1297040433, as_u32(4), remaining)
        remaining = charge(left, as_u32(1))
        let path = slot(body, syntax.ZERO)
        if noun.eq(path, wanted) { return Found { exists: true, index, remaining } }
        let (candidate, left) = bytes.from_noun_budget(path, as_u32(255), remaining)
        let (earlier, left) = before(candidate, name, left)
        remaining = left
        if earlier { low = as_u32(as_field(index) + 1) }
        else { high = index }
    }
    Found { exists: false, index: seq.len(package.modules), remaining }
}

// The resolver calls this once per newly reached source, after lookup.
#[pure]
#[requires(index < seq.len(package.modules))]
pub fn open(package: Package, index: U32, source_capacity: U32) -> Source {
    assert(index < seq.len(package.modules))
    let remaining = charge(package.remaining, package.read_cost)
    let (body, left) = record(seq.get(package.modules, index), 1297040433, as_u32(4), remaining)
    let remaining = charge(left, as_u32(7))
    let source = slot(body, as_u32(3))
    let length = as_u32(noun.as_field(noun.head(noun.tail(source))))
    if syntax.either((source_capacity < length), (syntax.SOURCE_CAP < length)) {
        return Source { content: bytes.empty(), remaining, error: syntax.error(7, syntax.ZERO, syntax.ZERO) }
    }
    let (content, remaining) = bytes.from_noun_budget(source, package.source_limit, remaining)
    Source { content, remaining, error: syntax.error(0, syntax.ZERO, syntax.ZERO) }
}

#[pure]
pub fn read(input: Noun) -> View {
    // Bootstrap: tail(JOB), slot5, tail(LIM), slot4, atom = 14 probes.
    let raw_limits = slot(noun.tail(input), as_u32(5))
    let allowance = as_u32(noun.as_field(slot(noun.tail(raw_limits), as_u32(4))))
    let mut remaining = charge(allowance, as_u32(14))
    let (job, r0) = record(input, 1246708273, as_u32(6), remaining)
    let (limits, r1) = record(raw_limits, 1279872305, as_u32(11), r0)
    // Slots 0,3,7, with scalar projection for each: 2+5+9.
    remaining = charge(r1, as_u32(16))
    let source_limit = as_u32(noun.as_field(slot(limits, syntax.ZERO)))
    let sequence_limit = as_u32(noun.as_field(slot(limits, as_u32(3))))
    let depth_limit = as_u32(noun.as_field(slot(limits, as_u32(7))))
    // JOB entry name, function, options and package slots: 3+4+5+2.
    remaining = charge(remaining, as_u32(14))
    let entry = slot(job, as_u32(2))
    let function = slot(job, as_u32(3))
    let opts = slot(job, as_u32(4))
    let package = slot(job, as_u32(1))
    let (name, r2) = bytes.from_noun_budget(entry, as_u32(255), remaining)
    let (entry_function, r3) = bytes.from_noun_budget(function, as_u32(255), r2)
    let (options, r4) = record(opts, 1330664497, as_u32(5), r3)
    // Generated profile slots1/2 and their scalar projections: 3+4.
    remaining = charge(r4, as_u32(7))
    let input_profile = noun.as_field(slot(options, as_u32(1)))
    let output_profile = noun.as_field(slot(options, as_u32(2)))
    let (pkg, r5) = record(package, 1347110705, as_u32(1), remaining)
    remaining = charge(r5, as_u32(1))
    let (modules, r6) = seq.from_noun_budget(slot(pkg, syntax.ZERO), sequence_limit, remaining)
    remaining = r6
    let geometry = tree.shape(seq.len(modules))
    let read_cost = as_u32(as_field(geometry.height) + 1)
    for index in 0..65536 {
        if index == seq.len(modules) {
            assert_eq(0, 1)
            return reject(name, syntax.ZERO, 3)
        }
        // Indexed reads charge their complete path (height+1).
        // Bound is computed from the canonical occupied-leaf length.
        remaining = charge(remaining, read_cost)
        let (entry_record, left) = record(seq.get(modules, index), 1297040433, as_u32(4), remaining)
        remaining = charge(left, as_u32(1))
        if noun.eq(slot(entry_record, syntax.ZERO), entry) {
            if syntax.either(syntax.either(input_profile == 0, input_profile == 1) == false, (output_profile == input_profile) == false) { return reject(name, index, 6) }
            if (bytes.len(entry_function) == as_u32(4)) == false { return reject(name, index, 6) }
            // Four reads in the one-word entry-function payload.
            remaining = charge(remaining, as_u32(4))
            if syntax.either(syntax.either(syntax.either((bytes.get(entry_function, syntax.ZERO) == as_u32(109)) == false, (bytes.get(entry_function, as_u32(1)) == as_u32(97)) == false), (bytes.get(entry_function, as_u32(2)) == as_u32(105)) == false), (bytes.get(entry_function, as_u32(3)) == as_u32(110)) == false) { return reject(name, index, 6) }
            // Slot3 plus raw BYT1 length tail/head/atom: 4+3 probes.
            remaining = charge(remaining, as_u32(7))
            let source = slot(entry_record, as_u32(3))
            let source_length = as_u32(noun.as_field(noun.head(noun.tail(source))))
            if syntax.SOURCE_CAP < source_length { return reject(name, index, 7) }
            let (content, left) = bytes.from_noun_budget(source, source_limit, remaining)
            return View { source: content, name, index, sequence_limit, depth_limit,
                error: syntax.error(0, syntax.ZERO, syntax.ZERO),
                package: Package { modules, read_cost, remaining: left, source_limit, options: opts }, profile: input_profile }
        }
    }
    // The host contract guarantees a matching entry module.
    assert_eq(0, 1)
    reject(name, syntax.ZERO, 3)
}

sources.std.compiler.nox.lexer:
module std.compiler.nox.lexer

use std.nox.bytes
use std.compiler.nox.syntax
use std.compiler.nox.ascii
use vm.core.convert
use vm.core.field

#[pure]
fn identifier(source: bytes.Bytes, start: U32) -> syntax.Token {
    let mut pos = start
    let mut packed: Field = 0
    for step in 0..65536 {
        if pos == bytes.len(source) { return syntax.token(ascii.keyword(packed), start, pos, packed) }
        let c = bytes.get(source, pos)
        if (syntax.either(ascii.initial(c), ascii.digit(c))) == false {
            return syntax.token(ascii.keyword(packed), start, pos, packed)
        }
        if step < as_u32(7) { packed = packed * 256 + as_field(c) }
        else { packed = 0 }
        pos = syntax.inc(pos)
    }
    syntax.token(1, start, pos, 0)
}

#[pure]
fn decimal(source: bytes.Bytes, start: U32) -> syntax.Token {
    let max_digits = [1,8,4,4,6,7,4,4,0,7,3,7,0,9,5,5,1,6,1,5]
    let mut pos = start
    let mut significant = syntax.ZERO
    let mut comparison: Field = 0
    let mut value: Field = 0
    let mut overflow = false
    for step in 0..65536 {
        if pos == bytes.len(source) {
            if overflow { return syntax.token(14, start, pos, 0) }
            return syntax.token(2, start, pos, value)
        }
        let c = bytes.get(source, pos)
        if ascii.digit(c) == false {
            if overflow { return syntax.token(14, start, pos, 0) }
            return syntax.token(2, start, pos, value)
        }
        let digit = field.sub(as_field(c), 48)
        value = value * 10 + digit
        if syntax.either((significant == syntax.ZERO) == false, (digit == 0) == false) {
            if significant < as_u32(20) {
                let expected = max_digits[significant]
                if comparison == 0 {
                    if as_u32(digit) < as_u32(expected) { comparison = 1 }
                    if as_u32(expected) < as_u32(digit) { comparison = 2 }
                }
            }
            significant = syntax.inc(significant)
            if syntax.either(as_u32(20) < significant, (syntax.both(significant == as_u32(20), comparison == 2))) { overflow = true }
        }
        pos = syntax.inc(pos)
    }
    if overflow { return syntax.token(14, start, pos, 0) }
    syntax.token(2, start, pos, value)
}

// Token kinds: EOF=0, identifier=1, decimal=2, +=3, *=4, (=5, )=6,
// {=7, }=8, ->=9, program=10, fn=11, Field=12, unsupported=13, invalid=14,
// let=15, mut=16, colon=17, assignment=18, equality=19, Bool=20,
// true=21, false=22, if=23, else=24, return=25, comma=26;
// 43 is semicolon; 44 is the internal array marker; const=45; #=46.
// 38 is the internal tuple marker; struct=39, pub=40, .=41, internal record marker=42.
// 27 is the internal call marker; U32=28, less-than=29, &=30, for=31, in=32, ..=33, Noun=34, Digest=35, [=36, ]=37.
#[pure]
#[requires((syntax.SOURCE_CAP < bytes.len(source)) == false)]
#[requires((bytes.len(source) < start) == false)]
pub fn next(source: bytes.Bytes, start: U32) -> syntax.Token {
    let mut pos = start
    let mut comment = false
    for step in 0..65537 {
        if pos == bytes.len(source) { return syntax.token(0, pos, pos, 0) }
        let c = bytes.get(source, pos)
        if comment {
            if c == as_u32(10) { comment = false }
        } else if ascii.space(c) == false {
            // Look ahead only for a slash. Eager helper arguments otherwise
            // charge every tuple/group delimiter for comment-prefix work.
            if c == as_u32(47) {
                if syntax.inc(pos) < bytes.len(source) {
                    if bytes.get(source, syntax.inc(pos)) == as_u32(47) { comment = true }
                }
            }
            if comment == false {
                // Parentheses delimit calls, groups and tuples. Recognize them
                // before identifier/decimal classification on the hot path.
                if c == as_u32(40) { return syntax.token(5, pos, syntax.inc(pos), 0) }
                if c == as_u32(41) { return syntax.token(6, pos, syntax.inc(pos), 0) }
                if ascii.initial(c) { return identifier(source, pos) }
                if ascii.digit(c) { return decimal(source, pos) }
                let end = syntax.inc(pos)
                if c == as_u32(43) { return syntax.token(3, pos, end, 0) }
                if c == as_u32(42) { return syntax.token(4, pos, end, 0) }
                if c == as_u32(123) { return syntax.token(7, pos, end, 0) }
                if c == as_u32(125) { return syntax.token(8, pos, end, 0) }
                if syntax.both(c == as_u32(45), end < bytes.len(source)) {
                    if bytes.get(source, end) == as_u32(62) { return syntax.token(9, pos, syntax.inc(end), 0) }
                }
                if syntax.both(c == as_u32(47), end < bytes.len(source)) {
                    if bytes.get(source, end) == as_u32(37) { return syntax.token(13, pos, syntax.inc(end), 0) }
                }
                if c == as_u32(91) { return syntax.token(36, pos, end, 0) }
                if c == as_u32(93) { return syntax.token(37, pos, end, 0) }
                if c == as_u32(59) { return syntax.token(43, pos, end, 0) }
                if c == as_u32(35) { return syntax.token(46, pos, end, 0) }
                if c == as_u32(44) { return syntax.token(26, pos, end, 0) }
                if c == as_u32(60) { return syntax.token(29, pos, end, 0) }
                if c == as_u32(38) { return syntax.token(30, pos, end, 0) }
                if syntax.both(c == as_u32(46), end < bytes.len(source)) {
                    if bytes.get(source, end) == as_u32(46) { return syntax.token(33, pos, syntax.inc(end), 0) }
                }
                if c == as_u32(46) { return syntax.token(41, pos, end, 0) }
                if c == as_u32(58) { return syntax.token(17, pos, end, 0) }
                if c == as_u32(61) {
                    if end < bytes.len(source) {
                        if bytes.get(source, end) == as_u32(61) { return syntax.token(19, pos, syntax.inc(end), 0) }
                    }
                    return syntax.token(18, pos, end, 0)
                }
                // Full-language punctuation outside the current subset.
                if ascii.punctuation(c) {
                    return syntax.token(13, pos, end, 0)
                }
                return syntax.token(14, pos, end, 0)
            }
        }
        pos = syntax.inc(pos)
    }
    syntax.token(14, pos, pos, 0)
}

sources.std.compiler.nox.loop_gen:
module std.compiler.nox.loop_gen

use vm.nox.noun
use vm.core.convert
use vm.core.field
use std.nox.seq
use std.nox.tree
use std.compiler.nox.syntax
use std.compiler.nox.loop_records
use std.compiler.nox.codegen
use std.compiler.nox.call_codegen
use std.compiler.nox.formula
use std.compiler.nox.flow

#[pure]
fn binary(opcode: Field, a: formula.Value, b: formula.Value) -> formula.Value {
    formula.Value { formula: noun.pair(noun.atom(opcode), noun.pair(a.formula, b.formula)),
        depth: as_u32(as_field(formula.maximum(a.depth, b.depth)) + 2) }
}

#[pure]
fn invoke(context: call_codegen.Context, id: U32) -> formula.Value {
    formula.apply(flow.axis(1), flow.axis(2 * context.table.capacity + as_field(context.loop_base) + as_field(id)))
}

#[pure]
pub fn initialize(record: loop_records.Loop, id: U32, shape: tree.Shape, context: call_codegen.Context) -> formula.Value {
    if loop_records.nonempty(record) == false { return flow.keep(flow.axis(1)) }
    let index = codegen.edit(record.index, shape, flow.literal(record.first))
    let count = codegen.edit(record.remaining, shape, flow.literal(field.sub(record.end, record.first)))
    flow.compose(flow.compose(index, count), invoke(context, id))
}

#[pure]
fn iteration(record: loop_records.Loop, id: U32, body: formula.Value, shape: tree.Shape, context: call_codegen.Context) -> formula.Value {
    if loop_records.nonempty(record) == false { return flow.keep(flow.axis(1)) }
    let remaining = flow.axis(7 * shape.capacity + as_field(record.remaining))
    let index = flow.axis(7 * shape.capacity + as_field(record.index))
    let done = binary(9, remaining, flow.literal(0))
    let decrement = codegen.edit(record.remaining, shape, binary(6, remaining, flow.literal(1)))
    let increment = codegen.edit(record.index, shape, binary(5, index, flow.literal(1)))
    // The final candidate exits before increment, including index U32_MAX.
    let next = flow.compose(decrement, flow.branch(done, flow.keep(flow.axis(1)), flow.compose(increment, invoke(context, id))))
    flow.branch(done, flow.keep(flow.axis(1)), flow.then(body, next))
}

pub struct Emitted { pub values: seq.Seq, pub next: U32, pub failed: Bool }

#[pure]
fn chunk(loops: seq.Seq, blocks: seq.Seq, shape: tree.Shape, context: call_codegen.Context, input: Emitted, depth_cap: U32) -> Emitted {
    let mut s = input
    for turn in 0..8 {
        if s.next == seq.len(loops) { return s }
        let record = loop_records.read(seq.get(loops, s.next))
        let value = iteration(record, s.next, formula.value(blocks, record.body), shape, context)
        if depth_cap < as_u32(as_field(value.depth) + 9) { s.failed = true return s }
        // Source-order IDs are independent of block postorder, including nesting.
        s.values = seq.push(s.values, formula.pack(value), seq.len(loops))
        s.next = syntax.inc(s.next)
    }
    s
}

#[pure]
#[requires((syntax.TABLE_CAP < seq.len(loops)) == false)]
pub fn generate(loops: seq.Seq, blocks: seq.Seq, shape: tree.Shape, context: call_codegen.Context, depth_cap: U32) -> Emitted {
    let mut s = Emitted { values: seq.empty(), next: syntax.ZERO, failed: false }
    for turn in 0..512 {
        s = chunk(loops, blocks, shape, context, s, depth_cap)
        if syntax.either(s.failed, s.next == seq.len(loops)) { return s }
    }
    s.failed = true
    s
}

sources.std.compiler.nox.loop_parse:
module std.compiler.nox.loop_parse

use vm.nox.noun
use vm.core.convert
use vm.core.field
use std.nox.bytes
use std.nox.seq
use std.compiler.nox.syntax
use std.compiler.nox.lexer
use std.compiler.nox.ast
use std.compiler.nox.symbols
use std.compiler.nox.blocks
use std.compiler.nox.contexts
use std.compiler.nox.body_state
use std.compiler.nox.loop_records
use std.compiler.nox.types

struct Bound { value: Field, error: syntax.Error }

// Tokens normalize decimal values in Goldilocks. Loop candidates instead use
// their raw decimal range, including the exclusive end 2^32.
#[pure]
#[requires(syntax.either(last_digit == as_u32(5), last_digit == as_u32(6)))]
fn bound(source: bytes.Bytes, token: syntax.Token, last_digit: U32) -> Bound {
    let mut result = Bound { value: 0, error: syntax.error(0, token.start, token.end) }
    if (token.kind == as_u32(2)) == false {
        let mut code: Field = 2
        if syntax.either(token.kind == as_u32(1), token.kind == as_u32(5)) { code = 6 }
        if syntax.either(token.kind == as_u32(21), token.kind == as_u32(22)) { code = 5 }
        result.error = ast.failed(token, code)
        return result
    }
    let mut pos = token.start
    for turn in 0..65536 {
        if pos == token.end { return result }
        let digit = as_u32(field.sub(as_field(bytes.get(source, pos)), 48))
        if result.value == 4294967296 { result.error = syntax.error(5, token.start, token.end) return result }
        let value = as_u32(result.value)
        if syntax.either(as_u32(429496729) < value,
            syntax.both(value == as_u32(429496729), last_digit < digit)) {
            result.error = syntax.error(5, token.start, token.end)
            return result
        }
        result.value = result.value * 10 + as_field(digit)
        pos = syntax.inc(pos)
    }
    result.error = syntax.error(7, token.start, token.end)
    result
}

#[pure]
#[requires((syntax.SOURCE_CAP < bytes.len(source)) == false)]
pub fn enter(source: bytes.Bytes, input: body_state.State, cap: U32) -> body_state.State {
    let mut s = input
    let mut nesting = cap
    if syntax.STACK_CAP < nesting { nesting = syntax.STACK_CAP }
    if syntax.either(nesting == syntax.ZERO, syntax.inc(s.depth) == nesting) {
        s.error = syntax.error(7, s.token.start, s.token.end)
        return s
    }
    let name = lexer.next(source, s.token.end)
    if (name.kind == as_u32(1)) == false { s.error = ast.failed(name, 2) return s }
    s.token = lexer.next(source, name.end)
    if (s.token.kind == as_u32(32)) == false { s.error = ast.failed(s.token, 2) return s }
    s.token = lexer.next(source, s.token.end)
    let first = bound(source, s.token, as_u32(5))
    s.error = first.error
    if (s.error.code == syntax.ZERO) == false { return s }
    s.token = lexer.next(source, s.token.end)
    if (s.token.kind == as_u32(33)) == false { s.error = ast.failed(s.token, 2) return s }
    s.token = lexer.next(source, s.token.end)
    let end = bound(source, s.token, as_u32(6))
    s.error = end.error
    if (s.error.code == syntax.ZERO) == false { return s }
    s.token = lexer.next(source, s.token.end)
    if (s.token.kind == as_u32(7)) == false { s.error = ast.failed(s.token, 2) return s }
    if syntax.either(seq.len(s.loops) == cap, cap < as_u32(as_field(seq.len(s.bindings)) + 2)) {
        s.error = syntax.error(7, name.start, s.token.end)
        return s
    }
    let id = seq.len(s.loops)
    let index = seq.len(s.bindings)
    let record = loop_records.Loop { index, remaining: syntax.inc(index), first: first.value, end: end.value, body: blocks.NONE }
    s.loops = seq.push(s.loops, loop_records.pack(record), cap)
    let frame = contexts.Frame { statements: s.current, visible: s.visible, returned: s.returned,
        synthetic: s.synthetic, start: s.start, condition: id, then_block: blocks.NONE, phase: 2 }
    s.frames = noun.pair(contexts.pack(frame), s.frames)
    s.depth = syntax.inc(s.depth)
    s.bindings = seq.push(s.bindings, symbols.binding(name, false, noun.atom(types.UINT32)), cap)
    // The remaining count can be 2^32. It is an invisible Field slot.
    s.bindings = seq.push(s.bindings, symbols.binding(name, false, noun.atom(types.FIELD)), cap)
    s.visible = noun.pair(noun.atom(as_field(index)), s.visible)
    s.start = s.token.start
    s.token = lexer.next(source, s.token.end)
    s.current = noun.atom(0)
    s.synthetic = false
    s.returned = false
    s.has_tail = false
    s
}

sources.std.compiler.nox.loop_records:
module std.compiler.nox.loop_records

use vm.nox.noun
use vm.core.convert

pub struct Loop { pub index: U32, pub remaining: U32, pub first: Field, pub end: Field, pub body: U32 }

#[pure]
pub fn pack(value: Loop) -> Noun {
    let slots = noun.pair(noun.atom(as_field(value.index)), noun.atom(as_field(value.remaining)))
    let range = noun.pair(noun.atom(value.first), noun.atom(value.end))
    noun.pair(slots, noun.pair(range, noun.atom(as_field(value.body))))
}

#[pure]
pub fn read(value: Noun) -> Loop {
    let slots = noun.head(value)
    let contents = noun.tail(value)
    let range = noun.head(contents)
    Loop { index: as_u32(noun.as_field(noun.head(slots))), remaining: as_u32(noun.as_field(noun.tail(slots))),
        first: noun.as_field(noun.head(range)), end: noun.as_field(noun.tail(range)), body: as_u32(noun.as_field(noun.tail(contents))) }
}

#[pure]
#[requires(as_field(as_u32(value.first)) == value.first)]
pub fn nonempty(value: Loop) -> Bool {
    if value.end == 4294967296 { return true }
    as_u32(value.first) < as_u32(value.end)
}

