module std.compiler.nox.module_function_order

use vm.nox.noun
use vm.core.field
use std.nox.bytes
use std.nox.seq
use std.nox.tree
use std.compiler.nox.syntax
use std.compiler.nox.signatures
use std.compiler.nox.function_order

struct Sources {
    functions: seq.Seq, owners: seq.Seq, names: bytes.BytesTable, sources: bytes.BytesTable
}
struct Merge { output: seq.Seq, left: U32, right: U32, middle: U32, end: U32 }
struct RankedOwners { root: Noun, count: U32 }
const HALF: Field = 9223372034707292161

#[pure]
fn before_span(left: bytes.Bytes, a: syntax.Token, right: bytes.Bytes, b: syntax.Token) -> Bool {
    let mut x = a.start
    let mut y = b.start
    if x == a.end { return (y == b.end) == false }
    if y == b.end { return false }
    let mut first_word = bytes.word_at(left, x)
    let mut second_word = bytes.word_at(right, y)
    for step in 0..65536 {
        if x == a.end { return (y == b.end) == false }
        if y == b.end { return false }
        let first_lane = x & as_u32(3)
        let second_lane = y & as_u32(3)
        let mut advance = as_u32(1)
        // Equal packed words preserve every byte comparison. Skip only the
        // common suffix that lies entirely inside both source name spans.
        if syntax.both(first_lane == second_lane, first_word == second_word) {
            let stride = as_u32(field.sub(4, as_field(first_lane)))
            let next_x = as_u32(as_field(x) + as_field(stride))
            let next_y = as_u32(as_field(y) + as_field(stride))
            if syntax.both((a.end < next_x) == false, (b.end < next_y) == false) { advance = stride }
        }
        if advance == as_u32(1) {
            let first = bytes.word_byte(first_word, first_lane)
            let second = bytes.word_byte(second_word, second_lane)
            if first < second { return true }
            if second < first { return false }
        }
        x = as_u32(as_field(x) + as_field(advance))
        y = as_u32(as_field(y) + as_field(advance))
        if syntax.both(x < a.end, (x & as_u32(3)) == syntax.ZERO) { first_word = bytes.word_at(left, x) }
        if syntax.both(y < b.end, (y & as_u32(3)) == syntax.ZERO) { second_word = bytes.word_at(right, y) }
    }
    false
}

// Compare the pair (owner, member), not their dotted concatenation. In
// particular, owner a precedes a.b independently of their member names.
#[pure]
fn before(scope: Sources, left: U32, right: U32) -> Bool {
    let a = as_u32(noun.as_field(seq.get(scope.owners, left)))
    let b = as_u32(noun.as_field(seq.get(scope.owners, right)))
    if (a == b) == false {
        let first = bytes.table_get(scope.names, a)
        let second = bytes.table_get(scope.names, b)
        return before_span(first, syntax.token(1, syntax.ZERO, bytes.len(first), 0),
            second, syntax.token(1, syntax.ZERO, bytes.len(second), 0))
    }
    let source = bytes.table_get(scope.sources, a)
    before_span(source, signatures.read(seq.get(scope.functions, left)).name,
        source, signatures.read(seq.get(scope.functions, right)).name)
}

#[pure]
fn merge_chunk(scope: Sources, values: seq.Seq, input: Merge, cap: U32) -> Merge {
    let mut s = input
    for step in 0..8 {
        if seq.len(s.output) == s.end { return s }
        let mut take_right = s.left == s.middle
        if syntax.both(s.left < s.middle, s.right < s.end) {
            let left = as_u32(noun.as_field(seq.get(values, s.left)))
            let right = as_u32(noun.as_field(seq.get(values, s.right)))
            // Equal keys retain the left run's original declaration order.
            take_right = before(scope, right, left)
        }
        if take_right {
            s.output = seq.push(s.output, seq.get(values, s.right), cap)
            s.right = syntax.inc(s.right)
        } else {
            s.output = seq.push(s.output, seq.get(values, s.left), cap)
            s.left = syntax.inc(s.left)
        }
    }
    s
}

#[pure]
fn merge(scope: Sources, values: seq.Seq, width: U32, output: seq.Seq, cap: U32) -> seq.Seq {
    let start = seq.len(output)
    let mut middle = as_u32(as_field(start) + as_field(width))
    if seq.len(values) < middle { middle = seq.len(values) }
    let mut end = as_u32(as_field(middle) + as_field(width))
    if seq.len(values) < end { end = seq.len(values) }
    let mut s = Merge { output, left: start, right: middle, middle, end }
    for block in 0..512 {
        s = merge_chunk(scope, values, s, cap)
        if seq.len(s.output) == s.end { return s.output }
    }
    s.output
}

#[pure]
fn pass(scope: Sources, values: seq.Seq, width: U32, cap: U32) -> seq.Seq {
    let mut output = seq.empty()
    for run in 0..4096 {
        if seq.len(output) == seq.len(values) { return output }
        output = merge(scope, values, width, output, cap)
    }
    output
}

#[pure]
fn prefix(roots: seq.Seq, cap: U32) -> seq.Seq {
    let mut output = seq.empty()
    for next in 0..4096 {
        if next == cap { return output }
        output = seq.push(output, seq.get(roots, next), cap)
    }
    output
}

#[pure]
fn ordered(scope: Sources, roots: seq.Seq, cap: U32) -> function_order.Ordered {
    let mut result = function_order.Ordered { ids: roots, next: seq.len(roots),
        error: syntax.error(0, syntax.ZERO, syntax.ZERO) }
    // Preserve the sorted admitted prefix and processed count on exhaustion.
    if cap < seq.len(roots) {
        result.ids = prefix(roots, cap)
        result.next = cap
        result.error = syntax.error(7, syntax.ZERO, syntax.ZERO)
    }
    let mut width = as_u32(1)
    // TABLE_CAP is 4096, so twelve doubling passes cover every admitted root.
    for level in 0..12 {
        if (width < seq.len(result.ids)) == false { return result }
        result.ids = pass(scope, result.ids, width, cap)
        width = as_u32(as_field(width) * 2)
    }
    result
}

#[pure]
fn buckets(owners: seq.Seq, roots: seq.Seq, count: U32) -> Noun {
    let mut output = tree.empty(tree.shape(count).height)
    for index in 0..4096 {
        if index == seq.len(roots) { return output }
        let value = seq.get(roots, index)
        let owner = as_u32(noun.as_field(seq.get(owners, as_u32(noun.as_field(value)))))
        output = tree.set(output, count, owner, noun.pair(value, tree.get(output, count, owner)))
    }
    output
}

#[pure]
fn ranked_owners(table: Noun, ranks: seq.Seq) -> RankedOwners {
    let count = seq.len(ranks)
    let mut output = RankedOwners { root: tree.empty(as_u32(16)), count: syntax.ZERO }
    for owner in 0..4096 {
        if owner == count { return output }
        if noun.eq(tree.get(table, count, owner), noun.atom(0)) == false {
            let rank = as_u32(noun.as_field(seq.get(ranks, owner)))
            output.root = tree.set(output.root, as_u32(65536), rank, noun.atom(as_field(owner) + 1))
            output.count = syntax.inc(output.count)
        }
    }
    output
}

// Admitted package indices use at most sixteen bits. Shared zero subtrees let
// selection skip absent package slots without scanning the package length.
#[pure]
fn first_rank(root: Noun) -> U32 {
    let mut cursor = root
    let mut padding = tree.empty(as_u32(16))
    let mut stride: Field = 65536
    let mut offset: Field = 0
    for level in 0..16 {
        stride = stride * HALF
        padding = noun.head(padding)
        let left = noun.head(cursor)
        if noun.eq(left, padding) { cursor = noun.tail(cursor) offset = offset + stride }
        else { cursor = left }
    }
    as_u32(offset)
}

#[pure]
fn owner_order(input: RankedOwners, cap: U32) -> seq.Seq {
    let mut table = input.root
    let mut output = seq.empty()
    for index in 0..4096 {
        if index == input.count { return output }
        let rank = first_rank(table)
        let owner = syntax.dec(as_u32(noun.as_field(tree.get(table, as_u32(65536), rank))))
        output = seq.push(output, noun.atom(as_field(owner)), cap)
        table = tree.set(table, as_u32(65536), rank, noun.atom(0))
    }
    output
}

#[pure]
fn reverse(input: Noun) -> Noun {
    let mut rest = input
    let mut output = noun.atom(0)
    for index in 0..4096 {
        if noun.eq(rest, noun.atom(0)) { return output }
        output = noun.pair(noun.head(rest), output)
        rest = noun.tail(rest)
    }
    output
}

#[pure]
fn member_roots(input: Noun, cap: U32) -> seq.Seq {
    let mut rest = reverse(input)
    let mut output = seq.empty()
    for index in 0..4096 {
        if noun.eq(rest, noun.atom(0)) { return output }
        output = seq.push(output, noun.head(rest), cap)
        rest = noun.tail(rest)
    }
    output
}

#[pure]
fn append(values: seq.Seq, input: seq.Seq, cap: U32) -> seq.Seq {
    let mut output = input
    for index in 0..4096 {
        if index == seq.len(values) { return output }
        output = seq.push(output, seq.get(values, index), cap)
    }
    output
}

// Bucket by the complete owner identity, preserving original member order.
// Only active owners consume sort slots, including on a capacity-error prefix.
#[pure]
fn grouped(functions: seq.Seq, owners: seq.Seq, sources: bytes.BytesTable, roots: seq.Seq, ranks: seq.Seq, cap: U32) -> function_order.Ordered {
    let mut admitted = roots
    let mut error = syntax.error(0, syntax.ZERO, syntax.ZERO)
    if cap < seq.len(roots) { admitted = prefix(roots, cap) error = syntax.error(7, syntax.ZERO, syntax.ZERO) }
    let table = buckets(owners, admitted, seq.len(ranks))
    let owners = owner_order(ranked_owners(table, ranks), cap)
    let mut result = function_order.Ordered { ids: seq.empty(), next: seq.len(admitted), error }
    for position in 0..4096 {
        if position == seq.len(owners) { return result }
        let owner = as_u32(noun.as_field(seq.get(owners, position)))
        let members = member_roots(tree.get(table, seq.len(ranks), owner), cap)
        let sorted = function_order.sort_roots(bytes.table_get(sources, owner), functions, members, cap)
        result.ids = append(sorted, result.ids, cap)
    }
    result
}

#[pure]
#[requires((syntax.TABLE_CAP < seq.len(functions)) == false)]
#[requires((cap < seq.len(roots)) == false)]
pub fn sort(functions: seq.Seq, owners: seq.Seq, names: bytes.BytesTable, sources: bytes.BytesTable, roots: seq.Seq, cap: U32) -> function_order.Ordered {
    ordered(Sources { functions, owners, names, sources }, roots, cap)
}

// Compiler-owned ranks are admitted JOB1 package indices. Its module paths are
// strictly ASCII-sorted and unique, so rank comparison is complete owner-name
// comparison, including prefix-related paths. This entry consumes that proven
// ordering; standalone callers without it use sort's complete byte comparison.
#[pure]
#[requires((syntax.TABLE_CAP < seq.len(functions)) == false)]
#[requires((cap < seq.len(roots)) == false)]
#[requires(seq.len(ranks) == bytes.table_len(names))]
#[requires((syntax.TABLE_CAP < bytes.table_len(names)) == false)]
pub fn sort_ranked(functions: seq.Seq, owners: seq.Seq, names: bytes.BytesTable, sources: bytes.BytesTable, roots: seq.Seq, ranks: seq.Seq, cap: U32) -> function_order.Ordered {
    assert(seq.len(ranks) == bytes.table_len(names))
    grouped(functions, owners, sources, roots, ranks, cap)
}

sources.std.compiler.nox.module_functions:
module std.compiler.nox.module_functions

use vm.nox.noun
use std.nox.bytes
use std.nox.seq
use std.compiler.nox.syntax
use std.compiler.nox.signatures
use std.compiler.nox.headers
use std.compiler.nox.check_functions
use std.compiler.nox.module_graph
use std.compiler.nox.module_store
use std.compiler.nox.constant_exports
use std.compiler.nox.constant_imports
use std.compiler.nox.const_module
use std.compiler.nox.function_exports
use std.compiler.nox.function_imports
use std.compiler.nox.type_exports
use std.compiler.nox.type_imports
use std.compiler.nox.type_registry
use std.compiler.nox.nominal
use std.compiler.nox.intrinsic_bindings

// Declaration IDs are shared by signatures, checked bodies and owner records.
// Final roots retain private helpers, while exports contain only public targets.
pub struct Bank {
    pub functions: seq.Seq, pub params: seq.Seq, pub bodies: seq.Seq,
    pub owners: seq.Seq, pub roots: seq.Seq,
    pub exports: function_exports.Bank, pub constants: constant_exports.Bank,
    pub types: type_exports.Bank, pub type_count: U32, pub entry: U32, pub structured: Bool, pub error: syntax.Error, pub intrinsics: intrinsic_bindings.Bank
}

#[pure]
#[requires((syntax.TABLE_CAP < modules) == false)]
pub fn empty(modules: U32) -> Bank {
    Bank { functions: seq.empty(), params: seq.empty(), bodies: seq.empty(),
        owners: seq.empty(), roots: seq.empty(), exports: function_exports.empty(modules),
        constants: constant_exports.empty(modules), types: type_exports.empty(modules), type_count: syntax.ZERO, entry: signatures.NONE, structured: false,
        error: syntax.error(0, syntax.ZERO, syntax.ZERO), intrinsics: intrinsic_bindings.empty() }
}

#[pure]
fn publish(source: bytes.Bytes, owner: U32, start: U32, public: seq.Seq, input: Bank, cap: U32) -> Bank {
    let mut s = input
    let mut next = start
    let mut visible = syntax.ZERO
    let end = seq.len(s.functions)
    for step in 0..4096 {
        if next == end { return s }
        let signature = signatures.read(seq.get(s.functions, next))
        let mut exported = false
        if visible < seq.len(public) {
            if noun.as_field(seq.get(public, visible)) == as_field(next) {
                exported = true
                visible = syntax.inc(visible)
            }
        }
        // These banks cannot exceed the already checked global function count.
        s.owners = seq.push(s.owners, noun.atom(as_field(owner)), cap)
        if signatures.lookup_range(source, signature.name, s.functions, start, end) == next {
            s.roots = seq.push(s.roots, noun.atom(as_field(next)), cap)
            if exported {
                let binding = function_exports.Binding { owner, name: signature.name, target: next }
                s.exports = function_exports.push(s.exports, binding, cap)
            }
        }
        next = syntax.inc(next)
    }
    s
}

// Bodies see their declaring module's final local bindings and a frozen view
// of direct dependencies. No name span is ever interpreted in another source.
#[pure]
#[requires(owner < seq.len(graph.modules))]
pub fn check(graph: module_graph.Graph, owner: U32, entry_index: U32, input: Bank) -> Bank {
    check_profile(graph, owner, entry_index, input, 0)
}

#[pure]
#[requires(owner < seq.len(graph.modules))]
#[requires(syntax.either(profile == 0, profile == 1))]
pub fn check_profile(graph: module_graph.Graph, owner: U32, entry_index: U32, input: Bank, profile: Field) -> Bank {
    let mut s = input
    let unit = module_store.read(graph.modules, owner)
    let source = bytes.table_get(graph.sources, owner)
    let name = bytes.table_get(graph.names, owner)
    let constants = constant_imports.View { sources: graph.sources, names: graph.names,
        exports: s.constants, uses: unit.uses }
    let imports = function_imports.View { sources: graph.sources, names: graph.names,
        exports: s.exports, uses: unit.uses }
    let imported_types = type_imports.View { names: graph.names, exports: s.types, uses: unit.uses }
    let start = seq.len(s.functions)
    let entry = unit.index == entry_index
    let mut parsed = headers.scan_with_intrinsics(source, unit.offset, name, constants,
        imported_types, s.type_count, s.functions, s.params, graph.capacity, s.intrinsics)
    s.error = parsed.error
    if (s.error.code == syntax.ZERO) == false { return s }
    if entry {
        parsed = headers.require_profile(headers.validate_entry(parsed), profile)
        s.error = parsed.error
        if (s.error.code == syntax.ZERO) == false { return s }
        s.entry = parsed.entry
        s.structured = parsed.structured
    }
    let checked = check_functions.check_range_with_intrinsics(source, parsed.functions, parsed.params,
        parsed.pure_functions, parsed.types, parsed.constants, graph.capacity,
        start, seq.len(parsed.functions), imports, s.bodies, parsed.intrinsics)
    s.error = checked.error
    if (s.error.code == syntax.ZERO) == false { return s }
    s.intrinsics = parsed.intrinsics
    s.functions = parsed.functions
    s.params = parsed.params
    s.bodies = checked.bodies
    let constants = const_module.publish(source, parsed.constants, owner, s.constants, graph.capacity)
    s.error = constants.error
    if (s.error.code == syntax.ZERO) == false { return s }
    s.constants = constants.exports
    s.type_count = as_u32(as_field(s.type_count) + as_field(seq.len(parsed.types.records)))
    for index in 0..4096 {
        if index == seq.len(parsed.types.records) {
            return publish(source, owner, start, parsed.public_functions, s, graph.capacity)
        }
        let record = seq.get(parsed.types.records, index)
        let ty = noun.head(record)
        if noun.as_field(noun.tail(record)) == 1 {
            if type_registry.position(parsed.types, nominal.name(ty)) == index {
                s.types = type_exports.push(s.types, owner, ty, graph.capacity)
            }
        }
    }
    publish(source, owner, start, parsed.public_functions, s, graph.capacity)
}

sources.std.compiler.nox.module_graph:
module std.compiler.nox.module_graph

use vm.nox.noun
use vm.core.field
use std.nox.bytes
use std.nox.seq
use std.nox.tree
use std.compiler.nox.syntax
use std.compiler.nox.job
use std.compiler.nox.utf8
use std.compiler.nox.lexer
use std.compiler.nox.module_header
use std.compiler.nox.module_store

pub struct Graph {
    pub package: job.Package, pub sources: bytes.BytesTable, pub names: bytes.BytesTable,
    pub modules: seq.Seq, pub indexes: Noun, pub capacity: U32,
    pub total_bytes: U32, pub total_uses: U32, pub error_index: U32, pub error: syntax.Error
}
struct Walk { graph: Graph, current: U32, parents: Noun, depth: U32, done: Bool }

#[pure]
fn fail(input: Graph, index: U32, error: syntax.Error) -> Graph {
    let mut graph = input
    graph.error_index = index
    graph.error = error
    graph
}

// Caller checks remaining shared source capacity before opening the payload.
#[pure]
fn register(input: Graph, index: U32, source: bytes.Bytes, name: bytes.Bytes, entry: Bool) -> Graph {
    let mut graph = input
    if seq.len(graph.modules) == graph.capacity { return fail(graph, index, syntax.error(7, syntax.ZERO, syntax.ZERO)) }
    let encoding = utf8.validate(source)
    if (encoding.code == syntax.ZERO) == false { return fail(graph, index, encoding) }
    let header = module_header.open(source, name, entry)
    if (header.error.code == syntax.ZERO) == false { return fail(graph, index, header.error) }
    register_open(graph, index, source, name, header)
}

#[pure]
fn register_open(input: Graph, index: U32, source: bytes.Bytes, name: bytes.Bytes, header: module_header.Header) -> Graph {
    let mut graph = input
    let id = seq.len(graph.modules)
    let unit = module_store.Module { index, offset: header.token.start,
        status: as_u32(1), count: syntax.ZERO, uses: noun.atom(0) }
    graph.sources = bytes.table_push(graph.sources, source, graph.capacity)
    graph.names = bytes.table_push(graph.names, name, graph.capacity)
    graph.modules = seq.push(graph.modules, module_store.pack(unit), graph.capacity)
    graph.indexes = tree.set(graph.indexes, seq.len(graph.package.modules), index, noun.atom(as_field(id) + 1))
    graph.total_bytes = as_u32(as_field(graph.total_bytes) + as_field(bytes.len(source)))
    graph
}

#[pure]
fn step(input: Walk) -> Walk {
    let mut s = input
    let mut unit = module_store.read(s.graph.modules, s.current)
    let source = bytes.table_get(s.graph.sources, s.current)
    let item = module_header.next_use(source, lexer.next(source, unit.offset))
    if (item.error.code == syntax.ZERO) == false { s.graph = fail(s.graph, unit.index, item.error) return s }
    if item.exists == false {
        unit.offset = item.token.start
        s.graph.modules = seq.set(s.graph.modules, s.current, module_store.pack(module_store.finish(unit)))
        if noun.eq(s.parents, noun.atom(0)) { s.done = true return s }
        s.current = as_u32(noun.as_field(noun.head(s.parents)))
        s.parents = noun.tail(s.parents)
        s.depth = syntax.dec(s.depth)
        return s
    }
    if s.graph.total_uses == s.graph.capacity {
        s.graph = fail(s.graph, unit.index, syntax.error(7, item.start, item.end))
        return s
    }
    let found = job.find(s.graph.package, item.name)
    s.graph.package.remaining = found.remaining
    if found.exists == false { s.graph = fail(s.graph, unit.index, syntax.error(3, item.start, item.end)) return s }
    let saved = as_u32(noun.as_field(tree.get(s.graph.indexes, seq.len(s.graph.package.modules), found.index)))
    let mut target = seq.len(s.graph.modules)
    if (saved == syntax.ZERO) == false {
        target = syntax.dec(saved)
        if module_store.read(s.graph.modules, target).status == as_u32(1) {
            s.graph = fail(s.graph, unit.index, syntax.error(4, item.start, item.end))
            return s
        }
    } else {
        if syntax.either(target == s.graph.capacity, s.depth == s.graph.capacity) {
            s.graph = fail(s.graph, found.index, syntax.error(7, syntax.ZERO, syntax.ZERO))
            return s
        }
        let capacity = as_u32(field.sub(as_field(s.graph.package.source_limit), as_field(s.graph.total_bytes)))
        let opened = job.open(s.graph.package, found.index, capacity)
        s.graph.package.remaining = opened.remaining
        if (opened.error.code == syntax.ZERO) == false { s.graph = fail(s.graph, found.index, opened.error) return s }
        s.graph = register(s.graph, found.index, opened.content, item.name, false)
        if (s.graph.error.code == syntax.ZERO) == false { return s }
    }
    unit.offset = item.token.start
    unit.count = syntax.inc(unit.count)
    let occurrence = module_store.Use { target, start: item.start, path_start: item.path_start, end: item.end }
    unit.uses = noun.pair(module_store.use_record(occurrence), unit.uses)
    s.graph.modules = seq.set(s.graph.modules, s.current, module_store.pack(unit))
    s.graph.total_uses = syntax.inc(s.graph.total_uses)
    if saved == syntax.ZERO {
        s.parents = noun.pair(noun.atom(as_field(s.current)), s.parents)
        s.depth = syntax.inc(s.depth)
        s.current = target
    }
    s
}

#[pure]
fn chunk(input: Walk) -> Walk {
    let mut s = input
    for turn in 0..8 {
        s = step(s)
        if syntax.either(s.done, (s.graph.error.code == syntax.ZERO) == false) { return s }
    }
    s
}

// The admitted entry handle is reused. Unreachable source payloads stay opaque.
#[pure]
pub fn discover(view: job.View) -> Graph {
    discover_open(view, entry_header(view))
}

// Entry validation is shared by the direct no-import path and graph discovery.
#[pure]
pub fn entry_header(view: job.View) -> module_header.Header {
    let zero = syntax.ZERO
    let token = syntax.token(0, zero, zero, 0)
    if (view.error.code == zero) == false { return module_header.Header { token, error: view.error } }
    if view.sequence_limit == zero { return module_header.Header { token, error: syntax.error(7, zero, zero) } }
    let encoding = utf8.validate(view.source)
    if (encoding.code == zero) == false { return module_header.Header { token, error: encoding } }
    module_header.open(view.source, view.name, true)
}

#[pure]
pub fn discover_open(view: job.View, header: module_header.Header) -> Graph {
    let zero = syntax.ZERO
    let mut capacity = view.sequence_limit
    if syntax.TABLE_CAP < capacity { capacity = syntax.TABLE_CAP }
    let empty = tree.empty(tree.shape(seq.len(view.package.modules)).height)
    let graph = Graph { package: view.package, sources: bytes.table_empty(), names: bytes.table_empty(),
        modules: seq.empty(), indexes: empty, capacity, total_bytes: zero, total_uses: zero,
        error_index: view.index, error: view.error }
    if (view.error.code == zero) == false { return graph }
    if (header.error.code == zero) == false { return fail(graph, view.index, header.error) }
    let graph = register_open(graph, view.index, view.source, view.name, header)
    if (graph.error.code == zero) == false { return graph }
    let mut s = Walk { graph, current: zero, parents: noun.atom(0), depth: as_u32(1), done: false }
    // Each source is completed once and each use consumed once, both <=4096.
    for block in 0..1024 {
        s = chunk(s)
        if syntax.either(s.done, (s.graph.error.code == zero) == false) { return s.graph }
    }
    fail(s.graph, view.index, syntax.error(7, zero, zero))
}

sources.std.compiler.nox.module_header:
module std.compiler.nox.module_header

use vm.nox.noun
use std.nox.bytes
use std.compiler.nox.syntax
use std.compiler.nox.lexer
use std.compiler.nox.ast

const NAME_CAP: U32 = 255
const MODULE: Field = 120325194214501
const USE: Field = 7697253

pub struct Header { pub token: syntax.Token, pub error: syntax.Error }
pub struct Import {
    pub exists: Bool, pub name: bytes.Bytes, pub token: syntax.Token,
    pub start: U32, pub path_start: U32, pub end: U32, pub error: syntax.Error
}
struct Path {
    name: bytes.Bytes, token: syntax.Token, start: U32, end: U32, error: syntax.Error
}

#[pure]
fn wrong(token: syntax.Token) -> syntax.Error {
    if token.kind == as_u32(14) { return syntax.error(1, token.start, token.end) }
    syntax.error(2, token.start, token.end)
}

#[pure]
fn keyword(token: syntax.Token, value: Field) -> Bool {
    syntax.both(token.kind == as_u32(13), token.value == value)
}

#[pure]
fn append_word(source: bytes.Bytes, input: Path) -> Path {
    let mut s = input
    let word = s.token
    let mut pos = word.start
    for letter in 0..256 {
        if pos == word.end { return s }
        if bytes.len(s.name) == NAME_CAP {
            s.error = syntax.error(7, word.start, word.end)
            return s
        }
        s.name = bytes.push(s.name, bytes.get(source, pos), NAME_CAP)
        pos = syntax.inc(pos)
    }
    s.error = syntax.error(7, word.start, word.end)
    s
}

// Each normalized path fits the JOB1 logical-name cap. A token's complete
// original span survives even when spaces/comments separate its components.
#[pure]
#[requires((syntax.SOURCE_CAP < bytes.len(source)) == false)]
fn path(source: bytes.Bytes, first: syntax.Token, dotted: Bool) -> Path {
    let mut s = Path { name: bytes.empty(), token: first, start: first.start,
        end: first.end, error: syntax.error(0, first.start, first.end) }
    for part in 0..256 {
        if (s.token.kind == as_u32(1)) == false { s.error = wrong(s.token) return s }
        let word = s.token
        s = append_word(source, s)
        if (s.error.code == syntax.ZERO) == false { return s }
        s.end = word.end
        s.token = lexer.next(source, word.end)
        if s.token.kind == as_u32(14) { s.error = wrong(s.token) return s }
        if (s.token.kind == as_u32(41)) == false { return s }
        if dotted == false { s.error = wrong(s.token) return s }
        if bytes.len(s.name) == NAME_CAP {
            s.error = syntax.error(7, s.token.start, s.token.end)
            return s
        }
        s.name = bytes.push(s.name, as_u32(46), NAME_CAP)
        s.token = lexer.next(source, s.token.end)
    }
    s.error = syntax.error(7, s.token.start, s.token.end)
    s
}

// Expected names already come from the admitted package or a normalized use.
#[pure]
#[requires((syntax.SOURCE_CAP < bytes.len(source)) == false)]
#[requires((NAME_CAP < bytes.len(expected)) == false)]
pub fn open(source: bytes.Bytes, expected: bytes.Bytes, is_entry: Bool) -> Header {
    let first = lexer.next(source, syntax.ZERO)
    let is_program = first.kind == as_u32(10)
    let is_module = keyword(first, MODULE)
    if syntax.either(is_program, is_module) == false {
        return Header { token: first, error: ast.failed(first, 2) }
    }
    if (is_program == is_entry) == false {
        return Header { token: first, error: syntax.error(3, first.start, first.end) }
    }
    let name = path(source, lexer.next(source, first.end), is_entry == false)
    if (name.error.code == syntax.ZERO) == false { return Header { token: name.token, error: name.error } }
    if noun.eq(bytes.to_noun(name.name), bytes.to_noun(expected)) == false {
        return Header { token: name.token, error: syntax.error(3, name.start, name.end) }
    }
    Header { token: name.token, error: syntax.error(0, name.start, name.end) }
}

// The caller retains each occurrence in order and advances with result.token.
#[pure]
#[requires((syntax.SOURCE_CAP < bytes.len(source)) == false)]
pub fn next_use(source: bytes.Bytes, token: syntax.Token) -> Import {
    if keyword(token, USE) == false {
        let mut error = syntax.error(0, token.start, token.end)
        if token.kind == as_u32(14) { error = wrong(token) }
        return Import { exists: false, name: bytes.empty(), token,
            start: token.start, path_start: token.start, end: token.end,
            error }
    }
    let name = path(source, lexer.next(source, token.end), true)
    Import { exists: true, name: name.name, token: name.token, start: token.start,
        path_start: name.start, end: name.end, error: name.error }
}

sources.std.compiler.nox.module_order:
module std.compiler.nox.module_order

use vm.nox.noun
use std.nox.seq
use std.nox.tree
use std.compiler.nox.syntax
use std.compiler.nox.module_store
use std.compiler.nox.module_graph

const HALF: Field = 9223372034707292161
pub struct Ordered { pub modules: seq.Seq, pub error_index: U32, pub error: syntax.Error }
struct Walk {
    pending: Noun, colors: Noun, frames: Noun, depth: U32, result: Ordered, done: Bool
}

// A shared zero subtree skips all unused package slots in one comparison.
#[pure]
#[requires((as_u32(65536) < length) == false)]
fn first(root: Noun, length: U32) -> U32 {
    let shape = tree.shape(length)
    let mut capacity = shape.capacity
    let mut padding = tree.empty(shape.height)
    if noun.eq(root, padding) { return length }
    let mut cursor = root
    let mut offset: Field = 0
    for level in 0..17 {
        if capacity == 1 { return as_u32(offset) }
        capacity = capacity * HALF
        padding = noun.head(padding)
        let left = noun.head(cursor)
        if noun.eq(left, padding) { cursor = noun.tail(cursor) offset = offset + capacity }
        else { cursor = left }
    }
    length
}

#[pure]
fn push(graph: module_graph.Graph, input: Walk, id: U32) -> Walk {
    let mut s = input
    let unit = module_store.read(graph.modules, id)
    if s.depth == graph.capacity {
        s.result.error_index = unit.index
        s.result.error = syntax.error(7, unit.offset, unit.offset)
        return s
    }
    s.colors = tree.set(s.colors, seq.len(graph.modules), id, noun.atom(1))
    s.frames = noun.pair(noun.pair(noun.atom(as_field(id)), unit.uses), s.frames)
    s.depth = syntax.inc(s.depth)
    s
}

#[pure]
fn step(graph: module_graph.Graph, input: Walk) -> Walk {
    let mut s = input
    if noun.eq(s.frames, noun.atom(0)) {
        if seq.len(s.result.modules) == seq.len(graph.modules) { s.done = true return s }
        let index = first(s.pending, seq.len(graph.package.modules))
        assert(index < seq.len(graph.package.modules))
        let saved = as_u32(noun.as_field(tree.get(s.pending, seq.len(graph.package.modules), index)))
        return push(graph, s, syntax.dec(saved))
    }
    let frame = noun.head(s.frames)
    let id = as_u32(noun.as_field(noun.head(frame)))
    let uses = noun.tail(frame)
    if noun.eq(uses, noun.atom(0)) {
        let unit = module_store.read(graph.modules, id)
        s.colors = tree.set(s.colors, seq.len(graph.modules), id, noun.atom(2))
        s.pending = tree.set(s.pending, seq.len(graph.package.modules), unit.index, noun.atom(0))
        s.result.modules = seq.push(s.result.modules, noun.atom(as_field(id)), graph.capacity)
        s.frames = noun.tail(s.frames)
        s.depth = syntax.dec(s.depth)
        return s
    }
    let item = module_store.use_read(noun.head(uses))
    s.frames = noun.pair(noun.pair(noun.atom(as_field(id)), noun.tail(uses)), noun.tail(s.frames))
    let color = noun.as_field(tree.get(s.colors, seq.len(graph.modules), item.target))
    if color == 1 {
        s.result.error_index = module_store.read(graph.modules, id).index
        s.result.error = syntax.error(4, item.start, item.end)
        return s
    }
    if color == 0 { return push(graph, s, item.target) }
    s
}

#[pure]
fn chunk(graph: module_graph.Graph, input: Walk) -> Walk {
    let mut s = input
    for turn in 0..16 {
        s = step(graph, s)
        if syntax.either(s.done, (s.result.error.code == syntax.ZERO) == false) { return s }
    }
    s
}

// Lexical roots, source-order dependencies, dependency-first output: seed DFS.
#[pure]
pub fn sort(graph: module_graph.Graph) -> Ordered {
    let zero = syntax.ZERO
    let result = Ordered { modules: seq.empty(), error_index: graph.error_index, error: graph.error }
    if (graph.error.code == zero) == false { return result }
    let mut s = Walk { pending: graph.indexes, colors: tree.empty(tree.shape(seq.len(graph.modules)).height),
        frames: noun.atom(0), depth: zero, result, done: false }
    // At most4096 root starts +4096 uses +4096 completions, then one done check.
    for block in 0..1024 {
        s = chunk(graph, s)
        if syntax.either(s.done, (s.result.error.code == zero) == false) { return s.result }
    }
    s.result.error = syntax.error(7, zero, zero)
    s.result
}

sources.std.compiler.nox.module_store:
module std.compiler.nox.module_store

use vm.nox.noun
use std.nox.seq
use std.compiler.nox.syntax

// Compiler-owned records only. Uses reverse during discovery and become source
// ordered on completion. Each occurrence is [target [use_start [path_start end]]].
pub struct Module {
    pub index: U32, pub offset: U32, pub status: U32, pub count: U32, pub uses: Noun
}
pub struct Use { pub target: U32, pub start: U32, pub path_start: U32, pub end: U32 }

#[pure]
pub fn pack(value: Module) -> Noun {
    noun.pair(noun.atom(as_field(value.index)), noun.pair(noun.atom(as_field(value.offset)),
        noun.pair(noun.atom(as_field(value.status)), noun.pair(noun.atom(as_field(value.count)), value.uses))))
}

#[pure]
#[requires(id < seq.len(modules))]
pub fn read(modules: seq.Seq, id: U32) -> Module {
    let value = seq.get(modules, id)
    let offset = noun.tail(value)
    let status = noun.tail(offset)
    let count = noun.tail(status)
    Module { index: as_u32(noun.as_field(noun.head(value))),
        offset: as_u32(noun.as_field(noun.head(offset))), status: as_u32(noun.as_field(noun.head(status))),
        count: as_u32(noun.as_field(noun.head(count))), uses: noun.tail(count) }
}

#[pure]
pub fn use_record(value: Use) -> Noun {
    noun.pair(noun.atom(as_field(value.target)), noun.pair(noun.atom(as_field(value.start)),
        noun.pair(noun.atom(as_field(value.path_start)), noun.atom(as_field(value.end)))))
}

#[pure]
pub fn use_read(value: Noun) -> Use {
    let rest = noun.tail(value)
    let path = noun.tail(rest)
    Use { target: as_u32(noun.as_field(noun.head(value))), start: as_u32(noun.as_field(noun.head(rest))),
        path_start: as_u32(noun.as_field(noun.head(path))), end: as_u32(noun.as_field(noun.tail(path))) }
}

#[pure]
fn reverse_chunk(input: Noun, output: Noun) -> (Noun, Noun) {
    let mut rest = input
    let mut ordered = output
    for step in 0..64 {
        if noun.eq(rest, noun.atom(0)) { return (rest, ordered) }
        ordered = noun.pair(noun.head(rest), ordered)
        rest = noun.tail(rest)
    }
    (rest, ordered)
}

#[pure]
#[requires((syntax.TABLE_CAP < value.count) == false)]
pub fn finish(value: Module) -> Module {
    let mut rest = value.uses
    let mut ordered = noun.atom(0)
    for chunk in 0..64 {
        (rest, ordered) = reverse_chunk(rest, ordered)
        if noun.eq(rest, noun.atom(0)) {
            return Module { index: value.index, offset: value.offset, status: as_u32(2),
                count: value.count, uses: ordered }
        }
    }
    assert_eq(0, 1)
    value
}

sources.std.compiler.nox.nominal:
module std.compiler.nox.nominal

use vm.nox.noun
use vm.core.convert
use std.nox.bytes
use std.nox.seq
use std.compiler.nox.syntax
use std.compiler.nox.types

pub const MAX_FIELDS: U32 = 32
pub struct Built { pub ty: Noun, pub status: U32, pub field: U32 }
pub struct Selected { pub ty: Noun, pub index: U32, pub exists: Bool, pub visible: Bool }

// Names and child types are compiler-owned values. Source spelling is checked
// by the frontend; this layer owns canonical layout, identity and visibility.
#[pure]
pub fn field(name: bytes.Bytes, ty: Noun, public: Bool) -> Noun {
    let mut flag: Field = 0
    if public { flag = 1 }
    noun.pair(bytes.to_noun(name), noun.pair(ty, noun.atom(flag)))
}

#[pure]
fn failure(status: Field, index: U32) -> Built {
    Built { ty: noun.atom(types.INVALID), status: as_u32(status), field: index }
}

#[pure]
pub fn field_name(member: Noun) -> Noun { noun.head(member) }

#[pure]
pub fn field_type(member: Noun) -> Noun { noun.head(noun.tail(member)) }

#[pure]
pub fn field_public(member: Noun) -> Bool { noun.as_field(noun.tail(noun.tail(member))) == 1 }

// At most32 fields: compare complete names without a mutable name interner.
#[pure]
fn repeated(fields: seq.Seq, index: U32, name: Noun) -> Bool {
    for earlier in 0..32 {
        if earlier == index { return false }
        if noun.eq(field_name(seq.get(fields, earlier)), name) { return true }
    }
    false
}

#[pure]
#[requires((syntax.TABLE_CAP < node_cap) == false)]
#[requires((syntax.STACK_CAP < depth_cap) == false)]
pub fn build(owner: bytes.Bytes, name: bytes.Bytes, fields: seq.Seq, node_cap: U32, depth_cap: U32) -> Built {
    let zero = syntax.ZERO
    if syntax.either(bytes.len(owner) == zero, bytes.len(name) == zero) { return failure(5, zero) }
    let count = seq.len(fields)
    if syntax.either((MAX_FIELDS < count), node_cap == zero) { return failure(7, zero) }
    let mut nodes: Field = 1
    let mut depth = zero
    let mut contains: Field = 0
    for index in 0..32 {
        if index < count {
            let member = seq.get(fields, index)
            let member_name = field_name(member)
            if noun.eq(member_name, bytes.to_noun(bytes.empty())) { return failure(5, index) }
            if repeated(fields, index, member_name) { return failure(5, index) }
            let child = types.info(field_type(member))
            if child.valid == false { return failure(5, index) }
            nodes = nodes + as_field(child.nodes)
            if node_cap < as_u32(nodes) { return failure(7, index) }
            if depth < child.depth { depth = child.depth }
            if child.contains_noun { contains = 1 }
        }
    }
    depth = syntax.inc(depth)
    if depth_cap < depth { return failure(7, zero) }
    let identity = noun.pair(bytes.to_noun(owner), noun.pair(bytes.to_noun(name), seq.to_noun(fields)))
    let metadata = noun.pair(noun.atom(as_field(depth)), noun.pair(noun.atom(nodes), noun.atom(contains)))
    Built { ty: noun.pair(noun.atom(types.NOMINAL), noun.pair(identity, metadata)), status: zero, field: zero }
}

// These projections require a successfully constructed nominal descriptor.
#[pure]
pub fn owner(ty: Noun) -> Noun { noun.head(noun.head(noun.tail(ty))) }

#[pure]
pub fn name(ty: Noun) -> Noun { noun.head(noun.tail(noun.head(noun.tail(ty)))) }

#[pure]
pub fn fields(ty: Noun) -> seq.Seq {
    seq.from_noun(noun.tail(noun.tail(noun.head(noun.tail(ty)))), MAX_FIELDS, as_u32(63))
}

#[pure]
pub fn lookup(ty: Noun, current_owner: bytes.Bytes, member_name: bytes.Bytes) -> Selected {
    let absent = Selected { ty: noun.atom(types.INVALID), index: syntax.ZERO, exists: false, visible: false }
    let description = types.info(ty)
    if syntax.either(description.valid == false, description.depth == syntax.ZERO) { return absent }
    if (noun.as_field(noun.head(ty)) == types.NOMINAL) == false { return absent }
    let members = fields(ty)
    let wanted = bytes.to_noun(member_name)
    for index in 0..32 {
        if index == seq.len(members) { return absent }
        let member = seq.get(members, index)
        if noun.eq(field_name(member), wanted) {
            let visible = syntax.either(field_public(member), noun.eq(owner(ty), bytes.to_noun(current_owner)))
            return Selected { ty: field_type(member), index, exists: true, visible }
        }
    }
    absent
}

sources.std.compiler.nox.package_compile:
module std.compiler.nox.package_compile

use vm.nox.noun
use std.nox.bytes
use std.nox.seq
use std.compiler.nox.syntax
use std.compiler.nox.job
use std.compiler.nox.module_graph
use std.compiler.nox.module_order
use std.compiler.nox.module_store
use std.compiler.nox.constant_imports
use std.compiler.nox.parser
use std.compiler.nox.module_functions
use std.compiler.nox.module_function_order
use std.compiler.nox.function_plan
use std.compiler.nox.function_gen
use std.compiler.nox.signatures
use std.compiler.nox.intrinsic_plan

pub struct Compiled { pub formula: Noun, pub index: U32, pub error: syntax.Error }

#[pure]
fn failed(index: U32, error: syntax.Error) -> Compiled {
    Compiled { formula: noun.atom(0), index, error }
}

// JOB1 admission fixes strict ASCII module-path order. Discovery retains each
// package index, so these ranks compare owners without rereading source bytes.
#[pure]
fn owner_ranks(modules: seq.Seq, cap: U32) -> seq.Seq {
    let mut ranks = seq.empty()
    for owner in 0..4096 {
        if owner == seq.len(modules) { return ranks }
        let index = module_store.read(modules, owner).index
        ranks = seq.push(ranks, noun.atom(as_field(index)), cap)
    }
    ranks
}

#[pure]
pub fn compile(view: job.View) -> Compiled {
    let header = module_graph.entry_header(view)
    if (header.error.code == syntax.ZERO) == false { return failed(view.index, header.error) }
    // No graph storage is needed when the checked header has no direct uses.
    // A one-module package can still contain a self-use and must discover it.
    if syntax.both(header.token.kind == as_u32(13), header.token.value == 7697253) == false {
        let compiled = parser.compile_profile(view.source, view.name, header.token.start,
            constant_imports.empty(), view.sequence_limit, view.depth_limit, view.profile)
        return Compiled { formula: compiled.formula, index: view.index, error: compiled.error }
    }
    let graph = module_graph.discover_open(view, header)
    if (graph.error.code == syntax.ZERO) == false { return failed(graph.error_index, graph.error) }
    let ordered = module_order.sort(graph)
    if (ordered.error.code == syntax.ZERO) == false { return failed(ordered.error_index, ordered.error) }
    let mut bank = module_functions.empty(seq.len(graph.modules))
    for position in 0..4096 {
        if position == seq.len(ordered.modules) {
            if bank.entry == signatures.NONE { return failed(view.index, syntax.error(3, syntax.ZERO, syntax.ZERO)) }
            let sorted = module_function_order.sort_ranked(bank.functions, bank.owners,
                graph.names, graph.sources, bank.roots, owner_ranks(graph.modules, graph.capacity), graph.capacity)
            let plan = intrinsic_plan.check(function_plan.ordered(bank.functions, bank.bodies, sorted, bank.entry, graph.capacity), bank.bodies, bank.intrinsics, graph.capacity)
            if (plan.error.code == syntax.ZERO) == false {
                let mut index = view.index
                if plan.error_function < seq.len(bank.owners) {
                    let owner = as_u32(noun.as_field(seq.get(bank.owners, plan.error_function)))
                    index = module_store.read(graph.modules, owner).index
                }
                return failed(index, plan.error)
            }
            let compiled = function_gen.generate(bank.bodies, plan, bank.entry,
                graph.capacity, view.depth_limit, bank.structured)
            return Compiled { formula: compiled.formula, index: view.index, error: compiled.error }
        }
        let owner = as_u32(noun.as_field(seq.get(ordered.modules, position)))
        bank = module_functions.check_profile(graph, owner, view.index, bank, view.profile)
        if (bank.error.code == syntax.ZERO) == false {
            return failed(module_store.read(graph.modules, owner).index, bank.error)
        }
    }
    failed(view.index, syntax.error(7, syntax.ZERO, syntax.ZERO))
}

sources.std.compiler.nox.parser:
module std.compiler.nox.parser

use vm.nox.noun
use vm.core.convert
use std.nox.bytes
use std.compiler.nox.syntax
use std.compiler.nox.ascii
use std.compiler.nox.lexer
use std.compiler.nox.ast
use std.compiler.nox.codegen
use std.compiler.nox.headers
use std.compiler.nox.check_functions
use std.compiler.nox.function_plan
use std.compiler.nox.function_gen
use std.compiler.nox.constant_imports
use std.compiler.nox.function_imports
use std.compiler.nox.intrinsic_plan
use std.nox.seq

#[pure]
#[requires((syntax.SOURCE_CAP < bytes.len(source)) == false)]
pub fn compile(source: bytes.Bytes, name: bytes.Bytes, cap: U32, depth_cap: U32) -> codegen.Compiled {
    let expected = [10,1]
    let mut pos = syntax.ZERO
    for i in 0..2 {
        let token = lexer.next(source, pos)
        if (as_field(token.kind) == expected[i]) == false {
            return codegen.Compiled { formula: noun.atom(0), error: ast.failed(token, 2) }
        }
        if syntax.both(i == as_u32(1), ascii.same(source, token.start, token.end, name) == false) {
            return codegen.Compiled { formula: noun.atom(0), error: syntax.error(3, token.start, token.end) }
        }
        pos = token.end
    }
    compile_at(source, name, pos, constant_imports.empty(), cap, depth_cap)
}

#[pure]
#[requires((syntax.SOURCE_CAP < bytes.len(source)) == false)]
pub fn compile_at(source: bytes.Bytes, name: bytes.Bytes, start: U32, imports: constant_imports.View, cap: U32, depth_cap: U32) -> codegen.Compiled {
    compile_profile(source, name, start, imports, cap, depth_cap, 0)
}

#[pure]
#[requires((syntax.SOURCE_CAP < bytes.len(source)) == false)]
#[requires(syntax.either(profile == 0, profile == 1))]
pub fn compile_profile(source: bytes.Bytes, name: bytes.Bytes, start: U32, imports: constant_imports.View, cap: U32, depth_cap: U32, profile: Field) -> codegen.Compiled {
    let mut capacity = cap
    if syntax.TABLE_CAP < capacity { capacity = syntax.TABLE_CAP }
    let parsed = headers.require_profile(headers.parse_imports(source, start, name, imports, capacity), profile)
    if (parsed.error.code == syntax.ZERO) == false { return codegen.Compiled { formula: noun.atom(0), error: parsed.error } }
    let checked = check_functions.check_range_with_intrinsics(source, parsed.functions, parsed.params, parsed.pure_functions, parsed.types, parsed.constants, capacity, syntax.ZERO, seq.len(parsed.functions), function_imports.empty(), seq.empty(), parsed.intrinsics)
    if (checked.error.code == syntax.ZERO) == false { return codegen.Compiled { formula: noun.atom(0), error: checked.error } }
    let plan = intrinsic_plan.check(function_plan.plan(source, parsed.functions, checked.bodies, parsed.entry, capacity), checked.bodies, parsed.intrinsics, capacity)
    if (plan.error.code == syntax.ZERO) == false { return codegen.Compiled { formula: noun.atom(0), error: plan.error } }
    function_gen.generate(checked.bodies, plan, parsed.entry, capacity, depth_cap, parsed.structured)
}

