module std.compiler.nox.qualified_call

use std.nox.bytes
use std.compiler.nox.syntax
use std.compiler.nox.lexer
use std.compiler.nox.ascii
use std.compiler.nox.record_parse
use vm.nox.noun

// A lexical local can share an imported module root. Detect a call before
// choosing field projection. Constructors share this independent namespace, without building a capped module-name buffer.
// Non-call paths keep their original field parser and source-length allowance.
#[pure]
#[requires(dot.kind == as_u32(41))]
#[requires((syntax.SOURCE_CAP < bytes.len(source)) == false)]
pub fn follows(source: bytes.Bytes, dot: syntax.Token, before_block: Bool, frames: Noun) -> Bool {
    let mut next = dot
    for part in 0..65536 {
        let member = lexer.next(source, next.end)
        if (member.kind == as_u32(1)) == false { return false }
        next = lexer.next(source, member.end)
        if next.kind == as_u32(5) { return ascii.same_line(source, member.end, next.start) }
        if next.kind == as_u32(7) { return record_parse.starts(source, member, next, before_block, frames) }
        if (next.kind == as_u32(41)) == false { return false }
    }
    false
}

sources.std.compiler.nox.qualified_name:
module std.compiler.nox.qualified_name

use std.nox.bytes
use vm.nox.noun
use vm.core.field
use std.compiler.nox.syntax
use std.compiler.nox.lexer

const PREFIX_CAP: U32 = 255

pub struct Name {
    pub prefix: bytes.Bytes, pub member: syntax.Token, pub token: syntax.Token,
    pub start: U32, pub end: U32, pub error: syntax.Error
}

// Full owner equality is canonical. Otherwise only one final component may
// match: a dot inside the candidate suffix rejects a partial qualified path.
#[pure]
#[requires((PREFIX_CAP < bytes.len(prefix)) == false)]
#[requires((PREFIX_CAP < bytes.len(owner)) == false)]
pub fn matches_owner(prefix: bytes.Bytes, owner: bytes.Bytes) -> Bool {
    if noun.eq(bytes.to_noun(prefix), bytes.to_noun(owner)) { return true }
    let length = bytes.len(prefix)
    if (length < bytes.len(owner)) == false { return false }
    let start = as_u32(field.sub(as_field(bytes.len(owner)), as_field(length)))
    if (bytes.get(owner, syntax.dec(start)) == as_u32(46)) == false { return false }
    let mut pos = start
    for index in 0..255 {
        if index == length { return true }
        let value = bytes.get(owner, pos)
        if value == as_u32(46) { return false }
        if (value == bytes.get(prefix, index)) == false { return false }
        pos = syntax.inc(pos)
    }
    true
}

#[pure]
fn wrong(token: syntax.Token) -> syntax.Error {
    if token.kind == as_u32(14) { return syntax.error(1, token.start, token.end) }
    syntax.error(2, token.start, token.end)
}

// Only words followed by a dot belong to the bounded module prefix. The final
// member stays a source token, so long member identifiers are never truncated.
#[pure]
fn append(source: bytes.Bytes, input: Name) -> Name {
    let mut s = input
    if (bytes.len(s.prefix) == syntax.ZERO) == false {
        if bytes.len(s.prefix) == PREFIX_CAP {
            s.error = syntax.error(7, s.member.start, s.member.end) return s
        }
        s.prefix = bytes.push(s.prefix, as_u32(46), PREFIX_CAP)
    }
    let mut pos = s.member.start
    for letter in 0..256 {
        if pos == s.member.end { return s }
        if bytes.len(s.prefix) == PREFIX_CAP {
            s.error = syntax.error(7, s.member.start, s.member.end) return s
        }
        s.prefix = bytes.push(s.prefix, bytes.get(source, pos), PREFIX_CAP)
        pos = syntax.inc(pos)
    }
    s.error = syntax.error(7, s.member.start, s.member.end)
    s
}

#[pure]
#[requires((syntax.SOURCE_CAP < bytes.len(source)) == false)]
pub fn parse(source: bytes.Bytes, first: syntax.Token) -> Name {
    let mut s = Name { prefix: bytes.empty(), member: first, token: first,
        start: first.start, end: first.end, error: syntax.error(0, first.start, first.end) }
    // A prefix admits at most 128 identifier components; the source ceiling is
    // separate. The extra final component is an arbitrarily long member token.
    for part in 0..256 {
        if (s.member.kind == as_u32(1)) == false { s.error = wrong(s.member) return s }
        s.end = s.member.end
        s.token = lexer.next(source, s.member.end)
        if s.token.kind == as_u32(14) { s.error = wrong(s.token) return s }
        if (s.token.kind == as_u32(41)) == false { return s }
        s = append(source, s)
        if (s.error.code == syntax.ZERO) == false { return s }
        s.member = lexer.next(source, s.token.end)
    }
    s.error = syntax.error(7, s.member.start, s.member.end)
    s
}

sources.std.compiler.nox.record_assign:
module std.compiler.nox.record_assign

use vm.nox.noun
use vm.core.convert
use std.nox.bytes
use std.nox.seq
use std.compiler.nox.syntax
use std.compiler.nox.ast
use std.compiler.nox.lexer
use std.compiler.nox.expression
use std.compiler.nox.expression_state
use std.compiler.nox.body_state
use std.compiler.nox.blocks

struct Root { node: Noun, error: syntax.Error }

// Every accepted projection is a static field selection. Its stable LOCAL
// slot identifies the binding even when another name shadows an older slot.
#[pure]
fn root(nodes: seq.Seq, bindings: seq.Seq, lhs: U32) -> Root {
    let target = seq.get(nodes, lhs)
    let mut current = target
    for step in 0..65 {
        if ast.kind(current) == ast.LOCAL {
            let binding = seq.get(bindings, as_u32(ast.left(current)))
            if (noun.as_field(noun.head(noun.tail(binding))) == 1) == false {
                return Root { node: current, error: ast.issue(5, target) }
            }
            return Root { node: current, error: syntax.error(0, syntax.ZERO, syntax.ZERO) }
        }
        if (ast.kind(current) == ast.PROJECT) == false { return Root { node: current, error: ast.issue(5, target) } }
        current = seq.get(nodes, as_u32(ast.left(current)))
    }
    Root { node: current, error: ast.issue(7, target) }
}

#[pure]
#[requires(lhs < seq.len(input.nodes))]
#[requires((syntax.SOURCE_CAP < bytes.len(source)) == false)]
pub fn assign(source: bytes.Bytes, input: body_state.State, lhs: U32, cap: U32) -> body_state.State {
    let mut s = input
    let target = seq.get(s.nodes, lhs)
    let selected = root(s.nodes, s.bindings, lhs)
    s.error = selected.error
    if (s.error.code == syntax.ZERO) == false { return s }
    if seq.len(s.statements) == cap { s.error = ast.issue(7, target) return s }
    let rhs = expression.parse(source, lexer.next(source, s.token.end), expression_state.context(s.bindings, s.visible, s.scope), s.nodes, s.arguments, s.edges, cap, false)
    s.error = rhs.error
    if (s.error.code == syntax.ZERO) == false { return s }
    let value = seq.get(rhs.nodes, rhs.value)
    if noun.eq(ast.ty(value), ast.ty(target)) == false { s.error = ast.issue(5, value) return s }
    if seq.len(rhs.nodes) == cap { s.error = ast.issue(7, value) return s }
    let edit = seq.len(rhs.nodes)
    s.nodes = seq.push(rhs.nodes, ast.typed(ast.RECORD_EDIT, as_field(lhs), as_field(rhs.value), ast.ty(selected.node), ast.start(target), ast.end(value)), cap)
    s.arguments = rhs.arguments
    s.edges = rhs.edges
    if rhs.needs_get { s.needs_get = true }
    s.token = rhs.token
    body_state.append(s, blocks.statement(blocks.WRITE, as_u32(ast.left(selected.node)), edit, syntax.ZERO), cap)
}

sources.std.compiler.nox.record_edit_gen:
module std.compiler.nox.record_edit_gen

use vm.core.convert
use vm.core.field
use std.nox.seq
use std.compiler.nox.ast
use std.compiler.nox.formula

const HALF: Field = 9223372034707292161

// Rebuild one record using relative axes. The unchanged suffix stays whole;
// each preceding field is read from the original parent, preserving siblings.
#[pure]
fn rebuild(parent: formula.Value, selected: Field, replacement: formula.Value) -> formula.Value {
    // Every sibling has the same depth: compose(parent, axis). Compute it
    // once; each additional cons then adds exactly two levels to the result.
    let sibling_depth = as_u32(as_field(formula.maximum(parent.depth, as_u32(2))) + 2)
    let suffix = formula.compose(parent.formula, formula.axis(selected + 1))
    let mut result = formula.Value {
        formula: formula.cons(replacement.formula, suffix),
        depth: as_u32(as_field(formula.maximum(replacement.depth, sibling_depth)) + 2)
    }
    let mut axis = selected
    for step in 0..32 {
        if axis == 2 { return result }
        axis = field.sub(axis, 2) * HALF
        result.formula = formula.cons(formula.compose(parent.formula, formula.axis(axis)), result.formula)
        result.depth = as_u32(as_field(result.depth) + 2)
    }
    result
}

// The checker admits only PROJECT chains ending at a mutable LOCAL. Complete
// axes never concatenate: each field stays below 2^33, at any nesting depth.
// Parent formulas only read the old frame; the RHS occurs once in the result.
#[pure]
#[requires(lhs < seq.len(nodes))]
#[requires(rhs < seq.len(values))]
pub fn generate(nodes: seq.Seq, values: seq.Seq, lhs: U32, rhs: U32) -> formula.Value {
    let mut current = seq.get(nodes, lhs)
    let mut result = formula.value(values, rhs)
    for step in 0..65 {
        if ast.kind(current) == ast.LOCAL { return result }
        let parent = as_u32(ast.left(current))
        result = rebuild(formula.value(values, parent), ast.right(current), result)
        current = seq.get(nodes, parent)
    }
    result
}

sources.std.compiler.nox.record_frames:
module std.compiler.nox.record_frames

use vm.nox.noun
use vm.core.convert
use std.compiler.nox.signatures
use std.compiler.nox.nominal

// Owned continuation: fields are an immutable declaration-order list; values
// are a canonical tree with arity leaves. Zero is empty, AST IDs store id+1.
pub struct Frame { pub ty: Noun, pub fields: Noun, pub values: Noun, pub arity: U32,
    pub start: U32, pub base: U32, pub count: U32, pub pending: U32, pub expected: Noun }
pub struct Selected { pub ty: Noun, pub index: U32 }

#[pure]
pub fn find(f: Frame, wanted: Noun) -> Selected {
    let mut cursor = f.fields
    for index in 0..32 {
        if index == f.arity { return Selected { ty: noun.atom(0), index: signatures.NONE } }
        let member = noun.head(cursor)
        if noun.eq(nominal.field_name(member), wanted) { return Selected { ty: nominal.field_type(member), index } }
        cursor = noun.tail(cursor)
    }
    Selected { ty: noun.atom(0), index: signatures.NONE }
}

#[pure]
pub fn pack(f: Frame) -> Noun {
    let position = noun.pair(noun.atom(as_field(f.start)), noun.atom(as_field(f.base)))
    let progress = noun.pair(noun.atom(as_field(f.count)), noun.atom(as_field(f.pending)))
    let data = noun.pair(f.ty, noun.pair(f.fields, f.values))
    let layout = noun.pair(noun.atom(as_field(f.arity)), f.expected)
    noun.pair(data, noun.pair(position, noun.pair(progress, layout)))
}

// Only pack/enter produce these frames. Public Seq admission is performed once
// before constructing the owned field list, never bypassed by a forged handle.
#[pure]
pub fn read(value: Noun) -> Frame {
    let data = noun.head(value)
    let meta = noun.tail(value)
    let position = noun.head(meta)
    let progress = noun.head(noun.tail(meta))
    let layout = noun.tail(noun.tail(meta))
    Frame { ty: noun.head(data), fields: noun.head(noun.tail(data)), values: noun.tail(noun.tail(data)),
        arity: as_u32(noun.as_field(noun.head(layout))), expected: noun.tail(layout),
        start: as_u32(noun.as_field(noun.head(position))), base: as_u32(noun.as_field(noun.tail(position))),
        count: as_u32(noun.as_field(noun.head(progress))), pending: as_u32(noun.as_field(noun.tail(progress))) }
}

sources.std.compiler.nox.record_parse:
module std.compiler.nox.record_parse

use vm.nox.noun
use vm.core.convert
use std.nox.bytes
use std.nox.seq
use std.nox.tree
use vm.core.field
use std.compiler.nox.syntax
use std.compiler.nox.ast
use std.compiler.nox.lexer
use std.compiler.nox.signatures
use std.compiler.nox.nominal
use std.compiler.nox.type_registry
use std.compiler.nox.record_frames
use std.compiler.nox.expression_state
use std.compiler.nox.qualified_name

// A constructor starts only with an uppercase type name and named-field syntax.
// A nested delimiter owns its braces even in an outer before-block expression.
#[pure]
pub fn starts(source: bytes.Bytes, name: syntax.Token, opening: syntax.Token, before_block: Bool, frames: Noun) -> Bool {
    if syntax.both(before_block, noun.eq(frames, noun.atom(0))) { return false }
    let first = bytes.get(source, name.start)
    if syntax.either(first < as_u32(65), (first < as_u32(91)) == false) { return false }
    let next = lexer.next(source, opening.end)
    if next.kind == as_u32(8) { return true }
    if (next.kind == as_u32(1)) == false { return false }
    let following = lexer.next(source, next.end)
    syntax.either(following.kind == as_u32(17), syntax.either(following.kind == as_u32(26), following.kind == as_u32(8)))
}

// This phase owns labels, colons and shorthand. Ordinary expression parsing
// owns the selected initializer, including every nested delimiter.
#[pure]
fn member(source: bytes.Bytes, input: expression_state.State, input_frame: record_frames.Frame) -> expression_state.State {
    let mut s = input
    let mut f = input_frame
    if s.token.kind == as_u32(8) {
        f.pending = signatures.NONE
        s.frames = noun.pair(record_frames.pack(f), noun.tail(s.frames))
        return s
    }
    if (s.token.kind == as_u32(1)) == false { s.error = ast.failed(s.token, 2) return s }
    let selected = record_frames.find(f, bytes.to_noun(type_registry.name(source, s.token)))
    if selected.index == signatures.NONE { s.error = ast.failed(s.token, 5) return s }
    if noun.eq(tree.get(f.values, f.arity, selected.index), noun.atom(0)) == false { s.error = ast.failed(s.token, 5) return s }
    f.pending = selected.index
    f.expected = selected.ty
    let following = lexer.next(source, s.token.end)
    if following.kind == as_u32(17) { s.token = lexer.next(source, following.end) }
    else if syntax.either(following.kind == as_u32(26), following.kind == as_u32(8)) == false {
        s.error = ast.failed(following, 2) return s
    }
    s.frames = noun.pair(record_frames.pack(f), noun.tail(s.frames))
    s
}

#[pure]
pub fn enter(source: bytes.Bytes, opening: syntax.Token, input: expression_state.State) -> expression_state.State {
    let mut s = input
    let found = type_registry.lookup(s.context.scope.types, type_registry.name(source, s.token))
    if found.exists == false { s.error = ast.failed(s.token, 5) return s }
    enter_type(source, opening, s, found.ty)
}

#[pure]
pub fn enter_qualified(source: bytes.Bytes, query: qualified_name.Name, input: expression_state.State) -> expression_state.State {
    let mut s = input
    s.token = syntax.token(1, query.start, query.end, 0)
    let found = type_registry.imported(source, query, s.context.scope.types)
    if found.exists == false { s.error = ast.failed(s.token, 5) return s }
    enter_type(source, query.token, s, found.ty)
}

// Preserve the descriptor's defining owner and the full caller path span.
#[pure]
fn enter_type(source: bytes.Bytes, opening: syntax.Token, input: expression_state.State, ty: Noun) -> expression_state.State {
    let mut s = input
    if s.ops == s.capacity { s.error = ast.failed(opening, 7) return s }
    let fields = nominal.fields(ty)
    let arity = seq.len(fields)
    let mut members = noun.atom(0)
    let values = tree.empty(tree.shape(arity).height)
    for index in 0..32 {
        if index < arity {
            let position = as_u32(field.sub(as_field(arity), as_field(index) + 1))
            let field = seq.get(fields, position)
            if syntax.both(nominal.field_public(field) == false, noun.eq(nominal.owner(ty), bytes.to_noun(s.context.scope.types.owner)) == false) {
                s.error = ast.failed(s.token, 5) return s
            }
            members = noun.pair(field, members)
        }
    }
    let f = record_frames.Frame { ty, fields: members, values, arity, expected: noun.atom(0), start: s.token.start, base: s.vals, count: syntax.ZERO, pending: signatures.NONE }
    s.operators = ast.store(s.operators, s.ops, noun.atom(as_field(expression_state.RECORD_MARKER)), s.capacity)
    s.ops = syntax.inc(s.ops)
    s.frames = noun.pair(noun.atom(0), s.frames)
    s.token = lexer.next(source, opening.end)
    member(source, s, f)
}

#[pure]
pub fn finish(source: bytes.Bytes, input: expression_state.State, closing: Bool) -> expression_state.State {
    let mut s = input
    let mut f = record_frames.read(noun.head(s.frames))
    if s.operand == false {
        if (s.vals == syntax.inc(f.base)) == false { s.error = ast.failed(s.token, 2) return s }
        let id = as_u32(noun.as_field(seq.get(s.values, f.base)))
        let value = seq.get(s.nodes, id)
        if (noun.eq(ast.ty(value), f.expected)) == false { s.error = ast.issue(5, value) return s }
        f.values = tree.set(f.values, f.arity, f.pending, noun.atom(as_field(id) + 1))
        f.count = syntax.inc(f.count)
        s.vals = f.base
    } else if syntax.either(closing == false, (f.pending == signatures.NONE) == false) { s.error = ast.failed(s.token, 2) return s }
    if closing {
        if (f.count == f.arity) == false { s.error = syntax.error(5, f.start, s.token.end) return s }
        if syntax.either(seq.len(s.nodes) == s.node_cap, s.vals == s.capacity) { s.error = ast.failed(s.token, 7) return s }
        let mut head = signatures.NONE
        // Formula links follow declaration order, independent of source labels.
        for index in 0..32 {
            if index < f.count {
                if seq.len(s.arguments) == s.node_cap { s.error = ast.failed(s.token, 7) return s }
                let link = seq.len(s.arguments)
                s.arguments = seq.push(s.arguments, noun.pair(noun.atom(field.sub(noun.as_field(tree.get(f.values, f.arity, index)), 1)), noun.atom(as_field(head))), s.node_cap)
                head = link
            }
        }
        let id = seq.len(s.nodes)
        s.nodes = seq.push(s.nodes, ast.typed(ast.RECORD_VALUE, as_field(f.count), as_field(head), f.ty, f.start, s.token.end), s.node_cap)
        s.values = ast.store(s.values, s.vals, noun.atom(as_field(id)), s.capacity)
        s.vals = syntax.inc(s.vals)
        s.ops = syntax.dec(s.ops)
        s.frames = noun.tail(s.frames)
        s.operand = false
        s.token = lexer.next(source, s.token.end)
        return s
    }
    s.operand = true
    s.token = lexer.next(source, s.token.end)
    member(source, s, f)
}

#[pure]
pub fn project(source: bytes.Bytes, input: expression_state.State) -> expression_state.State {
    let mut s = input
    let name = lexer.next(source, s.token.end)
    if (name.kind == as_u32(1)) == false { s.error = ast.failed(name, 2) return s }
    let base = as_u32(noun.as_field(seq.get(s.values, syntax.dec(s.vals))))
    let value = seq.get(s.nodes, base)
    let selected = nominal.lookup(ast.ty(value), s.context.scope.types.owner, type_registry.name(source, name))
    if syntax.either(selected.exists == false, selected.visible == false) { s.error = ast.failed(name, 5) return s }
    if seq.len(s.nodes) == s.node_cap { s.error = ast.failed(name, 7) return s }
    let mut axis: Field = 2
    for index in 0..32 { if index < selected.index { axis = axis * 2 + 2 } }
    let id = seq.len(s.nodes)
    s.nodes = seq.push(s.nodes, ast.typed(ast.PROJECT, as_field(base), axis, selected.ty, ast.start(value), name.end), s.node_cap)
    s.values = seq.set(s.values, syntax.dec(s.vals), noun.atom(as_field(id)))
    s.token = lexer.next(source, name.end)
    s
}

