module std.compiler.nox.signatures

use vm.nox.noun
use vm.core.convert
use std.nox.seq
use std.nox.bytes
use std.compiler.nox.syntax
use std.compiler.nox.symbols

pub const NONE: U32 = 4096
pub struct Function {
    pub name: syntax.Token, pub params: U32, pub count: U32,
    pub returns: Noun, pub open: U32, pub close: U32
}

// Parameter ranges are allocated by a flat header pass; nested call arguments
// use a separate ownership structure and never borrow these ranges.
#[pure]
pub fn pack(f: Function) -> Noun {
    let name = noun.pair(noun.atom(as_field(f.name.start)), noun.atom(as_field(f.name.end)))
    let params = noun.pair(noun.atom(as_field(f.params)), noun.atom(as_field(f.count)))
    let body = noun.pair(noun.atom(as_field(f.open)), noun.atom(as_field(f.close)))
    return noun.pair(name, noun.pair(params, noun.pair(f.returns, body)))
}

#[pure]
pub fn read(value: Noun) -> Function {
    let name = noun.head(value)
    let info = noun.tail(value)
    let params = noun.head(info)
    let result = noun.tail(info)
    let body = noun.tail(result)
    Function { name: syntax.token(1, as_u32(noun.as_field(noun.head(name))), as_u32(noun.as_field(noun.tail(name))), 0),
        params: as_u32(noun.as_field(noun.head(params))), count: as_u32(noun.as_field(noun.tail(params))),
        returns: noun.head(result), open: as_u32(noun.as_field(noun.head(body))),
        close: as_u32(noun.as_field(noun.tail(body))) }
}

struct Search { remaining: U32, found: U32 }

#[pure]
fn chunk(source: bytes.Bytes, name: syntax.Token, functions: seq.Seq, start: U32, input: Search) -> Search {
    let mut s = input
    for turn in 0..8 {
        if s.remaining == start { return s }
        s.remaining = syntax.dec(s.remaining)
        // Packed signatures already begin with the full name span. Name lookup
        // needs no return/body decoding or temporary binding reconstruction.
        if symbols.same(source, name, seq.get(functions, s.remaining)) {
            s.found = s.remaining
            return s
        }
    }
    s
}

// Final callable bindings are independent of the current lexical local scope.
#[pure]
#[requires((syntax.TABLE_CAP < seq.len(functions)) == false)]
#[requires((syntax.SOURCE_CAP < bytes.len(source)) == false)]
pub fn lookup(source: bytes.Bytes, name: syntax.Token, functions: seq.Seq) -> U32 {
    lookup_range(source, name, functions, syntax.ZERO, seq.len(functions))
}

// Only the current owner's declaration range supplies bare callable names.
#[pure]
#[requires((syntax.TABLE_CAP < seq.len(functions)) == false)]
#[requires((syntax.SOURCE_CAP < bytes.len(source)) == false)]
#[requires((end < start) == false)]
#[requires((seq.len(functions) < end) == false)]
pub fn lookup_range(source: bytes.Bytes, name: syntax.Token, functions: seq.Seq, start: U32, end: U32) -> U32 {
    let mut s = Search { remaining: end, found: NONE }
    for turn in 0..512 {
        s = chunk(source, name, functions, start, s)
        if syntax.either((s.found == NONE) == false, s.remaining == start) { return s.found }
    }
    NONE
}

sources.std.compiler.nox.struct_parse:
module std.compiler.nox.struct_parse

use vm.nox.noun
use vm.core.convert
use std.nox.bytes
use std.nox.seq
use std.compiler.nox.syntax
use std.compiler.nox.ast
use std.compiler.nox.lexer
use std.compiler.nox.nominal
use std.compiler.nox.type_registry
use std.compiler.nox.type_parse

pub struct Parsed { pub scope: type_registry.Scope, pub token: syntax.Token, pub error: syntax.Error }

#[pure]
fn failed(scope: type_registry.Scope, token: syntax.Token, code: Field) -> Parsed {
    Parsed { scope, token, error: ast.failed(token, code) }
}

// Register only a complete layout. Field types resolve against the preceding
// registry, so a declaration cannot refer to itself or a later layout.
#[pure]
#[requires((syntax.SOURCE_CAP < bytes.len(source)) == false)]
#[requires((syntax.TABLE_CAP < cap) == false)]
pub fn parse(source: bytes.Bytes, opening: syntax.Token, scope: type_registry.Scope, public: Bool, cap: U32) -> Parsed {
    let name_token = lexer.next(source, opening.end)
    if (name_token.kind == as_u32(1)) == false { return failed(scope, name_token, 2) }
    if seq.len(scope.records) == cap { return failed(scope, name_token, 7) }
    let name = type_registry.name(source, name_token)
    let previous = type_registry.lookup(scope, name)
    let mut token = lexer.next(source, name_token.end)
    if (token.kind == as_u32(7)) == false { return failed(scope, token, 2) }
    token = lexer.next(source, token.end)
    let mut members = seq.empty()
    let mut spans = seq.empty()
    for index in 0..33 {
        if token.kind == as_u32(8) {
            let built = nominal.build(scope.owner, name, members, cap, syntax.STACK_CAP)
            if (built.status == syntax.ZERO) == false {
                let mut at = name_token
                if built.field < seq.len(spans) {
                    let span = seq.get(spans, built.field)
                    at = syntax.token(1, as_u32(noun.as_field(noun.head(span))), as_u32(noun.as_field(noun.tail(span))), 0)
                }
                return failed(scope, at, as_field(built.status))
            }
            if previous.exists {
                if noun.eq(previous.ty, built.ty) == false { return failed(scope, name_token, 5) }
            }
            let mut result = scope
            result.records = seq.push(result.records, type_registry.record(built.ty, public), cap)
            return Parsed { scope: result, token: lexer.next(source, token.end), error: syntax.error(0, syntax.ZERO, syntax.ZERO) }
        }
        let mut visible = false
        if token.kind == as_u32(40) { visible = true token = lexer.next(source, token.end) }
        let field_token = token
        if (field_token.kind == as_u32(1)) == false { return failed(scope, field_token, 2) }
        if syntax.either(index == nominal.MAX_FIELDS, seq.len(members) == cap) { return failed(scope, field_token, 7) }
        token = lexer.next(source, token.end)
        if (token.kind == as_u32(17)) == false { return failed(scope, token, 2) }
        token = lexer.next(source, token.end)
        let parsed = type_parse.parse(source, token, scope, cap)
        if (parsed.error.code == syntax.ZERO) == false { return Parsed { scope, token: parsed.token, error: parsed.error } }
        members = seq.push(members, nominal.field(type_registry.name(source, field_token), parsed.ty, visible), cap)
        spans = seq.push(spans, noun.pair(noun.atom(as_field(field_token.start)), noun.atom(as_field(field_token.end))), cap)
        token = parsed.token
        if token.kind == as_u32(26) { token = lexer.next(source, token.end) }
        else if (token.kind == as_u32(8)) == false { return failed(scope, token, 2) }
    }
    failed(scope, token, 7)
}

sources.std.compiler.nox.symbols:
module std.compiler.nox.symbols

use vm.nox.noun
use vm.core.convert
use vm.core.field
use std.nox.seq
use std.nox.bytes
use std.compiler.nox.syntax
use std.compiler.nox.types

pub struct Found { pub exists: Bool, pub slot: U32, pub writable: Bool, pub ty: Noun }

// The record index is its stable slot. Visible lists select lexical bindings;
// restoring an outer list never reuses slots allocated in a finished branch.
#[pure]
pub fn binding(name: syntax.Token, writable: Bool, ty: Noun) -> Noun {
    let mut flag: Field = 0
    if writable { flag = 1 }
    let span = noun.pair(noun.atom(as_field(name.start)), noun.atom(as_field(name.end)))
    noun.pair(span, noun.pair(noun.atom(flag), ty))
}

#[pure]
pub fn same(source: bytes.Bytes, name: syntax.Token, binding: Noun) -> Bool {
    let span = noun.head(binding)
    let start = as_u32(noun.as_field(noun.head(span)))
    let end = as_u32(noun.as_field(noun.tail(span)))
    if (field.sub(as_field(name.end), as_field(name.start)) == field.sub(as_field(end), as_field(start))) == false { return false }
    let mut a = name.start
    let mut b = start
    for step in 0..65536 {
        if a == name.end { return true }
        if (bytes.get(source, a) == bytes.get(source, b)) == false { return false }
        a = syntax.inc(a)
        b = syntax.inc(b)
    }
    a == name.end
}

#[pure]
#[requires((syntax.TABLE_CAP < seq.len(bindings)) == false)]
#[requires((syntax.SOURCE_CAP < bytes.len(source)) == false)]
pub fn lookup(source: bytes.Bytes, name: syntax.Token, bindings: seq.Seq, visible: Noun) -> Found {
    let mut cursor = visible
    for step in 0..4096 {
        if noun.eq(cursor, noun.atom(0)) { return Found { exists: false, slot: syntax.ZERO, writable: false, ty: noun.atom(types.INVALID) } }
        let index = as_u32(noun.as_field(noun.head(cursor)))
        let binding = seq.get(bindings, index)
        if same(source, name, binding) {
            let metadata = noun.tail(binding)
            return Found { exists: true, slot: index, writable: noun.as_field(noun.head(metadata)) == 1, ty: noun.tail(metadata) }
        }
        cursor = noun.tail(cursor)
    }
    Found { exists: false, slot: syntax.ZERO, writable: false, ty: noun.atom(types.INVALID) }
}

sources.std.compiler.nox.syntax:
module std.compiler.nox.syntax

use vm.core.convert
use vm.core.field
use std.nox.bytes

pub const ZERO: U32 = 0
// Source offsets and internal table IDs have independent capacities.
pub const SOURCE_CAP: U32 = 65536
pub const TABLE_CAP: U32 = 4096
pub const STACK_CAP: U32 = 64

// Internal compiler records are shared explicitly between native stages.
pub struct Error { pub code: U32, pub start: U32, pub end: U32 }
pub struct Token { pub kind: U32, pub start: U32, pub end: U32, pub value: Field }

#[pure]
#[requires(value < as_u32(4294967295))]
pub fn inc(value: U32) -> U32 { convert.as_u32(convert.as_field(value) + 1) }

#[pure]
#[requires((value == ZERO) == false)]
pub fn dec(value: U32) -> U32 { convert.as_u32(field.sub(convert.as_field(value), 1)) }

#[pure]
pub fn error(code: Field, start: U32, end: U32) -> Error {
    Error { code: convert.as_u32(code), start, end }
}

#[pure]
pub fn token(kind: Field, start: U32, end: U32, value: Field) -> Token {
    Token { kind: convert.as_u32(kind), start, end, value }
}

// Arguments are evaluated before these Boolean combinators are called.
#[pure]
pub fn either(a: Bool, b: Bool) -> Bool { if a { return true } b }

#[pure]
pub fn both(a: Bool, b: Bool) -> Bool { if a { return b } false }

// Exact bounded spelling for metadata names longer than the lexer pack.
#[pure]
#[requires((name.end < name.start) == false)]
#[requires((bytes.len(source) < name.end) == false)]
#[requires((9 < field.sub(convert.as_field(name.end), convert.as_field(name.start))) == false)]
pub fn spells(source: bytes.Bytes, name: Token, spelling: [Field; 9]) -> Bool {
    let length = convert.as_u32(field.sub(convert.as_field(name.end), convert.as_field(name.start)))
    for i in 0..9 {
        if i == length { return true }
        if (convert.as_field(bytes.get(source, convert.as_u32(convert.as_field(name.start) + convert.as_field(i)))) == spelling[i]) == false { return false }
    }
    true
}

sources.std.compiler.nox.terminal:
module std.compiler.nox.terminal

use vm.nox.noun
use vm.core.convert
use std.nox.seq
use std.nox.tree
use std.compiler.nox.syntax
use std.compiler.nox.ast
use std.compiler.nox.blocks
use std.compiler.nox.halting

pub struct Marked { pub flags: Noun, pub remaining: U32, pub error: syntax.Error }

// Each block has one owner. Parents follow children, so descending propagation
// visits each terminal block once, including both arms of constant conditions.
#[pure]
fn chunk(nodes: seq.Seq, statements: seq.Seq, bodies: seq.Seq, arguments: seq.Seq, input: Marked, returns: Noun) -> Marked {
    let mut s = input
    for turn in 0..8 {
        if s.remaining == syntax.ZERO { return s }
        s.remaining = syntax.dec(s.remaining)
        if noun.as_field(tree.get(s.flags, seq.len(bodies), s.remaining)) == 1 {
            let block = blocks.read(seq.get(bodies, s.remaining))
            if block.has_tail {
                let tail = seq.get(nodes, block.tail)
                if (noun.eq(ast.ty(tail), returns)) == false {
                    if halting.is_false_assert(tail, nodes, arguments) == false { s.error = ast.issue(5, tail) return s }
                }
            } else if noun.eq(block.statements, noun.atom(0)) == false {
                let last = blocks.read_statement(seq.get(statements, as_u32(noun.as_field(noun.head(block.statements)))))
                if last.kind == blocks.IF {
                    s.flags = tree.set(s.flags, seq.len(bodies), last.b, noun.atom(1))
                    if (last.c == blocks.NONE) == false { s.flags = tree.set(s.flags, seq.len(bodies), last.c, noun.atom(1)) }
                }
            }
        }
    }
    s
}

#[pure]
#[requires(root < seq.len(bodies))]
#[requires((syntax.TABLE_CAP < seq.len(bodies)) == false)]
pub fn mark(nodes: seq.Seq, statements: seq.Seq, bodies: seq.Seq, arguments: seq.Seq, root: U32, returns: Noun) -> Marked {
    let flags = tree.set(tree.empty(tree.shape(seq.len(bodies)).height), seq.len(bodies), root, noun.atom(1))
    let mut s = Marked { flags, remaining: seq.len(bodies), error: syntax.error(0, syntax.ZERO, syntax.ZERO) }
    for turn in 0..512 {
        s = chunk(nodes, statements, bodies, arguments, s, returns)
        if syntax.either(s.remaining == syntax.ZERO, (s.error.code == syntax.ZERO) == false) { return s }
    }
    s.error = syntax.error(7, syntax.ZERO, syntax.ZERO)
    s
}

sources.std.compiler.nox.tuple_bind:
module std.compiler.nox.tuple_bind

use vm.nox.noun
use vm.core.convert
use std.nox.bytes
use std.nox.seq
use std.compiler.nox.syntax
use std.compiler.nox.ast
use std.compiler.nox.types
use std.compiler.nox.symbols
use std.compiler.nox.blocks
use std.compiler.nox.body_state
use std.compiler.nox.tuple_pattern

// The expression has already been parsed against the old scope. Every target
// is checked before a hidden RHS slot or any ordered component writes exist.
#[pure]
pub fn bind(source: bytes.Bytes, input: body_state.State, names: seq.Seq, writable: Bool, declaration: Bool, value: U32, cap: U32) -> body_state.State {
    let mut s = input
    let rhs = seq.get(s.nodes, value)
    let parts = types.parts(ast.ty(rhs))
    let count = seq.len(names)
    if syntax.either(parts.valid == false, (count == parts.count) == false) {
        s.error = ast.issue(5, rhs) return s
    }
    let mut targets = seq.empty()
    for i in 0..16 {
        if i < count {
            let name = tuple_pattern.name(seq.get(names, i))
            if declaration == false {
                let found = symbols.lookup(source, name, s.bindings, s.visible)
                if syntax.either(syntax.either(found.exists == false, found.writable == false), noun.eq(found.ty, types.component(parts, i)) == false) {
                    s.error = syntax.error(5, name.start, name.end) return s
                }
                targets = seq.push(targets, noun.atom(as_field(found.slot)), cap)
            }
        }
    }
    if syntax.either(seq.len(s.bindings) == cap, seq.len(s.nodes) == cap) { s.error = ast.issue(7, rhs) return s }
    let hidden = seq.len(s.bindings)
    let name = syntax.token(1, ast.start(rhs), ast.end(rhs), 0)
    s.bindings = seq.push(s.bindings, symbols.binding(name, false, ast.ty(rhs)), cap)
    s = body_state.append(s, blocks.statement(blocks.WRITE, hidden, value, syntax.ZERO), cap)
    if (s.error.code == syntax.ZERO) == false { return s }
    let base = seq.len(s.nodes)
    s.nodes = seq.push(s.nodes, ast.typed(ast.LOCAL, as_field(hidden), 0, ast.ty(rhs), ast.start(rhs), ast.end(rhs)), cap)
    let mut axis: Field = 2
    for i in 0..16 {
        if i == count { return s }
        let name = tuple_pattern.name(seq.get(names, i))
        if tuple_pattern.discard(name) == false {
            let ty = types.component(parts, i)
            if syntax.either(seq.len(s.nodes) == cap, syntax.both(declaration, seq.len(s.bindings) == cap)) { s.error = ast.issue(7, rhs) return s }
            let mut slot = seq.len(s.bindings)
            if declaration == false { slot = as_u32(noun.as_field(seq.get(targets, i))) }
            let mut projection = axis
            if parts.digest { projection = 4 + as_field(i) }
            let projected = seq.len(s.nodes)
            s.nodes = seq.push(s.nodes, ast.typed(ast.PROJECT, as_field(base), projection, ty, name.start, name.end), cap)
            s = body_state.append(s, blocks.statement(blocks.WRITE, slot, projected, syntax.ZERO), cap)
            if (s.error.code == syntax.ZERO) == false { return s }
            if declaration {
                s.bindings = seq.push(s.bindings, symbols.binding(name, writable, ty), cap)
                s.visible = noun.pair(noun.atom(as_field(slot)), s.visible)
            }
        }
        axis = axis * 2 + 2
    }
    s
}

sources.std.compiler.nox.tuple_declarations:
module std.compiler.nox.tuple_declarations

use vm.nox.noun
use vm.core.convert
use std.nox.bytes
use std.nox.seq
use std.compiler.nox.syntax
use std.compiler.nox.ast
use std.compiler.nox.lexer
use std.compiler.nox.expression
use std.compiler.nox.expression_state
use std.compiler.nox.body_state
use std.compiler.nox.type_parse
use std.compiler.nox.tuple_pattern
use std.compiler.nox.tuple_bind

struct Read { body: body_state.State, id: U32 }

#[pure]
fn value(source: bytes.Bytes, input: body_state.State, cap: U32) -> Read {
    let mut s = input
    let parsed = expression.parse(source, lexer.next(source, s.token.end), expression_state.context(s.bindings, s.visible, s.scope), s.nodes, s.arguments, s.edges, cap, false)
    s.nodes = parsed.nodes
    s.arguments = parsed.arguments
    s.edges = parsed.edges
    if parsed.needs_get { s.needs_get = true }
    s.token = parsed.token
    s.error = parsed.error
    Read { body: s, id: parsed.value }
}

#[pure]
pub fn declare(source: bytes.Bytes, opening: syntax.Token, writable: Bool, input: body_state.State, cap: U32) -> body_state.State {
    let mut s = input
    let parsed = tuple_pattern.parse(source, lexer.next(source, opening.end), cap)
    s.error = parsed.error
    if (s.error.code == syntax.ZERO) == false { return s }
    s.token = parsed.token
    let mut annotated = false
    let mut expected = noun.atom(0)
    if s.token.kind == as_u32(17) {
        let ty = type_parse.parse(source, lexer.next(source, s.token.end), s.scope.types, cap)
        s.error = ty.error
        if (s.error.code == syntax.ZERO) == false { return s }
        expected = ty.ty
        annotated = true
        s.token = ty.token
    }
    if (s.token.kind == as_u32(18)) == false { s.error = ast.failed(s.token, 2) return s }
    let result = value(source, s, cap)
    s = result.body
    if (s.error.code == syntax.ZERO) == false { return s }
    let rhs = seq.get(s.nodes, result.id)
    if syntax.both(annotated, noun.eq(expected, ast.ty(rhs)) == false) { s.error = ast.issue(5, rhs) return s }
    tuple_bind.bind(source, s, parsed.names, writable, true, result.id, cap)
}

#[pure]
pub fn assign(source: bytes.Bytes, input: body_state.State, lhs: U32, cap: U32) -> body_state.State {
    let mut s = input
    let node = seq.get(s.nodes, lhs)
    if (ast.kind(node) == ast.TUPLE_VALUE) == false { s.error = ast.failed(s.token, 2) return s }
    let count = as_u32(ast.left(node))
    let mut cursor = as_u32(ast.right(node))
    let mut reversed = noun.atom(0)
    for i in 0..16 {
        if i < count {
            let link = seq.get(s.arguments, cursor)
            let target = seq.get(s.nodes, as_u32(noun.as_field(noun.head(link))))
            if (ast.kind(target) == ast.LOCAL) == false { s.error = ast.issue(5, target) return s }
            let name = syntax.token(1, ast.start(target), ast.end(target), 0)
            reversed = noun.pair(tuple_pattern.pack(name), reversed)
            cursor = as_u32(noun.as_field(noun.tail(link)))
        }
    }
    let mut names = seq.empty()
    for i in 0..16 {
        if i < count {
            names = seq.push(names, noun.head(reversed), cap)
            reversed = noun.tail(reversed)
        }
    }
    let result = value(source, s, cap)
    s = result.body
    if (s.error.code == syntax.ZERO) == false { return s }
    tuple_bind.bind(source, s, names, false, false, result.id, cap)
}

sources.std.compiler.nox.tuple_pattern:
module std.compiler.nox.tuple_pattern

use vm.nox.noun
use vm.core.convert
use std.nox.bytes
use std.nox.seq
use std.compiler.nox.syntax
use std.compiler.nox.ast
use std.compiler.nox.lexer
use std.compiler.nox.types

pub struct Parsed { pub names: seq.Seq, pub token: syntax.Token, pub error: syntax.Error }

#[pure]
pub fn discard(token: syntax.Token) -> Bool {
    syntax.both(token.kind == as_u32(13), token.value == 95)
}

#[pure]
pub fn pack(token: syntax.Token) -> Noun {
    let mut flag: Field = 0
    if discard(token) { flag = 1 }
    noun.pair(noun.atom(as_field(token.start)), noun.pair(noun.atom(as_field(token.end)), noun.atom(flag)))
}

#[pure]
pub fn name(record: Noun) -> syntax.Token {
    let end = noun.tail(record)
    let mut kind: Field = 1
    let mut value: Field = 0
    if noun.as_field(noun.tail(end)) == 1 { kind = 13 value = 95 }
    syntax.token(kind, as_u32(noun.as_field(noun.head(record))), as_u32(noun.as_field(noun.head(end))), value)
}

// Called just after the opening parenthesis. The seed accepts a trailing comma
// and empty pattern syntax; component-count validation belongs to the binder.
#[pure]
pub fn parse(source: bytes.Bytes, token: syntax.Token, cap: U32) -> Parsed {
    let zero = syntax.ZERO
    let mut s = Parsed { names: seq.empty(), token, error: syntax.error(0, zero, zero) }
    for i in 0..17 {
        if s.token.kind == as_u32(6) { s.token = lexer.next(source, s.token.end) return s }
        if syntax.either(s.token.kind == as_u32(1), discard(s.token)) == false {
            s.error = ast.failed(s.token, 2) return s
        }
        if syntax.either(seq.len(s.names) == cap, seq.len(s.names) == types.MAX_ARITY) {
            s.error = ast.failed(s.token, 7) return s
        }
        s.names = seq.push(s.names, pack(s.token), cap)
        s.token = lexer.next(source, s.token.end)
        if s.token.kind == as_u32(6) { s.token = lexer.next(source, s.token.end) return s }
        if (s.token.kind == as_u32(26)) == false { s.error = ast.failed(s.token, 2) return s }
        s.token = lexer.next(source, s.token.end)
    }
    s.error = ast.failed(s.token, 7)
    s
}

sources.std.compiler.nox.type_exports:
module std.compiler.nox.type_exports

use vm.nox.noun
use std.nox.bytes
use std.nox.seq
use std.nox.tree
use std.compiler.nox.syntax
use std.compiler.nox.nominal
use std.compiler.nox.types

// The driver publishes final public descriptors built by nominal.build. Their
// owned names and layouts retain defining identity independently of graph IDs.
pub struct Bank { records: seq.Seq, heads: Noun, modules: U32 }
pub struct Found { pub exists: Bool, pub ty: Noun }

#[pure]
#[requires((syntax.TABLE_CAP < modules) == false)]
#[ensures(len(result) == syntax.ZERO)]
pub fn empty(modules: U32) -> Bank {
    assert((syntax.TABLE_CAP < modules) == false)
    Bank { records: seq.empty(), heads: tree.empty(tree.shape(modules).height), modules }
}

#[pure]
pub fn len(bank: Bank) -> U32 { seq.len(bank.records) }

// A row is [previous descriptor]; module heads contain row ID+1, or zero.
// Capacity is checked before append. Known descriptors enter unchanged; this
// compiler-owned bank has no serialized-handle admission or source-name spans.
#[pure]
#[requires(len(bank) < cap)]
#[requires((syntax.TABLE_CAP < cap) == false)]
#[requires(owner < bank.modules)]
#[requires(noun.as_field(noun.head(ty)) == types.NOMINAL)]
#[ensures(as_field(len(result)) == as_field(len(bank)) + 1)]
pub fn push(bank: Bank, owner: U32, ty: Noun, cap: U32) -> Bank {
    assert((syntax.TABLE_CAP < cap) == false)
    assert(len(bank) < cap)
    assert(owner < bank.modules)
    assert_eq(noun.as_field(noun.head(ty)), types.NOMINAL)
    let id = len(bank)
    let next = tree.get(bank.heads, bank.modules, owner)
    Bank { records: seq.push(bank.records, noun.pair(next, ty), cap),
        heads: tree.set(bank.heads, bank.modules, owner, noun.atom(as_field(id) + 1)), modules: bank.modules }
}

#[pure]
#[requires(owner < bank.modules)]
#[requires((syntax.SOURCE_CAP < bytes.len(name)) == false)]
pub fn find(bank: Bank, owner: U32, name: bytes.Bytes) -> Found {
    let wanted = bytes.to_noun(name)
    let mut cursor = as_u32(noun.as_field(tree.get(bank.heads, bank.modules, owner)))
    for step in 0..4096 {
        if cursor == syntax.ZERO { return Found { exists: false, ty: noun.atom(types.INVALID) } }
        let row = seq.get(bank.records, syntax.dec(cursor))
        let ty = noun.tail(row)
        if noun.eq(nominal.name(ty), wanted) { return Found { exists: true, ty } }
        cursor = as_u32(noun.as_field(noun.head(row)))
    }
    assert(cursor == syntax.ZERO)
    Found { exists: false, ty: noun.atom(types.INVALID) }
}

sources.std.compiler.nox.type_imports:
module std.compiler.nox.type_imports

use vm.nox.noun
use std.nox.bytes
use std.compiler.nox.syntax
use std.compiler.nox.qualified_name
use std.compiler.nox.type_exports
use std.compiler.nox.types

// Graph names and ordered uses select only direct dependencies. Descriptors
// already own complete declaration names, so lookup needs no foreign source.
pub struct View {
    pub names: bytes.BytesTable, pub exports: type_exports.Bank, pub uses: Noun
}

#[pure]
pub fn empty() -> View {
    View { names: bytes.table_empty(), exports: type_exports.empty(syntax.ZERO), uses: noun.atom(0) }
}

// The caller extracts the final member once from its own source. A successful
// qualified_name.parse and the graph own prefix/name bounds and use records.
// Qualified lookup inspects every ordered use, including after a match; lists
// over 4096 fail closed instead of returning a partially resolved binding.
#[pure]
#[requires(name.error.code == syntax.ZERO)]
#[requires((syntax.SOURCE_CAP < bytes.len(member)) == false)]
pub fn lookup(name: qualified_name.Name, member: bytes.Bytes, view: View) -> type_exports.Found {
    let mut found = type_exports.Found { exists: false, ty: noun.atom(types.INVALID) }
    if bytes.len(name.prefix) == syntax.ZERO { return found }
    let mut rest = view.uses
    for step in 0..4096 {
        if noun.eq(rest, noun.atom(0)) { return found }
        // module_store.Use starts with its compact target module ID.
        let target = as_u32(noun.as_field(noun.head(noun.head(rest))))
        let owner = bytes.table_get(view.names, target)
        if qualified_name.matches_owner(name.prefix, owner) {
            let candidate = type_exports.find(view.exports, target, member)
            // Missing/private symbols in a later same-basename module leave
            // the earlier public binding visible; repeated uses retain order.
            if candidate.exists { found = candidate }
        }
        rest = noun.tail(rest)
    }
    assert(noun.eq(rest, noun.atom(0)))
    found
}

sources.std.compiler.nox.type_parse:
module std.compiler.nox.type_parse

use vm.nox.noun
use vm.core.convert
use std.nox.seq
use std.nox.bytes
use std.compiler.nox.type_registry
use std.compiler.nox.syntax
use std.compiler.nox.lexer
use std.compiler.nox.ast
use std.compiler.nox.types
use std.compiler.nox.array_size
use std.compiler.nox.qualified_name

pub struct Parsed { pub ty: Noun, pub token: syntax.Token, pub error: syntax.Error }
struct State {
    token: syntax.Token, ty: Noun, children: seq.Seq, frames: Noun,
    depth: U32, operand: Bool, done: Bool, error: syntax.Error
}

#[pure]
pub fn scalar(token: syntax.Token) -> Field {
    if token.kind == as_u32(12) { return types.FIELD }
    if token.kind == as_u32(20) { return types.BOOL }
    if token.kind == as_u32(28) { return types.UINT32 }
    if token.kind == as_u32(34) { return types.NOUN }
    if token.kind == as_u32(35) { return types.DIGEST }
    types.INVALID
}

#[pure]
fn step(source: bytes.Bytes, scope: type_registry.Scope, input: State, cap: U32, stack: U32) -> State {
    let mut s = input
    if s.operand {
        if s.token.kind == as_u32(36) {
            let array = array_size.parse(source, s.token, cap, stack)
            s.ty = array.ty
            s.token = array.token
            s.error = array.error
            s.operand = false
            return s
        }
        if s.token.kind == as_u32(5) {
            if s.depth == stack { s.error = ast.failed(s.token, 7) return s }
            s.frames = noun.pair(seq.to_noun(s.children), s.frames)
            s.children = seq.empty()
            s.depth = syntax.inc(s.depth)
            s.token = lexer.next(source, s.token.end)
            return s
        }
        if s.token.kind == as_u32(1) {
            let following = lexer.next(source, s.token.end)
            if following.kind == as_u32(41) {
                let query = qualified_name.parse(source, s.token)
                s.error = query.error
                if (s.error.code == syntax.ZERO) == false { return s }
                let found = type_registry.imported(source, query, scope)
                if found.exists == false { s.error = syntax.error(5, query.start, query.end) return s }
                s.ty = found.ty
                s.token = query.token
                s.operand = false
                return s
            }
            let found = type_registry.lookup(scope, type_registry.name(source, s.token))
            if found.exists == false { s.error = ast.failed(s.token, 5) return s }
            s.ty = found.ty
            s.token = following
            s.operand = false
            return s
        }
        let tag = scalar(s.token)
        if tag == types.INVALID {
            let mut code: Field = 2
            if syntax.either(s.token.kind == as_u32(1), s.token.kind == as_u32(36)) { code = 6 }
            s.error = ast.failed(s.token, code)
            return s
        }
        s.ty = noun.atom(tag)
        s.token = lexer.next(source, s.token.end)
        s.operand = false
        return s
    }
    if s.depth == syntax.ZERO { s.done = true return s }
    if syntax.either(seq.len(s.children) == types.MAX_ARITY, seq.len(s.children) == cap) {
        s.error = ast.failed(s.token, 7) return s
    }
    s.children = seq.push(s.children, s.ty, cap)
    if s.token.kind == as_u32(26) {
        s.token = lexer.next(source, s.token.end)
        s.operand = true
        return s
    }
    if s.token.kind == as_u32(6) {
        let built = types.tuple(s.children, cap, stack)
        if built.failed { s.error = ast.failed(s.token, 7) return s }
        s.ty = built.ty
        s.children = seq.from_noun(noun.head(s.frames), cap, as_u32(1000))
        s.frames = noun.tail(s.frames)
        s.depth = syntax.dec(s.depth)
        s.token = lexer.next(source, s.token.end)
        return s
    }
    let mut code: Field = 2
    if s.token.kind == as_u32(14) { code = 1 }
    s.error = syntax.error(code, s.token.start, s.token.end)
    s
}

#[pure]
#[requires((syntax.SOURCE_CAP < bytes.len(source)) == false)]
#[requires((syntax.TABLE_CAP < cap) == false)]
pub fn parse(source: bytes.Bytes, token: syntax.Token, scope: type_registry.Scope, cap: U32) -> Parsed {
    let zero = syntax.ZERO
    if cap == zero { return Parsed { ty: noun.atom(types.INVALID), token, error: syntax.error(7, token.start, token.end) } }
    let tag = scalar(token)
    if (tag == types.INVALID) == false {
        return Parsed { ty: noun.atom(tag), token: lexer.next(source, token.end), error: syntax.error(0, zero, zero) }
    }
    let mut stack = cap
    if syntax.STACK_CAP < stack { stack = syntax.STACK_CAP }
    let mut s = State { token, ty: noun.atom(types.INVALID), children: seq.empty(), frames: noun.atom(0),
        depth: zero, operand: true, done: false, error: syntax.error(0, zero, zero) }
    for block in 0..256 {
        for turn in 0..32 {
            s = step(source, scope, s, cap, stack)
            if syntax.either(s.done, (s.error.code == zero) == false) {
                return Parsed { ty: s.ty, token: s.token, error: s.error }
            }
        }
    }
    Parsed { ty: noun.atom(types.INVALID), token: s.token, error: syntax.error(7, s.token.start, s.token.end) }
}

sources.std.compiler.nox.type_registry:
module std.compiler.nox.type_registry

use vm.nox.noun
use vm.core.convert
use std.nox.bytes
use std.nox.seq
use std.compiler.nox.syntax
use std.compiler.nox.nominal
use std.compiler.nox.types
use std.compiler.nox.type_imports
use std.compiler.nox.type_exports
use std.compiler.nox.qualified_name

pub struct Scope { pub owner: bytes.Bytes, pub records: seq.Seq, pub imports: type_imports.View }
pub struct Found { pub ty: Noun, pub exists: Bool, pub public: Bool }

#[pure]
pub fn empty() -> Scope { Scope { owner: bytes.empty(), records: seq.empty(), imports: type_imports.empty() } }

// Names retain every byte; the lexer's seven-byte keyword hint is never identity.
#[pure]
#[requires((bytes.len(source) < token.end) == false)]
#[requires((token.end < token.start) == false)]
#[requires((syntax.SOURCE_CAP < bytes.len(source)) == false)]
pub fn name(source: bytes.Bytes, token: syntax.Token) -> bytes.Bytes {
    let mut result = bytes.empty()
    let mut pos = token.start
    for step in 0..65536 {
        if pos == token.end { return result }
        result = bytes.push(result, bytes.get(source, pos), syntax.SOURCE_CAP)
        pos = syntax.inc(pos)
    }
    result
}

// Export visibility belongs to a declaration; field visibility belongs to its
// nominal layout. Keeping the two separate permits private types with pub fields.
#[pure]
pub fn record(ty: Noun, public: Bool) -> Noun {
    let mut flag: Field = 0
    if public { flag = 1 }
    noun.pair(ty, noun.atom(flag))
}

// Reverse lookup selects final local visibility without making imports bare.
#[pure]
#[requires((syntax.TABLE_CAP < seq.len(scope.records)) == false)]
pub fn position(scope: Scope, wanted: Noun) -> U32 {
    let mut index = seq.len(scope.records)
    for step in 0..4096 {
        if index == syntax.ZERO { return syntax.TABLE_CAP }
        index = syntax.dec(index)
        if noun.eq(nominal.name(noun.head(seq.get(scope.records, index))), wanted) { return index }
    }
    syntax.TABLE_CAP
}

#[pure]
pub fn lookup(scope: Scope, name: bytes.Bytes) -> Found {
    let index = position(scope, bytes.to_noun(name))
    if index == syntax.TABLE_CAP { return Found { ty: noun.atom(types.INVALID), exists: false, public: false } }
    let item = seq.get(scope.records, index)
    Found { ty: noun.head(item), exists: true, public: noun.as_field(noun.tail(item)) == 1 }
}

#[pure]
pub fn imported(source: bytes.Bytes, query: qualified_name.Name, scope: Scope) -> type_exports.Found {
    type_imports.lookup(query, name(source, query.member), scope.imports)
}

sources.std.compiler.nox.types:
module std.compiler.nox.types

use vm.nox.noun
use vm.core.convert
use std.nox.seq
use std.compiler.nox.syntax

pub const FIELD: Field = 0
pub const BOOL: Field = 1
pub const UNIT: Field = 2
pub const UINT32: Field = 3
pub const NOUN: Field = 4
pub const INVALID: Field = 5
pub const DIGEST: Field = 6
pub const TUPLE: Field = 16
pub const NOMINAL: Field = 17
pub const ARRAY: Field = 18
pub const MAX_ARITY: U32 = 16

pub struct Info { pub depth: U32, pub nodes: U32, pub contains_noun: Bool, pub valid: Bool }
pub struct Built { pub ty: Noun, pub failed: Bool }

// Descriptors are compiler-owned canonical values. Primitive types are atoms;
// tuple: [16 [children-Seq [logical-depth [logical-nodes contains-Noun-flag]]]].
// nominal.tri uses tag17 with the same metadata envelope and owned record identity.
// Accessors consume known primitive tags or descriptors from these constructors.
// Only constructors derive metadata. Source data never supplies descriptors.
#[pure]
pub fn info(ty: Noun) -> Info {
    for tag in 0..7 {
        if noun.eq(ty, noun.atom(as_field(tag))) {
            return Info { depth: syntax.ZERO, nodes: as_u32(1), contains_noun: as_field(tag) == NOUN, valid: (as_field(tag) == INVALID) == false }
        }
    }
    let metadata = noun.tail(noun.tail(ty))
    let extent = noun.tail(metadata)
    let kind = noun.as_field(noun.head(ty))
    Info { depth: as_u32(noun.as_field(noun.head(metadata))),
        nodes: as_u32(noun.as_field(noun.head(extent))),
        contains_noun: noun.as_field(noun.tail(extent)) == 1,
        valid: syntax.either(kind == ARRAY, syntax.either(kind == TUPLE, kind == NOMINAL)) }
}

#[pure]
pub fn contains_noun(ty: Noun) -> Bool { info(ty).contains_noun }

// Count logical type occurrences, including repeated children; sharing in the
// canonical DAG does not evade source complexity or nesting allowances.
#[pure]
#[requires((syntax.TABLE_CAP < node_cap) == false)]
#[requires((syntax.STACK_CAP < depth_cap) == false)]
pub fn tuple(children: seq.Seq, node_cap: U32, depth_cap: U32) -> Built {
    let failure = Built { ty: noun.atom(INVALID), failed: true }
    let count = seq.len(children)
    if syntax.either(count == syntax.ZERO, MAX_ARITY < count) { return failure }
    let mut depth = syntax.ZERO
    let mut nodes: Field = 1
    let mut flag: Field = 0
    for id in 0..16 {
        if id < count {
            let child = info(seq.get(children, id))
            if child.valid == false { return failure }
            nodes = nodes + as_field(child.nodes)
            if node_cap < as_u32(nodes) { return failure }
            if depth < child.depth { depth = child.depth }
            if child.contains_noun { flag = 1 }
        }
    }
    depth = syntax.inc(depth)
    if depth_cap < depth { return failure }
    let metadata = noun.pair(noun.atom(as_field(depth)), noun.pair(noun.atom(nodes), noun.atom(flag)))
    Built { ty: noun.pair(noun.atom(TUPLE), noun.pair(seq.to_noun(children), metadata)), failed: false }
}


pub struct Parts { pub children: seq.Seq, pub count: U32, pub digest: Bool, pub valid: Bool }

// Known descriptors only. Decode the owned child sequence once per pattern.
#[pure]
pub fn parts(ty: Noun) -> Parts {
    let mut result = Parts { children: seq.empty(), count: syntax.ZERO, digest: false, valid: false }
    if noun.eq(ty, noun.atom(DIGEST)) {
        result.digest = true
        result.valid = true
        result.count = as_u32(4)
        return result
    }
    if info(ty).depth == syntax.ZERO { return result }
    if (noun.as_field(noun.head(ty)) == TUPLE) == false { return result }
    result.children = seq.from_noun(noun.head(noun.tail(ty)), MAX_ARITY, as_u32(31))
    result.count = seq.len(result.children)
    result.valid = true
    result
}

// Digest limbs have a fixed primitive type; they need no synthesized collection.
#[pure]
#[requires(index < parts.count)]
pub fn component(parts: Parts, index: U32) -> Noun {
    if parts.digest { return noun.atom(FIELD) }
    seq.get(parts.children, index)
}

// Fixed Field arrays use [18 [[element length] metadata]]. Logical occurrence
// count includes every element, even when their canonical type value is shared.
#[pure]
#[requires((syntax.TABLE_CAP < node_cap) == false)]
#[requires((syntax.STACK_CAP < depth_cap) == false)]
pub fn array(length: U32, node_cap: U32, depth_cap: U32) -> Built {
    if syntax.either(depth_cap == syntax.ZERO, (length < node_cap) == false) {
        return Built { ty: noun.atom(INVALID), failed: true }
    }
    let data = noun.pair(noun.atom(FIELD), noun.atom(as_field(length)))
    let metadata = noun.pair(noun.atom(1), noun.pair(noun.atom(as_field(length) + 1), noun.atom(0)))
    Built { ty: noun.pair(noun.atom(ARRAY), noun.pair(data, metadata)), failed: false }
}

pub struct Array { pub length: U32, pub valid: Bool }

#[pure]
pub fn array_info(ty: Noun) -> Array {
    let absent = Array { length: syntax.ZERO, valid: false }
    if info(ty).depth == syntax.ZERO { return absent }
    if (noun.as_field(noun.head(ty)) == ARRAY) == false { return absent }
    Array { length: as_u32(noun.as_field(noun.tail(noun.head(noun.tail(ty))))), valid: true }
}

sources.std.compiler.nox.utf8:
module std.compiler.nox.utf8

use std.nox.bytes
use std.nox.tree
use vm.nox.noun
use std.compiler.nox.syntax

struct Scan { pos: U32, pending: U32, lead: U32, low: U32, high: U32, error: Bool }

#[pure]
#[requires((length < input.pos) == false)]
fn word(word: U32, length: U32, input: Scan) -> Scan {
    let mut s = input
    // A zero high-bit mask certifies every byte in this packed word as ASCII.
    // Pending continuations still examine the first offending byte exactly.
    if s.pending == syntax.ZERO {
        if (word & as_u32(2155905152)) == syntax.ZERO {
            let end = as_u32(as_field(s.pos) + 4)
            if length < end { s.pos = length } else { s.pos = end }
            return s
        }
    }
    for lane in 0..4 {
        if s.pos == length { return s }
        let c = bytes.word_byte(word, lane)
        if (s.pending == syntax.ZERO) == false {
            if syntax.either(c < s.low, (c < s.high) == false) {
                s.error = true
                s.pos = syntax.inc(s.pos)
                return s
            }
            s.pending = syntax.dec(s.pending)
            s.low = as_u32(128)
            s.high = as_u32(192)
        } else {
            if (c < as_u32(128)) == false {
                s.lead = s.pos
                s.low = as_u32(128)
                s.high = as_u32(192)
                if syntax.either(c < as_u32(194), (c < as_u32(245)) == false) {
                    s.error = true
                    s.pos = syntax.inc(s.pos)
                    return s
                }
                if c < as_u32(224) { s.pending = as_u32(1) }
                else if c < as_u32(240) { s.pending = as_u32(2) }
                else { s.pending = as_u32(3) }
                if c == as_u32(224) { s.low = as_u32(160) }
                if c == as_u32(237) { s.high = as_u32(160) }
                if c == as_u32(240) { s.low = as_u32(144) }
                if c == as_u32(244) { s.high = as_u32(144) }
            }
        }
        s.pos = syntax.inc(s.pos)
    }
    s
}

// A group contains eight packed words in their canonical height-three tree.
// All high-bit masks are nonnegative and their sum fits in Field, so zero
// certifies every lane as ASCII without a per-word state transition.
#[pure]
#[requires((length < input.pos) == false)]
fn group(node: Noun, length: U32, input: Scan) -> Scan {
    let a = noun.head(noun.head(node))
    let b = noun.tail(noun.head(node))
    let c = noun.head(noun.tail(node))
    let d = noun.tail(noun.tail(node))
    let w0 = as_u32(noun.as_field(noun.head(a)))
    let w1 = as_u32(noun.as_field(noun.tail(a)))
    let w2 = as_u32(noun.as_field(noun.head(b)))
    let w3 = as_u32(noun.as_field(noun.tail(b)))
    let w4 = as_u32(noun.as_field(noun.head(c)))
    let w5 = as_u32(noun.as_field(noun.tail(c)))
    let w6 = as_u32(noun.as_field(noun.head(d)))
    let w7 = as_u32(noun.as_field(noun.tail(d)))
    let mut s = input
    if s.pending == syntax.ZERO {
        let mask = as_u32(2155905152)
        let high = as_field(w0 & mask) + as_field(w1 & mask) + as_field(w2 & mask) + as_field(w3 & mask)
            + as_field(w4 & mask) + as_field(w5 & mask) + as_field(w6 & mask) + as_field(w7 & mask)
        if high == 0 {
            let end = as_u32(as_field(s.pos) + 32)
            if length < end { s.pos = length } else { s.pos = end }
            return s
        }
    }
    s = word(w0, length, s)
    if s.error { return s }
    s = word(w1, length, s)
    if s.error { return s }
    s = word(w2, length, s)
    if s.error { return s }
    s = word(w3, length, s)
    if s.error { return s }
    s = word(w4, length, s)
    if s.error { return s }
    s = word(w5, length, s)
    if s.error { return s }
    s = word(w6, length, s)
    if s.error { return s }
    word(w7, length, s)
}

// Each chunk unwinds its word and tree traversal frames before the next one.
#[pure]
#[requires((length < input.pos) == false)]
fn chunk(length: U32, input: Scan, words: tree.Cursor, grouped: Bool) -> (Scan, tree.Cursor) {
    let mut s = input
    let mut cursor = words
    for step in 0..64 {
        if s.pos == length { return (s, cursor) }
        let (value, next) = tree.read(cursor)
        cursor = next
        if grouped { s = group(value, length, s) }
        else { s = word(as_u32(noun.as_field(value)), length, s) }
        if s.error { return (s, cursor) }
    }
    (s, cursor)
}

#[pure]
#[requires((syntax.SOURCE_CAP < bytes.len(source)) == false)]
pub fn validate(source: bytes.Bytes) -> syntax.Error {
    let zero = syntax.ZERO
    let mut s = Scan { pos: zero, pending: zero, lead: zero, low: zero, high: zero, error: false }
    let grouped = as_u32(16) < bytes.len(source)
    let mut cursor = bytes.words(source)
    if grouped { cursor = bytes.word_groups(source) }
    for block in 0..256 {
        (s, cursor) = chunk(bytes.len(source), s, cursor, grouped)
        if s.error { return syntax.error(1, s.lead, s.pos) }
        if s.pos == bytes.len(source) {
            if (s.pending == zero) == false { return syntax.error(1, s.lead, s.pos) }
            return syntax.error(0, s.pos, s.pos)
        }
    }
    syntax.error(7, s.pos, s.pos)
}

sources.std.nox.bytes:
module std.nox.bytes

use vm.nox.noun
use vm.core.convert
use vm.core.field
use std.nox.tree
use std.nox.seq

const TAG: Field = 1113150513
const ZERO: U32 = 0
const THREE: U32 = 3
const BYTE_LIMIT: U32 = 256
const INV4: Field = 13835058052060938241

// The root contains packed U32 words, with no embedded Seq wrapper.
pub struct Bytes { length: U32, root: Noun, words: U32 }

// Only validated Bytes enter this table. Its private storage cannot be replaced
// by untrusted Nouns between compiler stages.
pub struct BytesTable { values: seq.Seq }

#[pure]
#[ensures(table_len(result) == ZERO)]
pub fn table_empty() -> BytesTable { BytesTable { values: seq.empty() } }

#[pure]
#[ensures(result == seq.len(table.values))]
pub fn table_len(table: BytesTable) -> U32 { seq.len(table.values) }

#[pure]
#[requires(table_len(table) < max_length)]
#[ensures(convert.as_field(table_len(result)) == convert.as_field(table_len(table)) + 1)]
pub fn table_push(table: BytesTable, value: Bytes, max_length: U32) -> BytesTable {
    assert(table_len(table) < max_length)
    let stored = noun.pair(noun.atom(convert.as_field(value.length)), noun.pair(value.root, noun.atom(convert.as_field(value.words))))
    BytesTable { values: seq.push(table.values, stored, max_length) }
}

#[pure]
#[requires(index < table_len(table))]
pub fn table_get(table: BytesTable, index: U32) -> Bytes {
    let stored = seq.get(table.values, index)
    let payload = noun.tail(stored)
    Bytes { length: convert.as_u32(noun.as_field(noun.head(stored))), root: noun.head(payload), words: convert.as_u32(noun.as_field(noun.tail(payload))) }
}

#[pure]
#[ensures(len(result) == ZERO)]
pub fn empty() -> Bytes { Bytes { length: ZERO, root: noun.atom(0), words: ZERO } }

#[pure]
#[ensures(result == b.length)]
pub fn len(b: Bytes) -> U32 { b.length }

#[pure]
fn quotient(value: U32) -> U32 {
    let remainder = value & THREE
    convert.as_u32(field.sub(convert.as_field(value), convert.as_field(remainder)) * INV4)
}

#[pure]
fn word_count(length: U32) -> U32 {
    let whole = quotient(length)
    if (length & THREE) == ZERO { return whole }
    convert.as_u32(convert.as_field(whole) + 1)
}

#[pure]
#[requires(position < convert.as_u32(4))]
fn scale(position: U32) -> Field {
    let powers = [1, 256, 65536, 16777216]
    powers[position]
}

#[pure]
#[requires(index < len(b))]
#[ensures(result < BYTE_LIMIT)]
pub fn get(b: Bytes, index: U32) -> U32 {
    assert(index < b.length)
    let word = convert.as_u32(noun.as_field(tree.get(b.root, b.words, quotient(index))))
    let position = index & THREE
    // Keep this direct path for existing random readers. Sequential readers
    // call word_byte after retaining a packed word across several positions.
    if position == ZERO { return word & convert.as_u32(255) }
    if position == convert.as_u32(1) {
        return convert.as_u32(convert.as_field(word & convert.as_u32(65280)) * 18374686475393433601)
    }
    if position == convert.as_u32(2) {
        return convert.as_u32(convert.as_field(word & convert.as_u32(16711680)) * 18446462594437939201)
    }
    convert.as_u32(convert.as_field(word & convert.as_u32(4278190080)) * 18446742969902956801)
}

// Sequential readers share a traversal across packed words. Padding words are
// excluded; the final word's unused high lanes are canonical zero bytes.
#[pure]
pub fn words(b: Bytes) -> tree.Cursor { tree.cursor(b.root, b.words) }

// At least five words give the tree three levels. Treat each height-three
// subtree as one opaque leaf, including its canonical final padding words.
#[pure]
#[requires(convert.as_u32(16) < len(b))]
pub fn word_groups(b: Bytes) -> tree.Cursor {
    assert(convert.as_u32(16) < b.length)
    let remainder = b.length & convert.as_u32(31)
    let mut count = field.sub(convert.as_field(b.length), convert.as_field(remainder)) * 17870283317245378561
    if (remainder == ZERO) == false { count = count + 1 }
    tree.cursor(b.root, convert.as_u32(count))
}

// The offset addresses a byte. The first word contains that byte; at the end
// the cursor is empty even when the last word has unused high lanes.
#[pure]
#[requires((len(b) < offset) == false)]
pub fn words_from(b: Bytes, offset: U32) -> tree.Cursor {
    assert((b.length < offset) == false)
    if offset == b.length { return tree.cursor(noun.atom(0), ZERO) }
    tree.cursor_at(b.root, b.words, quotient(offset))
}

#[pure]
#[requires(offset < len(b))]
pub fn word_at(b: Bytes, offset: U32) -> U32 {
    assert(offset < b.length)
    convert.as_u32(noun.as_field(tree.get(b.root, b.words, quotient(offset))))
}

#[pure]
#[requires(position < convert.as_u32(4))]
#[ensures(result < BYTE_LIMIT)]
pub fn word_byte(word: U32, position: U32) -> U32 {
    assert(position < convert.as_u32(4))
    // The low two bits select a fixed byte lane. Direct masks avoid building
    // and indexing two temporary tables for each source byte.
    if position == ZERO { return word & convert.as_u32(255) }
    if position == convert.as_u32(1) {
        return convert.as_u32(convert.as_field(word & convert.as_u32(65280)) * 18374686475393433601)
    }
    if position == convert.as_u32(2) {
        return convert.as_u32(convert.as_field(word & convert.as_u32(16711680)) * 18446462594437939201)
    }
    convert.as_u32(convert.as_field(word & convert.as_u32(4278190080)) * 18446742969902956801)
}

#[pure]
#[requires(index < len(b))]
#[requires(value < BYTE_LIMIT)]
#[ensures(len(result) == len(b))]
#[ensures(get(result, index) == value)]
pub fn set(b: Bytes, index: U32, value: U32) -> Bytes {
    assert(index < b.length)
    assert(value < BYTE_LIMIT)
    let words = b.words
    let at = quotient(index)
    let word = convert.as_u32(noun.as_field(tree.get(b.root, words, at)))
    let factor = scale(index & THREE)
    let mask = convert.as_u32(255 * factor)
    let next = field.sub(convert.as_field(word), convert.as_field(word & mask)) + convert.as_field(value) * factor
    Bytes { length: b.length, root: tree.set(b.root, words, at, noun.atom(next)), words }
}

#[pure]
#[requires(len(b) < max_length)]
#[requires(value < BYTE_LIMIT)]
#[ensures(convert.as_field(len(result)) == convert.as_field(len(b)) + 1)]
pub fn push(b: Bytes, value: U32, max_length: U32) -> Bytes {
    assert(b.length < max_length)
    assert(value < BYTE_LIMIT)
    let length = convert.as_u32(convert.as_field(b.length) + 1)
    if (b.length & THREE) == ZERO {
        let root = tree.push(b.root, b.words, noun.atom(convert.as_field(value)), word_count(max_length))
        return Bytes { length, root, words: convert.as_u32(convert.as_field(b.words) + 1) }
    }
    // Existing high bytes are zero; exposing the next one preserves validity.
    set(Bytes { length, root: b.root, words: b.words }, b.length, value)
}

#[pure]
#[ensures(noun.as_field(noun.head(result)) == TAG)]
pub fn to_noun(b: Bytes) -> Noun {
    noun.pair(noun.atom(TAG), noun.pair(noun.atom(convert.as_field(b.length)), b.root))
}

// The byte decoder validates branches and packed payloads in one traversal.
// Full eight-word subtrees share one task and one allowance subtraction. Every
// shape visit and the historical height+1 payload charge remain accounted for.
#[pure]
fn validation_task(node: Noun, occupied: U32, capacity: Field, padding: Noun) -> Noun {
    noun.pair(node, noun.pair(noun.atom(convert.as_field(occupied)), noun.pair(noun.atom(capacity), padding)))
}

#[pure]
fn validate_eight(node: Noun) -> U32 {
    let left = noun.head(node)
    let right = noun.tail(node)
    let a = noun.head(left)
    let b = noun.tail(left)
    let c = noun.head(right)
    let d = noun.tail(right)
    // Each checked conversion must execute, including the first seven words.
    convert.as_u32(noun.as_field(noun.head(a)))
    convert.as_u32(noun.as_field(noun.tail(a)))
    convert.as_u32(noun.as_field(noun.head(b)))
    convert.as_u32(noun.as_field(noun.tail(b)))
    convert.as_u32(noun.as_field(noun.head(c)))
    convert.as_u32(noun.as_field(noun.tail(c)))
    convert.as_u32(noun.as_field(noun.head(d)))
    convert.as_u32(noun.as_field(noun.tail(d)))
}

#[pure]
fn validate_words_chunk(todo: Noun, visits: U32, cost: U32, last: U32) -> (Noun, U32, U32) {
    let mut work = todo
    let mut remaining = visits
    let mut final_word = last
    for step in 0..128 {
        if noun.eq(work, noun.atom(0)) { return (work, remaining, final_word) }
        assert(ZERO < remaining)
        remaining = convert.as_u32(field.sub(convert.as_field(remaining), 1))
        let current = noun.head(work)
        work = noun.tail(work)
        let node = noun.head(current)
        let body = noun.tail(current)
        let occupied = convert.as_u32(noun.as_field(noun.head(body)))
        let geometry = noun.tail(body)
        let capacity = noun.as_field(noun.head(geometry))
        let padding = noun.tail(geometry)
        if occupied == ZERO {
            assert(noun.eq(node, padding))
        } else if capacity == 1 {
            assert((remaining < cost) == false)
            remaining = convert.as_u32(field.sub(convert.as_field(remaining), convert.as_field(cost)))
            final_word = convert.as_u32(noun.as_field(node))
        } else if capacity == 8 {
            if occupied == convert.as_u32(8) {
                let charge = convert.as_u32(14 + convert.as_field(cost) * 8)
                assert((remaining < charge) == false)
                remaining = convert.as_u32(field.sub(convert.as_field(remaining), convert.as_field(charge)))
                final_word = validate_eight(node)
            } else {
                let half = convert.as_u32(4)
                let mut left_count = occupied
                let mut right_count = ZERO
                if half < occupied {
                    left_count = half
                    right_count = convert.as_u32(field.sub(convert.as_field(occupied), 4))
                }
                let child_padding = noun.head(padding)
                let right = validation_task(noun.tail(node), right_count, 4, child_padding)
                let left = validation_task(noun.head(node), left_count, 4, child_padding)
                work = noun.pair(left, noun.pair(right, work))
            }
        } else {
            let half_capacity = capacity * 9223372034707292161
            let half = convert.as_u32(half_capacity)
            let mut left_count = occupied
            let mut right_count = ZERO
            if half < occupied {
                left_count = half
                right_count = convert.as_u32(field.sub(convert.as_field(occupied), half_capacity))
            }
            let child_padding = noun.head(padding)
            let right = validation_task(noun.tail(node), right_count, half_capacity, child_padding)
            let left = validation_task(noun.head(node), left_count, half_capacity, child_padding)
            work = noun.pair(left, noun.pair(right, work))
        }
    }
    (work, remaining, final_word)
}

#[pure]
#[ensures((max_length < len(result)) == false)]
#[ensures(noun.eq(to_noun(result), value))]
pub fn from_noun(value: Noun, max_length: U32, max_visits: U32) -> Bytes {
    let (value, remaining) = from_noun_budget(value, max_length, max_visits)
    value
}

// Shape and payload validation leave one shared allowance for the next field.
#[pure]
#[requires((max_visits == ZERO) == false)]
pub fn from_noun_budget(value: Noun, max_length: U32, max_visits: U32) -> (Bytes, U32) {
    assert_eq(noun.as_field(noun.head(value)), TAG)
    let body = noun.tail(value)
    let length = convert.as_u32(noun.as_field(noun.head(body)))
    assert((max_length < length) == false)
    let root = noun.tail(body)
    let words = word_count(length)
    let geometry = tree.shape(words)
    let cost = convert.as_u32(convert.as_field(geometry.height) + 1)
    let initial = validation_task(root, words, geometry.capacity, tree.empty(geometry.height))
    let mut work = noun.pair(initial, noun.atom(0))
    let mut remaining = max_visits
    let mut last = ZERO
    // Each chunk consumes visits or returns/fails, including an empty tree.
    for chunk in 0..33554432 {
        (work, remaining, last) = validate_words_chunk(work, remaining, cost, last)
        if noun.eq(work, noun.atom(0)) {
            let used = length & THREE
            if (used == ZERO) == false { assert(last < convert.as_u32(scale(used))) }
            return (Bytes { length, root, words }, remaining)
        }
    }
    assert_eq(0, 1)
    (empty(), ZERO)
}

sources.std.nox.seq:
module std.nox.seq

use vm.nox.noun
use vm.core.convert
use std.nox.tree

const TAG: Field = 1397051697
const ZERO: U32 = 0

// Only this module can construct a handle. External trees enter via from_noun.
pub struct Seq { length: U32, root: Noun }

#[pure]
#[ensures(len(result) == ZERO)]
pub fn empty() -> Seq { Seq { length: ZERO, root: noun.atom(0) } }

#[pure]
#[ensures(result == s.length)]
pub fn len(s: Seq) -> U32 { s.length }

#[pure]
#[requires(index < len(s))]
pub fn get(s: Seq, index: U32) -> Noun { tree.get(s.root, s.length, index) }

#[pure]
#[requires(index < len(s))]
#[ensures(len(result) == len(s))]
#[ensures(noun.eq(get(result, index), value))]
pub fn set(s: Seq, index: U32, value: Noun) -> Seq {
    Seq { length: s.length, root: tree.set(s.root, s.length, index, value) }
}

#[pure]
#[requires(len(s) < max_length)]
#[ensures(convert.as_field(len(result)) == convert.as_field(len(s)) + 1)]
pub fn push(s: Seq, value: Noun, max_length: U32) -> Seq {
    assert(s.length < max_length)
    let root = tree.push(s.root, s.length, value, max_length)
    Seq { length: convert.as_u32(convert.as_field(s.length) + 1), root }
}

#[pure]
#[ensures(noun.as_field(noun.head(result)) == TAG)]
pub fn to_noun(s: Seq) -> Noun {
    noun.pair(noun.atom(TAG), noun.pair(noun.atom(convert.as_field(s.length)), s.root))
}

#[pure]
#[ensures((max_length < len(result)) == false)]
#[ensures(noun.eq(to_noun(result), value))]
pub fn from_noun(value: Noun, max_length: U32, max_visits: U32) -> Seq {
    let (value, remaining) = from_noun_budget(value, max_length, max_visits)
    value
}

// Return unspent visits so callers can validate several fields in one pass.
#[pure]
#[requires((max_visits == ZERO) == false)]
pub fn from_noun_budget(value: Noun, max_length: U32, max_visits: U32) -> (Seq, U32) {
    assert_eq(noun.as_field(noun.head(value)), TAG)
    let body = noun.tail(value)
    let length = convert.as_u32(noun.as_field(noun.head(body)))
    assert((max_length < length) == false)
    let root = noun.tail(body)
    let remaining = tree.validate(root, length, max_visits)
    (Seq { length, root }, remaining)
}

sources.std.nox.tree:
module std.nox.tree

use vm.nox.noun
use vm.core.convert
use vm.core.field

// Raw indexed-tree helpers. Validated handles belong to seq and bytes.
const ZERO: U32 = 0
const MAX_HEIGHT: U32 = 32
const HALF: Field = 9223372034707292161

pub struct Shape { pub height: U32, pub capacity: Field }

// A sequential cursor retains pending right subtrees. Each branch is entered
// once across a complete walk; occupied leaves remain opaque Nouns.
pub struct Cursor { node: Noun, capacity: Field, pending: Noun, count: U32 }

#[pure]
#[ensures(result == input.count)]
pub fn remaining(input: Cursor) -> U32 { input.count }

// Requires the canonical tree shape for length, as get does.
#[pure]
#[ensures(remaining(result) == length)]
pub fn cursor(root: Noun, length: U32) -> Cursor {
    Cursor { node: root, capacity: shape(length).capacity, pending: noun.atom(0), count: length }
}

#[pure]
#[requires((length < start) == false)]
#[ensures(convert.as_field(remaining(result)) + convert.as_field(start) == convert.as_field(length))]
pub fn cursor_at(root: Noun, length: U32, start: U32) -> Cursor {
    assert((length < start) == false)
    let count = convert.as_u32(field.sub(convert.as_field(length), convert.as_field(start)))
    if count == ZERO { return cursor(noun.atom(0), ZERO) }
    let mut node = root
    let mut capacity = shape(length).capacity
    let mut offset = start
    let mut pending = noun.atom(0)
    for level in 0..32 {
        if capacity == 1 { return Cursor { node, capacity, pending, count } }
        capacity = capacity * HALF
        if offset < convert.as_u32(capacity) {
            pending = noun.pair(noun.pair(noun.tail(node), noun.atom(capacity)), pending)
            node = noun.head(node)
        } else {
            node = noun.tail(node)
            offset = convert.as_u32(field.sub(convert.as_field(offset), capacity))
        }
    }
    Cursor { node, capacity, pending, count }
}

#[pure]
fn read_leaf(node: Noun, pending: Noun, count: U32) -> (Noun, Cursor) {
    if count == ZERO {
        return (node, Cursor { node: noun.atom(0), capacity: 1, pending: noun.atom(0), count })
    }
    let next = noun.head(pending)
    (node, Cursor { node: noun.head(next), capacity: noun.as_field(noun.tail(next)), pending: noun.tail(pending), count })
}

// At most 32 descents per read and at most 32 pending right subtrees. The
// driver's own chunk bound decides when evaluator loop frames are released.
#[pure]
#[requires(ZERO < remaining(input))]
pub fn read(input: Cursor) -> (Noun, Cursor) {
    assert(ZERO < input.count)
    let mut node = input.node
    let mut capacity = input.capacity
    let mut pending = input.pending
    let count = convert.as_u32(field.sub(convert.as_field(input.count), 1))
    for level in 0..32 {
        if capacity == 1 { return read_leaf(node, pending, count) }
        capacity = capacity * HALF
        pending = noun.pair(noun.pair(noun.tail(node), noun.atom(capacity)), pending)
        node = noun.head(node)
    }
    read_leaf(node, pending, count)
}

// Canonical all-zero padding, including E(0) = atom zero.
#[pure]
#[requires((MAX_HEIGHT < height) == false)]
pub fn empty(height: U32) -> Noun {
    assert((MAX_HEIGHT < height) == false)
    let mut root = noun.atom(0)
    for level in 0..32 {
        if level == height { return root }
        root = noun.pair(root, root)
    }
    root
}

// Capacity may be 2^32. Only values up to 2^31 are narrowed for comparison.
#[pure]
#[ensures((MAX_HEIGHT < result.height) == false)]
pub fn shape(length: U32) -> Shape {
    if length == ZERO { return Shape { height: ZERO, capacity: 1 } }
    // Small compiler tables dominate shape queries. Resolve their powers directly
    // so every get/set does not allocate a loop continuation for each tree level.
    if length < convert.as_u32(33) {
        if length < convert.as_u32(3) {
            if length == convert.as_u32(1) { return Shape { height: ZERO, capacity: 1 } }
            return Shape { height: convert.as_u32(1), capacity: 2 }
        }
        if length < convert.as_u32(9) {
            if length < convert.as_u32(5) { return Shape { height: convert.as_u32(2), capacity: 4 } }
            return Shape { height: convert.as_u32(3), capacity: 8 }
        }
        if length < convert.as_u32(17) { return Shape { height: convert.as_u32(4), capacity: 16 } }
        return Shape { height: convert.as_u32(5), capacity: 32 }
    }
    if length < convert.as_u32(65) { return Shape { height: convert.as_u32(6), capacity: 64 } }
    let mut capacity: Field = 128
    for height in 7..32 {
        if (convert.as_u32(capacity) < length) == false { return Shape { height, capacity } }
        capacity = capacity * 2
    }
    Shape { height: MAX_HEIGHT, capacity }
}

// Requires the canonical tree shape for length. Occupied leaves may be pairs.
#[pure]
#[requires(index < length)]
pub fn get(root: Noun, length: U32, index: U32) -> Noun {
    assert(index < length)
    if length == convert.as_u32(1) { return root }
    let mut cursor = root
    let mut offset = index
    let mut capacity = shape(length).capacity
    for level in 0..32 {
        // Resolve the final two levels without allocating their continuation.
        // Both low bits select branches; the returned leaf stays opaque.
        if capacity == 4 {
            if offset < convert.as_u32(2) {
                if offset == ZERO { return noun.head(noun.head(cursor)) }
                return noun.tail(noun.head(cursor))
            }
            if offset == convert.as_u32(2) { return noun.head(noun.tail(cursor)) }
            return noun.tail(noun.tail(cursor))
        }
        // An odd remaining height ends in three direct selections.
        if capacity == 8 {
            if offset < convert.as_u32(4) {
                if offset < convert.as_u32(2) {
                    if offset == ZERO { return noun.head(noun.head(noun.head(cursor))) }
                    return noun.tail(noun.head(noun.head(cursor)))
                }
                if offset == convert.as_u32(2) { return noun.head(noun.tail(noun.head(cursor))) }
                return noun.tail(noun.tail(noun.head(cursor)))
            }
            if offset < convert.as_u32(6) {
                if offset == convert.as_u32(4) { return noun.head(noun.head(noun.tail(cursor))) }
                return noun.tail(noun.head(noun.tail(cursor)))
            }
            if offset == convert.as_u32(6) { return noun.head(noun.tail(noun.tail(cursor))) }
            return noun.tail(noun.tail(noun.tail(cursor)))
        }
        // The final branch selects an opaque leaf directly. Returning here
        // avoids rebuilding loop state only to return on the next iteration.
        if capacity == 2 {
            if offset == ZERO { return noun.head(cursor) }
            return noun.tail(cursor)
        }
        capacity = capacity * HALF
        let half = convert.as_u32(capacity)
        if offset < half {
            cursor = noun.head(cursor)
        } else {
            cursor = noun.tail(cursor)
            offset = convert.as_u32(field.sub(convert.as_field(offset), capacity))
        }
        // The preceding terminal cases leave at least four levels here.
        // Consume a second branch before allocating the next continuation.
        capacity = capacity * HALF
        let quarter = convert.as_u32(capacity)
        if offset < quarter {
            cursor = noun.head(cursor)
        } else {
            cursor = noun.tail(cursor)
            offset = convert.as_u32(field.sub(convert.as_field(offset), capacity))
        }
    }
    assert_eq(0, 1)
    cursor
}

// A zipper stores [direction sibling] records, deepest first on reconstruction.
#[pure]
fn zipper(root: Noun, geometry: Shape, index: U32) -> Noun {
    let mut cursor = root
    let mut offset = index
    let mut capacity = geometry.capacity
    let mut path = noun.atom(0)
    for level in 0..32 {
        if level == geometry.height { return path }
        capacity = capacity * HALF
        let half = convert.as_u32(capacity)
        if offset < half {
            path = noun.pair(noun.pair(noun.atom(0), noun.tail(cursor)), path)
            cursor = noun.head(cursor)
        } else {
            path = noun.pair(noun.pair(noun.atom(1), noun.head(cursor)), path)
            cursor = noun.tail(cursor)
            offset = convert.as_u32(field.sub(convert.as_field(offset), capacity))
        }
    }
    path
}

#[pure]
#[requires(index < length)]
pub fn set(root: Noun, length: U32, index: U32, value: Noun) -> Noun {
    assert(index < length)
    if length == convert.as_u32(1) { return value }
    let geometry = shape(length)
    let mut path = zipper(root, geometry, index)
    let mut result = value
    for level in 0..32 {
        if level == geometry.height { return result }
        let step = noun.head(path)
        if noun.as_field(noun.head(step)) == 0 {
            result = noun.pair(result, noun.tail(step))
        } else {
            result = noun.pair(noun.tail(step), result)
        }
        path = noun.tail(path)
    }
    result
}

#[pure]
#[requires(length < max_length)]
pub fn push(root: Noun, length: U32, value: Noun, max_length: U32) -> Noun {
    assert(length < max_length)
    if length == ZERO { return value }
    let next = convert.as_u32(convert.as_field(length) + 1)
    let old_shape = shape(length)
    let next_shape = shape(next)
    let mut expanded = root
    if old_shape.height < next_shape.height {
        expanded = noun.pair(root, empty(old_shape.height))
    }
    set(expanded, next, length, value)
}

// Task = [node [occupied [capacity canonical_empty]]].
#[pure]
fn task(node: Noun, occupied: U32, capacity: Field, padding: Noun) -> Noun {
    noun.pair(node, noun.pair(noun.atom(convert.as_field(occupied)), noun.pair(noun.atom(capacity), padding)))
}

// Charge before each visit, even when identical children share arena storage.
// Each call unwinds its loop frames before the driver starts the next chunk.
#[pure]
fn validate_chunk(todo: Noun, remaining: U32) -> (Noun, U32) {
    let mut work = todo
    let mut budget = remaining
    for visit in 0..128 {
        if noun.eq(work, noun.atom(0)) { return (work, budget) }
        assert(ZERO < budget)
        budget = convert.as_u32(field.sub(convert.as_field(budget), 1))
        let current = noun.head(work)
        work = noun.tail(work)
        let node = noun.head(current)
        let body = noun.tail(current)
        let occupied = convert.as_u32(noun.as_field(noun.head(body)))
        let geometry = noun.tail(body)
        let capacity = noun.as_field(noun.head(geometry))
        let padding = noun.tail(geometry)
        if occupied == ZERO {
            assert(noun.eq(node, padding))
        } else {
            if capacity == 1 {
                // The entire Noun is the occupied value; do not descend into it.
            } else {
                if capacity == 2 {
                    // Check the branch while keeping arbitrary leaf Nouns opaque.
                    // Both leaf positions retain their visit charge, but need no
                    // traversal tasks or separate validator loop iterations.
                    assert(convert.as_u32(1) < budget)
                    budget = convert.as_u32(field.sub(convert.as_field(budget), 2))
                    assert(noun.eq(noun.pair(noun.head(node), noun.tail(node)), node))
                    if occupied == convert.as_u32(1) { assert(noun.eq(noun.tail(node), noun.atom(0))) }
                } else {
                    let half_capacity = capacity * HALF
                    let half = convert.as_u32(half_capacity)
                    let mut left_count = occupied
                    let mut right_count = ZERO
                    if half < occupied {
                        left_count = half
                        right_count = convert.as_u32(field.sub(convert.as_field(occupied), half_capacity))
                    }
                    let child_padding = noun.head(padding)
                    let right = task(noun.tail(node), right_count, half_capacity, child_padding)
                    let left = task(noun.head(node), left_count, half_capacity, child_padding)
                    work = noun.pair(left, noun.pair(right, work))
                }
            }
        }
    }
    (work, budget)
}

// Returns unspent visits for a caller's payload validation pass.
#[pure]
#[ensures((remaining < result) == false)]
pub fn validate(root: Noun, length: U32, remaining: U32) -> U32 {
    let geometry = shape(length)
    let initial = task(root, length, geometry.capacity, empty(geometry.height))
    let mut work = noun.pair(initial, noun.atom(0))
    let mut budget = remaining
    // ceil(U32::MAX / 128); every chunk consumes visits or returns/fails.
    for chunk in 0..33554432 {
        (work, budget) = validate_chunk(work, budget)
        if noun.eq(work, noun.atom(0)) { return budget }
    }
    assert_eq(0, 1)
    ZERO
}

